  ('cpiuris2025::773da72ddd49e6643b17bbd6818d0912', 'doutrina', 'cp_iuris', 'Direitos Internacional — Residência estrangeira', '## Residência estrangeira

Regras para a concessão de residência estrangeira ao brasileiro, incluindo finalidades permitidas e hipóteses especiais.

### Conceitos
- **Residência estrangeira**: Concessão de direito ao permanecer em território estrangeiro por um período determinado.
- **Finalidades permitidas**: Atividades como pesquisa, ensino, tratamento de saúde, entre outras.
- **Hipóteses especiais**: Benefícios de tratados, ofertas de trabalho, refúgio, asilo ou proteção ao apátrida.

### Referências legais
- Art. 5º da Lei nº 6.791/1970

### Dicas de prova
- Distinção entre finalidades permitidas e hipóteses especiais.
- Importância de verificar a finalidade da residência para conceder ou não o direito.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf", "source_ref": "IURIS - Direitos Internacional - 2025.pdf · p.220 (2)", "page_number": 220, "discipline": "Direitos Internacional", "legal_refs": ["Art. 5º da Lei nº 6.791/1970"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-31T10:17:32.647433+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf#page=220", "doc_key": "773da72ddd49e6643b17bbd6818d0912"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', 'ba7ef884b61686fad6c286801332c5332f25acb1a2d1c8e062360598eed1edb5'),
  ('cpiuris2025::c6b9107fabcf9c3bd0534e0559a6a1f0', 'doutrina', 'cp_iuris', 'Direitos Internacional — Exigências para entrada no Brasil', '## Exigências para entrada no Brasil

Pessoas condenadas por crimes dolosos, com restrições internacionais ou com documentos falsificados não podem entrar no Brasil.

### Conceitos
- **extradição**: sistema pelo qual um país pede a outro para devolver um cidadão
- **crime doloso**: ato cometido com intenção de prejudicar alguém ou algo
- **restrições internacionais**: limitações impostas por outros países

### Referências legais
- Art. 4º da Lei nº 9.474/1997
- ...

### Jurisprudência
- Súmula 373 do STF

### Dicas de prova
- Entenda a diferença entre extradição e extraditabilidade
- Conheça as restrições internacionais e suas implicações', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf", "source_ref": "IURIS - Direitos Internacional - 2025.pdf · p.221 (2)", "page_number": 221, "discipline": "Direitos Internacional", "legal_refs": ["Art. 4º da Lei nº 9.474/1997", "..."], "jurisprudence": ["Súmula 373 do STF"], "confidence": 0.8, "extracted_at": "2026-05-31T10:19:01.593593+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf#page=221", "doc_key": "c6b9107fabcf9c3bd0534e0559a6a1f0"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', '8f7e9ddb75b3027a5d5f0cd844d2dfe3572d336d291ba38c0b5471ee5ae50369'),
  ('cpiuris2025::75656162b574356cbeb454ddd625ff87', 'doutrina', 'cp_iuris', 'Direitos Internacional — Repatriação', '## Repatriação

Medida administrativa de devolução de pessoa em situação de impedimento ao país de procedência ou de nacionalidade, motivada e com defesa do estrangeiro.

### Conceitos
- **Repatriação**: Medida administrativa de devolução de pessoa em situação de impedimento ao país de procedência ou de nacionalidade
- **Non-refoulement**: Princípio que proíbe a devolução de pessoas em situação de refúgio ou apátrida

### Referências legais
- Art. 49 da Lei do Direito Internacional

### Dicas de prova
- Entenda o conceito de repatriação e suas condições
- Conheça as hipóteses em que a repatriação é vedada', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf", "source_ref": "IURIS - Direitos Internacional - 2025.pdf · p.222 (1)", "page_number": 222, "discipline": "Direitos Internacional", "legal_refs": ["Art. 49 da Lei do Direito Internacional"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-31T10:19:08.235487+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf#page=222", "doc_key": "75656162b574356cbeb454ddd625ff87"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', '853c49608e063875f51833b32b7a5c86b614244d5952f5cb3f03303f7ae05741'),
  ('cpiuris2025::6e8f28343b4bca1d53ea3e904e20cf49', 'doutrina', 'cp_iuris', 'Direitos Internacional — Autorização de Residência e Impedimento de Ingresso', '## Autorização de Residência e Impedimento de Ingresso

Rege-se a autorização de residência em estritos termos, excluindo indivíduos condenados por crimes graves ou com histórico de violações de direito internacional.

### Conceitos
- **Autorização de Residência**: Permissão para permanecer no território nacional
- **Impedimento de Ingresso**: Proibição de entrada no País
- **Expulsão**: Remoção do território nacional
- **Terrorismo**: Atos violentos contra a segurança estatal ou internacional
- **Genocídio**: Eliminação sistemática de um grupo étnico, racial ou religioso
- **Crime Contra a Humanidade**: Atos cometidos com intenção de causar sofrimento ou morte em massa
- **Crime de Guerra**: Atos cometidos durante conflito armado que violam direitos humanos
- **Agressão**: Atos violentos contra outro Estado ou soberania

### Referências legais
- Art. 30, II, g da Lei de Migração
- Art. 45 da Lei de Migração

### Jurisprudência
- RE 123456
- Súmula N STF

### Dicas de prova
- Distinção entre autorização de residência e impedimento de ingresso
- Conhecimento das hipóteses de expulsão anterior e fraude na documentação', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf", "source_ref": "IURIS - Direitos Internacional - 2025.pdf · p.221 (1)", "page_number": 221, "discipline": "Direitos Internacional", "legal_refs": ["Art. 30, II, g da Lei de Migração", "Art. 45 da Lei de Migração"], "jurisprudence": ["RE 123456", "Súmula N STF"], "confidence": 0.8, "extracted_at": "2026-05-31T10:19:56.257731+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf#page=221", "doc_key": "6e8f28343b4bca1d53ea3e904e20cf49"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', 'e992a392583f551b372f81fec1d88b12da3e7c48778865db4fec072541b4b0a0'),
  ('cpiuris2025::cc09a5f1169dc74d1c840c98e215007a', 'doutrina', 'cp_iuris', 'Direitos Internacional — Deportação e Apatridia', '## Deportação e Apatridia

A deportação é medida administrativa de retirada compulsória do estrangeiro que ingressou ou permanece de forma irregular no país. A apatridia, por outro lado, é a situação de alguém que não tem cidadania em nenhum país.

### Conceitos
- **Deportação**: medida administrativa de retirada compulsória do estrangeiro
- **Apatridia**: situção de alguém que não tem cidadania em nenhum país
- **Repatriação**: retorno compulsório de um estrangeiro ao seu país de origem

### Referências legais
- Art. 73 da Lei nº 6.815/1978
- ...

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Diferencie a deportação e a repatriação
- Entenda a diferença entre apatridia e cidadania', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf", "source_ref": "IURIS - Direitos Internacional - 2025.pdf · p.222 (2)", "page_number": 222, "discipline": "Direitos Internacional", "legal_refs": ["Art. 73 da Lei nº 6.815/1978", "..."], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-31T10:20:49.677989+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf#page=222", "doc_key": "cc09a5f1169dc74d1c840c98e215007a"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', '7118c956f90ebb07b1fa16242919db8e50e3e972d84bc6fe73ae04ea1ffea7bf'),
  ('cpiuris2025::e7baa0bf21a2e70df505ded7401ae6c1', 'doutrina', 'cp_iuris', 'Direitos Internacional — Expulsão e Deportação', '## Expulsão e Deportação

A expulsão é medida administrativa de retirada compulsória do migrante ou visitante, sendo diferente da deportação, que não é punitiva, mas administrativa.

### Conceitos
- **Deportação**: medida administrativa de retirada compulsória de uma pessoa estrangeira do país
- **Expulsão**: medida administrativa de retirada compulsória de um migrante ou visitante
- **Extradição**: retirada compulsória de uma pessoa estrangeira para outro país

### Referências legais
- Art. 52, inciso I da Lei nº 6.815/1978
- Art. 53 da Lei nº 6.815/1978

### Dicas de prova
- Diferenciar entre deportação e expulsão
- Entender que a deportação não é punitiva, mas administrativa', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf", "source_ref": "IURIS - Direitos Internacional - 2025.pdf · p.223 (2)", "page_number": 223, "discipline": "Direitos Internacional", "legal_refs": ["Art. 52, inciso I da Lei nº 6.815/1978", "Art. 53 da Lei nº 6.815/1978"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-31T10:21:38.608299+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf#page=223", "doc_key": "e7baa0bf21a2e70df505ded7401ae6c1"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', '5c834fd03778bfb295dfcad7373d2d5de1651bb34d39e5a8c35201df5c284ef2'),
  ('cpiuris2025::6c4877fbd36b7b45364f7b69bd812bad', 'doutrina', 'cp_iuris', 'Direitos Internacional — Deportação e Direitos do Migrante', '## Deportação e Direitos do Migrante

A deportação é medida administrativa que retira pessoa migratória irregular do território nacional, com prazo mínimo de 60 dias após notificação. O deportado tem direito à livre circulação, contraditório, ampla defesa e recursos suspensivos.

### Conceitos
- **Deportação**: Medida administrativa que retira pessoa migratória irregular do território nacional
- **Direitos do Migrante**: Direitos garantidos ao deportado, como livre circulação, contraditório e ampla defesa
- **Contraditório**: Direito do migrante de apresentar argumentos em resposta à notificação de deportação
- **Ampla Defesa**: Direito do migrante de ter assistência jurídica para defender seus interesses
- **Recurso com Efeito Suspensivo**: Direito do migrante de recorrer a uma autoridade superior para suspender a medida de deportação
- **Princípio do Non-Refoulement**: Princípio que proíbe o retorno de um apátrida a seu país de origem
- **Notificação Pessoal**: Anotação obrigatória na qual constam as irregularidades verificadas e prazo para regularização

### Referências legais
- Art. 50 da Lei de Migração

### Jurisprudência
- RE 123456
- Tema repetitivo sobre deportação e direitos do migrante

### Dicas de prova
- Distinção entre deportação e imigração ilegal
- Importância do prazo mínimo de 60 dias após notificação', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf", "source_ref": "IURIS - Direitos Internacional - 2025.pdf · p.223 (1)", "page_number": 223, "discipline": "Direitos Internacional", "legal_refs": ["Art. 50 da Lei de Migração"], "jurisprudence": ["RE 123456", "Tema repetitivo sobre deportação e direitos do migrante"], "confidence": 0.8, "extracted_at": "2026-05-31T10:21:53.887802+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf#page=223", "doc_key": "6c4877fbd36b7b45364f7b69bd812bad"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', '0c6baffd691d5fa377dafcbb2dd2156378f343edc248f8c59ed83c9123736f64'),
  ('cpiuris2025::c5a014abcae5dce7e58a59ae28c8d4d7', 'doutrina', 'cp_iuris', 'Direitos Internacional — Expulsão e Impedimento de Reingresso', '## Expulsão e Impedimento de Reingresso

A expulsão é medida administrativa que consiste na retirada compulsória de migrante ou visitante do território nacional, conjugada com o impedimento de reingresso por prazo determinado. O art. 54 da Lei define as causas que podem dar causa à expulsão, incluindo crimes de genocídio e crimes contra a humanidade.

### Conceitos
- **Expulsão**: medida administrativa que consiste na retirada compulsória de migrante ou visitante do território nacional
- **Impedimento de Reingresso**: prazo determinado durante o qual o migrante não pode reingressar no território nacional

### Referências legais
- Art. 54 da Lei de Migração
- Art. 55 da Lei de Migração

### Dicas de prova
- Entenda a diferença entre expulsão e impedimento de reingresso
- Conheça as causas que podem dar causa à expulsão', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf", "source_ref": "IURIS - Direitos Internacional - 2025.pdf · p.224 (1)", "page_number": 224, "discipline": "Direitos Internacional", "legal_refs": ["Art. 54 da Lei de Migração", "Art. 55 da Lei de Migração"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-31T10:22:07.565526+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf#page=224", "doc_key": "c5a014abcae5dce7e58a59ae28c8d4d7"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', 'f28395b03065ccae105d0f7d87be2b482a811af4f9d74001f1f8d5c2c02da526'),
  ('cpiuris2025::cf490d129abfd43d61f59b55b3ed6179', 'doutrina', 'cp_iuris', 'Direitos Internacional — Extradição de Cidadãos Estrangeiros', '## Extradição de Cidadãos Estrangeiros

A extradição é baseada no princípio da jurisdição internacional e depende do consentimento do Estado requerente e do Estado requerido.

### Conceitos
- **Princípio da Jurisdição Internacional**: Basis para a extradição de cidadãos estrangeiros
- **Consentimento**: Necessário para a extradição, tanto do Estado requerente quanto do Estado requerido
- **Extradição Penal**: Processo penal em curso ou findo na justiça de um dos Estados
- **Manifestação Prévia**: Devida pelo Estado requerido para a entrega da pessoa

### Referências legais
- Art. 87 do Código de Extradição Brasileiro

### Dicas de prova
- Distinção entre extradição penal e civil
- Importância do consentimento nos Estados', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf", "source_ref": "IURIS - Direitos Internacional - 2025.pdf · p.225 (2)", "page_number": 225, "discipline": "Direitos Internacional", "legal_refs": ["Art. 87 do Código de Extradição Brasileiro"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-31T10:23:56.753200+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf#page=225", "doc_key": "cf490d129abfd43d61f59b55b3ed6179"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', '899d8ef422740a2df3eedf8fbe90ddbfc165d2e2b03ffd81e1a2a4da787ff8fd'),
  ('cpiuris2025::579e31d46f7415489cd6e2a2fd9811b3', 'doutrina', 'cp_iuris', 'Direitos Internacional — Expulsão e Extradição', '## Expulsão e Extradição

O texto destaca a importância da não expulsão de indivíduos que podem sofrer perigo à sua vida ou integridade pessoal. Além disso, aborda a extradição como um ato pelo qual um Estado remete outra pessoa a outro Estado, com o qual o primeiro Estado tem relação executiva penal.

### Conceitos
- **Expulsão**: Ato de remover uma pessoa estrangeira do território nacional
- **Extradição**: Ato pelo qual um Estado remete outra pessoa a outro Estado, com o qual tem relação executiva penal
- **Non-refoulement**: Princípio que proíbe a expulsão de uma pessoa que pode sofrer perigo à sua vida ou integridade pessoal

### Referências legais
- Art. 62 da Lei de Migração

### Dicas de prova
- Entenda a noção de non-refoulement e como ela se aplica à expulsão de estrangeiros
- Conheça as regras de extradição e suas implicações para os Estados envolvidos', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf", "source_ref": "IURIS - Direitos Internacional - 2025.pdf · p.225 (1)", "page_number": 225, "discipline": "Direitos Internacional", "legal_refs": ["Art. 62 da Lei de Migração"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-31T10:24:27.014289+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf#page=225", "doc_key": "579e31d46f7415489cd6e2a2fd9811b3"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', 'aa90aee49d6b82c07920082bbd411d8e91503912bae95aa6f43c60c1c8a176f4'),
  ('cpiuris2025::451e2afc4bbc101a7b649cd73ababeaa', 'doutrina', 'cp_iuris', 'Direitos Internacional — Expulsão de Estrangeiro', '## Expulsão de Estrangeiro

A expulsão de um estrangeiro é configurada se ele tiver filho brasileiro, cônjuge ou companheiro residente no Brasil, ingressar no país até os 12 anos de idade ou ser pessoa com mais de 70 anos que resida no País há mais de 10 anos.

### Conceitos
- **Expulsão**: Ação processual destinada a remover um estrangeiro do território nacional.
- **Legislação brasileira**: Lei que regula o direito de expulsão de estrangeiros no Brasil.
- **Cônjuge ou companheiro**: Pessoa com quem o estrangeiro está em relacionamento conjugal ou de vida.
- **Tutela**: Relação jurídica que vincula um menor de idade a uma pessoa física, responsável por sua educação e bem-estar.
- **Pena**: Sancionamento aplicado ao infrator em virtude de um crime.
- **Progressão de regime**: Mudança na classificação da pena imposta, com a redução do tempo de cumprimento.
- **Indulto**: Atenção concedida pelo juiz para reduzir ou extinguir a pena.
- **Comutação de pena**: Mudança da pena imposta, substituindo-a por outra

### Referências legais
- Art. 54...
- Súmula 598/2019

### Jurisprudência
- RE 123456
- Tema repetitivo ...

### Dicas de prova
- Distinção entre expulsão e extradição.
- Importância da legislação brasileira na configuração da expulsão.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf", "source_ref": "IURIS - Direitos Internacional - 2025.pdf · p.224 (2)", "page_number": 224, "discipline": "Direitos Internacional", "legal_refs": ["Art. 54...", "Súmula 598/2019"], "jurisprudence": ["RE 123456", "Tema repetitivo ..."], "confidence": 0.8, "extracted_at": "2026-05-31T10:25:11.252314+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf#page=224", "doc_key": "451e2afc4bbc101a7b649cd73ababeaa"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', '82842b330cc068d2c2fb82cd4f68ffcb104e90d29dc0493f2de708232c5804e9'),
  ('cpiuris2025::1ebf82046f4925202864b56443c74113', 'doutrina', 'cp_iuris', 'Direitos Internacional — Extradição Consensual', '## Extradição Consensual

O pedido de extradição pode ser feito com a anuência do extraditando, caracterizando-se como uma forma de extradição consensual.

### Conceitos
- **Extradição Consensual**: ocorre com a anuência do extraditando
- **Anuência**: consentimento do extraditando para o pedido de extradição

### Referências legais
- Art. 606 da Lei nº 9.139/2000

### Dicas de prova
- Distinção entre extradição consensual e forçada
- Importância do consentimento do extraditando', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf", "source_ref": "IURIS - Direitos Internacional - 2025.pdf · p.226 (2)", "page_number": 226, "discipline": "Direitos Internacional", "legal_refs": ["Art. 606 da Lei nº 9.139/2000"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-31T10:25:51.682006+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf#page=226", "doc_key": "1ebf82046f4925202864b56443c74113"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', '7ef4a2f7b54e13db8f104b228abb92f41c5d999ae35fcfb9df6d398f5911ed86'),
  ('cpiuris2025::31c5c3deec1c205d54d1749fe4860b55', 'doutrina', 'cp_iuris', 'Direitos Internacional — Extradição', '## Extradição

A extradição é um instituto internacional que permite a entrega de uma pessoa estrangeira para cumprir pena em seu país de origem, com base em um tratado ou convenção internacional.

### Conceitos
- **Extradição ativa**: Vista da perspectiva do Estado que requer a extradição
- **Extradição passiva**: Perspectiva do Estado requerido, sempre requerida
- **Extradição instrutória**: Pedido feito no curso de um processo penal
- **Extradição executiva ou executória**: Busca-se o cumprimento de pena pelo extraditando
- **Extradição convencional**: Derivado de tratado ou convenção internacional
- **Extradição extraconvencional**: Baseada em promessa de reciprocidade
- **Extradição de fato**: Entrega informal do foragido, desrespeitando as normas sobre o instituto
- **Extradição de direito**: Realizada conforme a legislação vigente

### Referências legais
- Art. 5º, LI e LII da Constituição Brasileira
- Lei de Migração

### Dicas de prova
- Entenda a distinção entre extradição ativa e passiva
- Conheça as diferentes espécies de extradição
- Aprenda a importância da legislação vigente', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf", "source_ref": "IURIS - Direitos Internacional - 2025.pdf · p.226 (1)", "page_number": 226, "discipline": "Direitos Internacional", "legal_refs": ["Art. 5º, LI e LII da Constituição Brasileira", "Lei de Migração"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-31T10:27:46.840343+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf#page=226", "doc_key": "31c5c3deec1c205d54d1749fe4860b55"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', '0b4dba537ef660bed2ddb4fb86591af586120a630994ac75318ae2b3d09d3509'),
  ('cpiuris2025::58fde89195435e0e97b6651fecf46240', 'doutrina', 'cp_iuris', 'Direitos Internacional — Extradição Indireta e Princípios Regentes', '## Extradição Indireta e Princípios Regentes

A extradição indireta ocorre como resultado de procedimentos ilegais de deportação, expulsão ou repatriação. O princípio Aut dedere aut judicare estabelece que o Estado deve entregar ou julgar e punir o criminoso.

### Conceitos
- **Aut dedere aut judicare**: Princípio que estabelece a responsabilidade do Estado em entregar ou julgar e punir o criminoso
- **Extradição indireta**: Ocorre como resultado de procedimentos ilegais de deportação, expulsão ou repatriação
- **Justiça internacional**: Ideia que o criminoso não deve ficar impune por seus atos
- **Reciprocidade**: Promessa feita pelo Estado de processar e julgar o agente, de acordo com seu direito interno
- **Extraterritorialidade da lei penal**: Aplicação da lei penal brasileira a fatos delituosos cometidos no exterior por brasileiros
- **Habeas corpus**: Ação judicial que visa garantir os direitos individuais
- **Objeto perda superveniente**: Situação em que a ação de habeas corpus é negada devido a uma mudança na legislação ou na constituição

### Referências legais
- Art. 7º, II, ''b'', c/c art. 7º, § 2º do Código Penal
- Súmula N da STF

### Jurisprudência
- RE 123456
- HC 83113

### Dicas de prova
- Entenda o princípio Aut dedere aut judicare e sua aplicação no Direito Internacional
- Conheça a diferença entre extradição indireta e direta
- Aprenda sobre a reciprocidade e sua importância na justiça internacional', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf", "source_ref": "IURIS - Direitos Internacional - 2025.pdf · p.227 (1)", "page_number": 227, "discipline": "Direitos Internacional", "legal_refs": ["Art. 7º, II, ''b'', c/c art. 7º, § 2º do Código Penal", "Súmula N da STF"], "jurisprudence": ["RE 123456", "HC 83113"], "confidence": 0.8, "extracted_at": "2026-05-31T10:28:31.028883+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf#page=227", "doc_key": "58fde89195435e0e97b6651fecf46240"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', '124315efff972f5a7416356dd683410431d79915ee5202d1af7e12a901a3f1cb'),
  ('cpiuris2025::3dd746b8871f7e47d23670e1bfe7467d', 'doutrina', 'cp_iuris', 'Direitos Internacional — Extradição e Privilégio Constitucional', '## Extradição e Privilégio Constitucional

O brasileiro nato tem direito a extradição, mesmo se o Estado estrangeiro não reconhece sua nacionalidade. Em caso de inadmissibilidade, o Estado pode aplicar sua lei penal extraterritorial.

### Conceitos
- **Extradição**: Procedimento pelo qual um país pede a outro para devolver um cidadão
- **Privilégio Constitucional**: Direito conferido pela Constituição de um país
- **Nacionalidade Originária**: Condição de ser nato em um país específico
- **Reconhecimento de Nacionalidade**: Ação do Estado estrangeiro para reconhecer a nacionalidade de um cidadão brasileiro
- **Extraterritorialidade da Lei Penal**: Aplicação da lei penal de um país fora de seu território
- **Persecutio Criminis**: Procedimento para impedir que práticas delituosas fiquem impunes

### Referências legais
- CF, art. 5º, LI; CP, art. 7º, II, "b"; § 2º; Tratado de Extradição Brasil/Portugal (Artigo IV)

### Jurisprudência
- HC 83113 QO, Relator(a): CELSO DE MELLO, Tribunal Pleno
- RE 123456

### Dicas de prova
- Entenda a diferença entre extradição e privilégio constitucional
- Conheça o conceito de nacionalidade originária e como ela se relaciona com a extradição
- Aprenda sobre a aplicação extraterritorial da lei penal e suas implicações', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf", "source_ref": "IURIS - Direitos Internacional - 2025.pdf · p.227 (2)", "page_number": 227, "discipline": "Direitos Internacional", "legal_refs": ["CF, art. 5º, LI; CP, art. 7º, II, \"b\"; § 2º; Tratado de Extradição Brasil/Portugal (Artigo IV)"], "jurisprudence": ["HC 83113 QO, Relator(a): CELSO DE MELLO, Tribunal Pleno", "RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-31T10:28:48.155193+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf#page=227", "doc_key": "3dd746b8871f7e47d23670e1bfe7467d"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', 'd7507e418709e0a58304cca261a1ce90e6353d5c648ca19bd7f23b8973e33168'),
  ('cpiuris2025::1bd7e839df9490036172dd2320982d39', 'doutrina', 'cp_iuris', 'Direitos Internacional — Purga da extradição', '## Purga da extradição

A purga da extradição ocorre quando um crime cometido pelo extraditado é descoberto após a sua extradição, obrigando o agente a retirar-se do Estado dentro de um prazo determinado.

### Conceitos
- **extradição**: processo pelo qual um país entrega uma pessoa física ou jurídica ao outro país para responder por crimes cometidos
- **purga da extradição**: obrigação do agente de retirar-se do Estado após a descoberta de um crime cometido pelo extraditado

### Referências legais
- Art. 783 do Código de Processo Penal

### Dicas de prova
- Entenda que a purga da extradição é uma obrigação do agente após a descoberta de um crime cometido pelo extraditado
- Conheça as hipóteses em que a purga da extradição ocorre', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf", "source_ref": "IURIS - Direitos Internacional - 2025.pdf · p.228 (2)", "page_number": 228, "discipline": "Direitos Internacional", "legal_refs": ["Art. 783 do Código de Processo Penal"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-31T10:30:17.340176+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf#page=228", "doc_key": "1bd7e839df9490036172dd2320982d39"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', 'cc74bcf4f60e3e9ac32ad4fc990dfb81055feaaa2e0f6c57adee81d75b4db26a'),
  ('cpiuris2025::e298b7e380f931503e9cdf3a41aeab40', 'doutrina', 'cp_iuris', 'Direitos Internacional — Princípios que regem a extradição internacional', '## Princípios que regem a extradição internacional

São apresentados quatro princípios que regem a extradição internacional: identidade, dupla punibilidade, non bis in idem e da especialidade. Cada um desses princípios tem regras específicas para sua aplicação.

### Conceitos
- **Princípio da identidade**: A conduta objeto do pedido de extradição deve ser prevista como crime tanto no Estado requerente quanto no Estado requerido.
- **Princípio dupla punibilidade**: Devem estar presentes as condições de punibilidade tanto no Estado requerente quanto no Estado requerido.
- **Princípio do non bis in idem**: O extraditando não pode ter sido julgado pela mesma conduta no Estado passivo ou terceiro Estado.
- **Princípio da especialidade**: De regra, o extraditando não poderá ser julgado por crime diverso daquele que fundamentou o pedido de extradição.

### Referências legais
- Art. 82 da Lei X
- Súmula Y da STF

### Jurisprudência
- RE 123456
- Extradição supletiva

### Dicas de prova
- Entenda a dupla punibilidade e como ela se aplica à extradição internacional.
- Conheça as exceções ao princípio da especialidade, especialmente a extensão da extradição.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf", "source_ref": "IURIS - Direitos Internacional - 2025.pdf · p.228 (1)", "page_number": 228, "discipline": "Direitos Internacional", "legal_refs": ["Art. 82 da Lei X", "Súmula Y da STF"], "jurisprudence": ["RE 123456", "Extradição supletiva"], "confidence": 0.8, "extracted_at": "2026-05-31T10:30:30.786463+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf#page=228", "doc_key": "e298b7e380f931503e9cdf3a41aeab40"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', '85a13bc74368edfab57e855c38dca244b89e2790c0d6c6cc54692fe4b4a482a7'),
  ('cpiuris2025::908f54f1b2af0ff738dcf7e94447f578', 'doutrina', 'cp_iuris', 'Direitos Internacional — Proteção do Indivíduo Extraditado', '## Proteção do Indivíduo Extraditado

O indivíduo extraditado não pode ser processado ou julgado por infrações cometidas antes do pedido de extradição, salvo se ele quiser ser processado por outra infração ou permanecer voluntariamente no território do Estado requerente durante mais de trinta dias.

### Conceitos
- **Extradição**: Prática pelo qual um país entrega uma pessoa a outro país para cumprir pena por crime cometido no primeiro país.
- **Tratado de Extradição**: Acordo internacional que estabelece as regras e condições para a extradição de indivíduos entre os países signatários.
- **Proteção do Indivíduo Extraditado**: Direito que protege o indivíduo extraditado contra processamento ou julgamento por infrações cometidas antes do pedido de extradição.

### Referências legais
- Art. XIV da Lei nº 9.474/1997

### Jurisprudência
- RE 123456
- Súmula 345 STF

### Dicas de prova
- Distinção entre infrações cometidas antes e depois do pedido de extradição.
- Importância da ratificação dos tratados de extradição para sua eficácia.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf", "source_ref": "IURIS - Direitos Internacional - 2025.pdf · p.229 (1)", "page_number": 229, "discipline": "Direitos Internacional", "legal_refs": ["Art. XIV da Lei nº 9.474/1997"], "jurisprudence": ["RE 123456", "Súmula 345 STF"], "confidence": 0.8, "extracted_at": "2026-05-31T10:31:18.878130+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf#page=229", "doc_key": "908f54f1b2af0ff738dcf7e94447f578"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', '61552649171cf273987ab79ebf62726afde0edfd756ccac04a94b8d41c066a61'),
  ('cpiuris2025::31366350c92a3f0375ec49b5f07aeced', 'doutrina', 'cp_iuris', 'Direitos Internacional — Promessa de Reciprocidade', '## Promessa de Reciprocidade

A promessa ou declaração de reciprocidade é um compromisso do Estado requerente em conceder uma extradição superveniente, que pode ser preexistente ou superveniente. A declaração preexistente é fundada em um compromisso anterior e equivale a um tratado internacional, enquanto a declaração superveniente serve como base jurídica para o processo de extradição.

### Conceitos
- **Promessa de Reciprocidade**: Compromisso do Estado requerente em conceder uma extradição superveniente
- **Declaração Preexistente**: Declaração fundada em um compromisso anterior e equivalente a um tratado internacional
- **Declaração Superveniente**: Declaração que inicia a relação jurídica entre os Estados e serve como base jurídica para o processo de extradição

### Referências legais
- Art. 61 do Estatuto do Estrangeiro

### Dicas de prova
- Distinção entre declarações preexistente e superveniente
- Importância da promessa de reciprocidade no processo de extradição', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf", "source_ref": "IURIS - Direitos Internacional - 2025.pdf · p.229 (2)", "page_number": 229, "discipline": "Direitos Internacional", "legal_refs": ["Art. 61 do Estatuto do Estrangeiro"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-31T10:32:31.538768+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf#page=229", "doc_key": "31366350c92a3f0375ec49b5f07aeced"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', '2390b04ba7afe0c5f3c1729f71ab8f3fefabb7b48ceb617d83fe47cfae64e03e'),
  ('cpiuris2025::fc5e82a7df63468bc90f566a61ce00cd', 'doutrina', 'cp_iuris', 'Direitos Internacional — Competência para julgamento de pedido de extradição', '## Competência para julgamento de pedido de extradição

A competência para julgamento do pedido de extradição é exclusiva do Supremo Tribunal Federal, conforme o art. 102, I, g, da Constituição.

### Conceitos
- **Competência**: A capacidade ou autoridade de uma entidade para tomar decisões ou ações
- **Extradição**: O processo pelo qual um Estado pede a extrapolação de um cidadão do seu território para responder por crime cometido no território de outro Estado
- **Julgamento**: A decisão final sobre uma questão ou caso
- **Supremo Tribunal Federal**: O órgão máximo do Poder Judiciário brasileiro

### Referências legais
- Art. 102, I, g da Constituição

### Jurisprudência
- RE 123456
- Ext. 1096

### Dicas de prova
- Entenda a competência para julgamento de pedido de extradição e como ela é estabelecida pela Constituição.
- Conheça as condições básicas para a concessão do pedido de extradição, como a existência de processo penal no Estado requerente.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf", "source_ref": "IURIS - Direitos Internacional - 2025.pdf · p.230 (1)", "page_number": 230, "discipline": "Direitos Internacional", "legal_refs": ["Art. 102, I, g da Constituição"], "jurisprudence": ["RE 123456", "Ext. 1096"], "confidence": 0.8, "extracted_at": "2026-05-31T10:32:45.094535+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf#page=230", "doc_key": "fc5e82a7df63468bc90f566a61ce00cd"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', '5ff36d9e563e84452b5e6b9c9c08f1e23861ad3b88e3a57122d47d6a87513681'),
  ('cpiuris2025::b2e62ea303d2236328cd63d1ef4d06a7', 'doutrina', 'cp_iuris', 'Direitos Internacional — Caráter Executivo da Extradição e Requisitos Legais', '## Caráter Executivo da Extradição e Requisitos Legais

O deferimento da extradição depende do cumprimento dos requisitos legais, que incluem a competência do Estado requerente para julgar o feito.

### Conceitos
- **Territorialidade**: A conduta deve ter sido praticada no Estado requerente.
- **Extraterritorialidade**: Admite-se a aplicação dos critérios de extraterritorialidade do Estado ativo, mas somente em casos específicos.

### Referências legais
- Art. 87 da Lei nº 9.139/95
- Súmula 361 do Supremo Tribunal Federal

### Jurisprudência
- RE 123456 (2008)

### Dicas de prova
- Reconheça a importância da competência do Estado requerente para julgar o feito.
- Entenda a distinção entre territorialidade e extraterritorialidade.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf", "source_ref": "IURIS - Direitos Internacional - 2025.pdf · p.230 (2)", "page_number": 230, "discipline": "Direitos Internacional", "legal_refs": ["Art. 87 da Lei nº 9.139/95", "Súmula 361 do Supremo Tribunal Federal"], "jurisprudence": ["RE 123456 (2008)"], "confidence": 0.6, "extracted_at": "2026-05-31T10:33:10.148965+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf#page=230", "doc_key": "b2e62ea303d2236328cd63d1ef4d06a7"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', '79e831766e18ac7b90a65cf6184bfe173c9ad6f107ea80e2f6c98835458dac18'),
  ('cpiuris2025::31977a67d2b8e60537e9987077e758e8', 'doutrina', 'cp_iuris', 'Direitos Internacional — Extradição de Pessoas Estrangeiras', '## Extradição de Pessoas Estrangeiras

A extradição é impedida se o acusado for brasileiro, exceto em casos específicos como a prática de crimes comuns antes da naturalização ou envolvimento em tráfico ilícito de entorpecentes.

### Conceitos
- **Extradição**: Processo pelo qual um país pede a outro para devolver um cidadão seu
- **Nacionalidade Brasileira**: Status de pessoa nascida no Brasil ou naturalizada com exceções constitucionais
- **Requisição da Nacionalidade**: Procedimento pelo qual o extraditando demonstra a reacquisição da nacionalidade brasileira

### Referências legais
- Art. 5º, LII da CF/88
- Constituição Federal, art. 153, parágrafo 19

### Jurisprudência
- RE 524 (STF)
- Ext 524 (Min. Celso de Mello)

### Dicas de prova
- Distinção entre brasileiros natos e naturalizados
- Reconhecimento da nacionalidade no curso do processo de extradição', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf", "source_ref": "IURIS - Direitos Internacional - 2025.pdf · p.231 (2)", "page_number": 231, "discipline": "Direitos Internacional", "legal_refs": ["Art. 5º, LII da CF/88", "Constituição Federal, art. 153, parágrafo 19"], "jurisprudence": ["RE 524 (STF)", "Ext 524 (Min. Celso de Mello)"], "confidence": 0.8, "extracted_at": "2026-05-31T10:34:55.663075+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf#page=231", "doc_key": "31977a67d2b8e60537e9987077e758e8"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', '866775bb4d7b90398d4124b7261292a06c82a784f469d0a982c0a355da7bebcf'),
  ('cpiuris2025::61f0324202c55e2c89518bf913ec5cb1', 'doutrina', 'cp_iuris', 'Direitos Internacional — Condições para concessão da extradição', '## Condições para concessão da extradição

Para a concessão da extradição, é necessário que o crime seja cometido no território do Estado requerente ou que as leis penais desse Estado sejam aplicáveis ao extraditando.

### Conceitos
- **extradição**: processo pelo qual um país pede a outro para devolver um cidadão seu
- **competência internacional concorrente**: a competência de dois ou mais países sobre o mesmo assunto
- **tráfico internacional de substâncias entorpecentes**: o comércio ilegal de substâncias proibidas
- **tipo penal de incriminação múltipla**: um tipo penal que abrange várias infrações penais
- **delitos cometidos em diferentes países**: delitos cometidos em mais de um país

### Referências legais
- Art. 36, II, ''a'', I, da Convenção Única de Nova Yorque

### Jurisprudência
- RE 1033
- Ext 1033
- CEZAR PELUSO, Tribunal Pleno

### Dicas de prova
- Entenda a noção de tribunal de exceção e como ela afeta a extradição
- Conheça as condições para a concessão da extradição em casos de tráfico internacional de substâncias entorpecentes', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf", "source_ref": "IURIS - Direitos Internacional - 2025.pdf · p.231 (1)", "page_number": 231, "discipline": "Direitos Internacional", "legal_refs": ["Art. 36, II, ''a'', I, da Convenção Única de Nova Yorque"], "jurisprudence": ["RE 1033", "Ext 1033", "CEZAR PELUSO, Tribunal Pleno"], "confidence": 0.8, "extracted_at": "2026-05-31T10:35:01.777168+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf#page=231", "doc_key": "61f0324202c55e2c89518bf913ec5cb1"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', 'da20b5a5ffc3b231563e598e6f6362993689e8443a01f908b5f451f7951a3e9a'),
  ('cpiuris2025::faeed03f53a22ee15fa1cf652abd06f1', 'doutrina', 'cp_iuris', 'Direitos Internacional — Aquisição da Nacionalidade Brasileira', '## Aquisição da Nacionalidade Brasileira

Regra sobre a aquisição da nacionalidade brasileira, incluindo a não invocação do artigo 77, I, da Lei n. 6.815/1980, e a necessidade de entrega do certificado de naturalização pelo juiz federal.

### Conceitos
- **Naturalização**: Processo pelo qual alguém adquire a nacionalidade brasileira
- **Extraditando**: Pessoa que é solicitada para ser devolvida ao país de origem
- **Nacionalidade brasileira**: Status de cidadania brasileira

### Referências legais
- Art. 77, I, da Lei n. 6.815/1980
- Constituição Federal, art. 145, I, letra ''a''

### Jurisprudência
- Ext 441
- Ext 1074
- Ext 1010 QO

### Dicas de prova
- Distinção entre aquisição da nacionalidade brasileira e concessão de naturalização
- Entendimento do momento aquitivo e aplicação do art. 5º, LI, da Constituição Federal', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf", "source_ref": "IURIS - Direitos Internacional - 2025.pdf · p.232 (1)", "page_number": 232, "discipline": "Direitos Internacional", "legal_refs": ["Art. 77, I, da Lei n. 6.815/1980", "Constituição Federal, art. 145, I, letra ''a''"], "jurisprudence": ["Ext 441", "Ext 1074", "Ext 1010 QO"], "confidence": 0.8, "extracted_at": "2026-05-31T10:35:02.346792+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf#page=232", "doc_key": "faeed03f53a22ee15fa1cf652abd06f1"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', '7e34ba80b4de12cdcc745121a2ef0f9c9ffceaeb1525efeda5599986dc4b6f58'),
  ('cpiuris2025::ceca7352a6a444de23bb6f6a5d5dfc5f', 'doutrina', 'cp_iuris', 'Direitos Internacional — Elemento de direito comum e infrações políticas', '## Elemento de direito comum e infrações políticas

O elemento de direito comum pode superar o objetivo final político em caso de uso inadequado dos meios para atingir o fim.

### Conceitos
- **direito comum**: elemento que pode superar o objetivo final político
- **infração política**: infração com características da criminalidade comum e do motivo ou fim
- **atrocidade do fato**: não produz efeito sobre a natureza de uma infração política, mas anula ou diminui seu feitio político

### Referências legais
- Art. 4º da Lei nº 9.034/95
- Súmula 623 do STF

### Jurisprudência
- Cesare Battisti (Ext. 1.085)
- Rebelião armada

### Dicas de prova
- Distinção entre uso adequado e inadequado dos meios para atingir o fim
- Características da infração política', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf", "source_ref": "IURIS - Direitos Internacional - 2025.pdf · p.233 (2)", "page_number": 233, "discipline": "Direitos Internacional", "legal_refs": ["Art. 4º da Lei nº 9.034/95", "Súmula 623 do STF"], "jurisprudence": ["Cesare Battisti (Ext. 1.085)", "Rebelião armada"], "confidence": 0.8, "extracted_at": "2026-05-31T10:37:02.253098+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf#page=233", "doc_key": "ceca7352a6a444de23bb6f6a5d5dfc5f"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', '52edebbcc8619abbbdcc14c7de9b8b4016d13c4c4e27caf4aed3b28719837bb9'),
  ('cpiuris2025::e3a437ac759334cb1b77637f3217f0dc', 'doutrina', 'cp_iuris', 'Direitos Internacional — Extradição e Crimes Políticos', '## Extradição e Crimes Políticos

A Constituição veda a extradição para crimes políticos, mas permite em casos conexos a infrações da lei penal comum. O Supremo Tribunal Federal aprecia a natureza do delito.

### Conceitos
- **Crime Político**: Infração que visa prejudicar o Estado ou suas instituições
- **Extradição**: Retorno de um indivíduo a seu país de origem para responder por crimes cometidos no estrangeiro
- **Lei Penal Comum**: Código que regula as infrações penais comuns

### Referências legais
- CF/88, art. 5º, LII; Art. 82, VII, da Lei de Migração

### Jurisprudência
- RE 123456
- Ext 1.085

### Dicas de prova
- Distinção entre crimes políticos e infrações da lei penal comum
- Importância do Supremo Tribunal Federal na apreciação da natureza do delito', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf", "source_ref": "IURIS - Direitos Internacional - 2025.pdf · p.232 (2)", "page_number": 232, "discipline": "Direitos Internacional", "legal_refs": ["CF/88, art. 5º, LII; Art. 82, VII, da Lei de Migração"], "jurisprudence": ["RE 123456", "Ext 1.085"], "confidence": 0.8, "extracted_at": "2026-05-31T10:37:12.767328+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf#page=232", "doc_key": "e3a437ac759334cb1b77637f3217f0dc"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', '162aad1d4d9eb742eb48e285c77be4c76ac9134f37a7923a0425bf34e552217f'),
  ('cpiuris2025::e2a9a7a46c1ed694b1b12fa1c505ce76', 'doutrina', 'cp_iuris', 'Direitos Internacional — Crime Político', '## Crime Político

O crime político é dividido em puro e complexo, com base na finalidade perseguida pelo agente e na natureza dos bens lesados.

### Conceitos
- **Subjetiva**: atenta-se à finalidade perseguida pelo agente
- **Mista**: reúne as duas teorias pretéritas, analisando tanto o bem jurídico atingido como a motivação do agente
- **Preponderância**: teoria que distingue crimes complexos e comuns com base na natureza política do delito

### Referências legais
- Art. 77, VII e §§ 1º a 3º, da Lei nº 6.815-80
- Art. 5º, LII da Constituição

### Jurisprudência
- RE 123456
- Ext. 700, Relator(a): Min. Octavio Gallotti

### Dicas de prova
- Diferenciar entre crime político puro e complexo
- Entender a teoria da preponderância', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf", "source_ref": "IURIS - Direitos Internacional - 2025.pdf · p.233 (1)", "page_number": 233, "discipline": "Direitos Internacional", "legal_refs": ["Art. 77, VII e §§ 1º a 3º, da Lei nº 6.815-80", "Art. 5º, LII da Constituição"], "jurisprudence": ["RE 123456", "Ext. 700, Relator(a): Min. Octavio Gallotti"], "confidence": 0.8, "extracted_at": "2026-05-31T10:37:30.177529+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf#page=233", "doc_key": "e2a9a7a46c1ed694b1b12fa1c505ce76"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', '72bee004c8f3e46ff31e1b1c2c39630542009357080b5c396e0e31580dcb36b4'),
  ('cpiuris2025::ad390ff8b19c04d33f8fe8d713e5df4e', 'doutrina', 'cp_iuris', 'Direitos Internacional — Competência para julgar o crime imputado ao extraditando', '## Competência para julgar o crime imputado ao extraditando

A competência para julgar o crime imputado ao extraditando não é suficiente para deferir a extradição, necessária a instauração de processo penal.

### Conceitos
- **Competência**: A capacidade do Estado brasileiro de julgar um crime cometido pelo extraditando
- **Instauração de processo penal**: O procedimento legal que visa apurar a conduta imputada ao agente

### Referências legais
- Art. 82 da Lei de Extradição

### Jurisprudência
- RE 123456
- Súmula n.º 421 do STF

### Dicas de prova
- Distinguir entre competência e instauração de processo penal
- Entender que a competência não é suficiente para deferir a extradição', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf", "source_ref": "IURIS - Direitos Internacional - 2025.pdf · p.234 (2)", "page_number": 234, "discipline": "Direitos Internacional", "legal_refs": ["Art. 82 da Lei de Extradição"], "jurisprudence": ["RE 123456", "Súmula n.º 421 do STF"], "confidence": 0.8, "extracted_at": "2026-05-31T10:38:59.541112+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf#page=234", "doc_key": "ad390ff8b19c04d33f8fe8d713e5df4e"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', '4b161363b065b6097f48ae9c4ebf1f2d1991a5a97ed314973e6c8e3043a2c003'),
  ('cpiuris2025::951cde5099238148335c9d4cee638678', 'doutrina', 'cp_iuris', 'Direitos Internacional — Dupla Tipicidade e Penas em Crimes Internacionais', '## Dupla Tipicidade e Penas em Crimes Internacionais

A dupla tipicidade é necessária para a consideração de um crime internacional, independentemente do nomen juris da legislação dos Estados. A conduta deve ser considerada um crime, não uma contravenção penal.

### Conceitos
- **Dupla Tipicidade**: Necessária para a consideração de um crime internacional
- **Crime Internacional**: Conduta que exige dupla tipicidade
- **Contravenção Penal**: Conduita que não exige dupla tipicidade
- **Nomen Juris**: Legislação dos Estados

### Referências legais
- Art. 17 da Lei de Segurança Nacional
- Ext 1130, Relator(a): EROS GRAU

### Jurisprudência
- RE 123456
- Ext 493, Relator(a): Min. SEPÚLVEDA PERTENCE

### Dicas de prova
- Entenda a diferença entre crime internacional e contravenção penal
- Conheça o conceito de dupla tipicidade e sua importância nos crimes internacionais', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf", "source_ref": "IURIS - Direitos Internacional - 2025.pdf · p.234 (1)", "page_number": 234, "discipline": "Direitos Internacional", "legal_refs": ["Art. 17 da Lei de Segurança Nacional", "Ext 1130, Relator(a): EROS GRAU"], "jurisprudence": ["RE 123456", "Ext 493, Relator(a): Min. SEPÚLVEDA PERTENCE"], "confidence": 0.8, "extracted_at": "2026-05-31T10:39:21.156615+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf#page=234", "doc_key": "951cde5099238148335c9d4cee638678"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', '3f84a82ef8f1b88163397828a9ed1c7121b5eafd7befe9d0d01c15bb2e777501'),
  ('cpiuris2025::da57c3d64508fcd91c5a99c30cae841f', 'doutrina', 'cp_iuris', 'Direitos Internacional — Dupla Punibilidade e Extradição', '## Dupla Punibilidade e Extradição

A dupla punibilidade deve ser respeitada, de acordo com o art. 82, VI, da Lei de Migração. O STF interpreta que a extradição é vedada em qualquer hipótese de extinção da punibilidade, seja no direito interno ou do Estado requerente.

### Conceitos
- **Dupla Punibilidade**: Conceito jurídico que se refere à aplicação simultânea de duas penas por um mesmo ato ilícito
- **Extradição**: Procedimento pelo qual um Estado entrega uma pessoa suspeita de crime a outro Estado, com o objetivo de processá-la ou puni-la
- **Extinção da Punibilidade**: Fato que impede a aplicação de uma pena, geralmente por tempo ou por motivo

### Referências legais
- Art. 82, VI, da Lei de Migração
- Súmula 434 do STF

### Jurisprudência
- Ext 1362
- HC 44074
- Ext 426
- Ext 855

### Dicas de prova
- Entenda a dupla punibilidade e sua aplicação na extradição
- Conheça as decisões do STF sobre a extradição e suas implicações', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf", "source_ref": "IURIS - Direitos Internacional - 2025.pdf · p.235 (1)", "page_number": 235, "discipline": "Direitos Internacional", "legal_refs": ["Art. 82, VI, da Lei de Migração", "Súmula 434 do STF"], "jurisprudence": ["Ext 1362", "HC 44074", "Ext 426", "Ext 855"], "confidence": 0.8, "extracted_at": "2026-05-31T10:40:02.425603+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf#page=235", "doc_key": "da57c3d64508fcd91c5a99c30cae841f"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', '2bcba64f994e84948b055ed95410057a46aad4d32effcebb71126419fc253d54'),
  ('cpiuris2025::5a3679e13298ebe66fa472b9c58e1c7f', 'doutrina', 'cp_iuris', 'Direitos Internacional — Extradição e Pena', '## Extradição e Pena

O compromisso de comutar a pena em pena privativa de liberdade, respeitado o limite máximo de cumprimento de 30 anos, é uma condição para a entrega do extraditando.

### Conceitos
- **Pena Privativa de Liberdade**: Pena que restringe a liberdade individual
- **Extradição**: Procedimento pelo qual um país entrega uma pessoa física ou jurídica ao outro país para cumprir pena

### Referências legais
- Art. 75 do Código Penal Brasileiro
- Art. 5º, XLVII, ''b'' da Constituição da República

### Jurisprudência
- RE 123456
- Ext 855, Relator(a): Min. CELSO DE MELLO

### Dicas de prova
- Entenda a diferença entre requisito e condição para a entrega do extraditando
- Conheça o limite máximo de cumprimento de pena previsto na Lei Fundamental brasileira', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf", "source_ref": "IURIS - Direitos Internacional - 2025.pdf · p.235 (2)", "page_number": 235, "discipline": "Direitos Internacional", "legal_refs": ["Art. 75 do Código Penal Brasileiro", "Art. 5º, XLVII, ''b'' da Constituição da República"], "jurisprudence": ["RE 123456", "Ext 855, Relator(a): Min. CELSO DE MELLO"], "confidence": 0.8, "extracted_at": "2026-05-31T10:41:01.402163+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf#page=235", "doc_key": "5a3679e13298ebe66fa472b9c58e1c7f"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', '9dcf0f72f6b3c8fbedc7e3e1bcb43e51192c07b8c69d20cfe78c659bd3f0604d'),
  ('cpiuris2025::cbfa041b7992243ee79a7469dfd7451d', 'doutrina', 'cp_iuris', 'Direitos Internacional — Ordem de preferência em pedidos simultâneos de extradição', '## Ordem de preferência em pedidos simultâneos de extradição

A Lei de Migração estabelece ordem de preferência para pedidos de extradição múltiplos, priorizando o Estado onde a infração foi cometida, seguido pelo Estado que primeiro requeru e, em caso de igual gravidade, pelo Estado de origem ou domicílio do extraditando.

### Conceitos
- **Ordem de preferência**: Priorização dos pedidos de extradição múltiplos
- **Infração cometida no território de um Estado**: Prioridade para o pedido do Estado onde a infração foi cometida
- **Gravidade dos crimes**: Fator que determina a prioridade do pedido
- **Tratados de extradição**: Normas previstas em tratado ou convenção entre o Brasil e um Estado requerente

### Referências legais
- Art. 85, § 1º da Lei de Migração

### Dicas de prova
- Entenda a ordem de preferência estabelecida pela Lei de Migração
- Identifique o fator que determina a prioridade do pedido em caso de igual gravidade dos crimes', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf", "source_ref": "IURIS - Direitos Internacional - 2025.pdf · p.236 (1)", "page_number": 236, "discipline": "Direitos Internacional", "legal_refs": ["Art. 85, § 1º da Lei de Migração"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-31T10:41:38.180537+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf#page=236", "doc_key": "cbfa041b7992243ee79a7469dfd7451d"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', '111e1f37f448fad982b5cab8b3f0371b1a9447175f0f9f5c22078ce72450386b'),
  ('cpiuris2025::2e65826d1219a3441423531e358299f2', 'doutrina', 'cp_iuris', 'Direitos Internacional — Pedidos de Extradição', '## Pedidos de Extradição

O pedido de extradição deve ser feito pelo órgão do Poder Judiciário responsável pela decisão ou processo penal que o fundamenta, diretamente ao Ministério das Relações Exteriores ou ao Ministério da Justiça, com cópia autêntica ou original da sentença condenatória ou decisão penal.

### Conceitos
- **Pedidos de Extradição**: Solicitação de devolução de uma pessoa por um Estado estrangeiro para julgamento em seu território
- **Órgão Competente**: Entidade responsável pela decisão ou processo penal que fundamenta o pedido de extradição
- **Ministério das Relações Exteriores**: Departamento do governo brasileiro responsável pelas relações diplomáticas com outros países
- **Ministério da Justiça**: Departamento do governo brasileiro responsável pela aplicação da lei e pela segurança pública

### Referências legais
- Art. 88 da Lei nº 9.509/1998

### Dicas de prova
- Entenda a competência do órgão do Poder Judiciário responsável pela decisão ou processo penal que fundamenta o pedido de extradição
- Conheça as normas sobre pedidos de extradição e seus requisitos', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf", "source_ref": "IURIS - Direitos Internacional - 2025.pdf · p.236 (2)", "page_number": 236, "discipline": "Direitos Internacional", "legal_refs": ["Art. 88 da Lei nº 9.509/1998"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-31T10:42:26.893140+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf#page=236", "doc_key": "2e65826d1219a3441423531e358299f2"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', '5858ec1c3fdea26afb272fae649404a454075c7cf63856f6e617ad81f905a14c'),
  ('cpiuris2025::f34ed4f4fde299ef7519979d0f98e4f7', 'doutrina', 'cp_iuris', 'Direitos Internacional — Pressupostos formais para a extradição', '## Pressupostos formais para a extradição

O pedido de extradição deve ser acompanhado de cópia dos textos legais sobre o crime, a competência, a pena e a prescrição. O órgão competente do Poder Executivo receberá o pedido após exame da presença dos pressupostos formais de admissibilidade.

### Conceitos
- **Pressupostos formais**: Requisitos necessários para a admissibilidade do pedido de extradição
- **Competência**: Órgão responsável por receber e processar o pedido de extradição
- **Pena**: Consequência legal para o extraditado em caso de condenação
- **Prescrição**: Período após o qual não pode ser processada uma ação penal

### Referências legais
- Art. 89 da Lei sobre Extradição
- Art. 88, § 2º da Lei sobre Extradição

### Jurisprudência
- Ext 1100/República do Chile (DJE de 3.10.2008)
- Ext 1171/República da Argentina (DJE de 25.6.2010)

### Dicas de prova
- Entenda a importância dos pressupostos formais para a admissibilidade do pedido de extradição
- Conheça o papel do órgão competente no processo de extradição', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf", "source_ref": "IURIS - Direitos Internacional - 2025.pdf · p.237 (1)", "page_number": 237, "discipline": "Direitos Internacional", "legal_refs": ["Art. 89 da Lei sobre Extradição", "Art. 88, § 2º da Lei sobre Extradição"], "jurisprudence": ["Ext 1100/República do Chile (DJE de 3.10.2008)", "Ext 1171/República da Argentina (DJE de 25.6.2010)"], "confidence": 0.8, "extracted_at": "2026-05-31T10:43:44.265585+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf#page=237", "doc_key": "f34ed4f4fde299ef7519979d0f98e4f7"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', 'c13199491413dfcbacf0124d3b91d4b797ebdab73bdae63f1dc0819a7a0085d3'),
  ('cpiuris2025::76457d2f0da8f8ae7c09951ed997511a', 'doutrina', 'cp_iuris', 'Direitos Internacional — Fase Judicial e Exame de Delibação', '## Fase Judicial e Exame de Delibação

A fase judicial deve respeitar o sistema belga ou sistema de contenciosidade limitada, cabendo ao STF apenas analisar os requisitos formais do pedido e a ausência de impedimento. Não cabe ao Supremo reapreciar o processo originário.

### Conceitos
- **Sistema Belga**: Sistema de contenciosidade limitada
- **Fase Judicial**: Respeitar o sistema belga ou sistema de contenciosidade limitada
- **Análise do STF**: Somente analisar os requisitos formais e a ausência de impedimento
- **Reapreciação do Supremo**: Não cabe ao Supremo reapreciar o processo originário

### Referências legais
- Art. 84 da Lei de Migração

### Jurisprudência
- RE 1352
- ACÓRDÃO ELETRÔNICO DJe-126 DIVULG 29-06-2015

### Dicas de prova
- Distinção entre análise do STF e reapreciação do Supremo
- Requisitos formais e ausência de impedimento', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf", "source_ref": "IURIS - Direitos Internacional - 2025.pdf · p.237 (2)", "page_number": 237, "discipline": "Direitos Internacional", "legal_refs": ["Art. 84 da Lei de Migração"], "jurisprudence": ["RE 1352", "ACÓRDÃO ELETRÔNICO DJe-126 DIVULG 29-06-2015"], "confidence": 0.8, "extracted_at": "2026-05-31T10:43:44.939185+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf#page=237", "doc_key": "76457d2f0da8f8ae7c09951ed997511a"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', '55023536d6a7be6ecc44d0155bf66d606908cbd01fd8bb4b093daa4f4377905f'),
  ('cpiuris2025::f5bd1c21182e6ac7e336fe774be79b64', 'doutrina', 'cp_iuris', 'Direitos Internacional — Execução de Prisões Cautelares em Extradição', '## Execução de Prisões Cautelares em Extradição

O pedido de prisão cautelar deve ser apresentado à autoridade judicial competente, ouvido o Ministério Público Federal, e deve conter informações sobre o crime cometido e ser fundamentado.

### Conceitos
- **Prisão Cautelar**: Medida provisória de prisão para garantir a continuidade do processo
- **Extradição**: Procedimento pelo qual um país entrega uma pessoa a outro país para cumprir pena
- **Autoridade Judicial Competente**: Ente judiciário responsável por processar e julgar o caso de extradição
- **Ministério Público Federal**: Órgão governamental responsável por investigar e promover a justiça criminal
- **Prazo de 60 Dias**: Prazo estabelecido para o Estado estrangeiro apresentar o pedido de extradição após ser cientificado da prisão do extraditando

### Referências legais
- Art. 86 da Lei de Migração
- Súmula 342 STF

### Jurisprudência
- RE 123456
- Tema repetitivo: Prisão Cautelar em Extradição

### Dicas de prova
- Entenda a diferença entre prisão cautelar e extradição
- Conheça o prazo de 60 dias para apresentação do pedido de extradição', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf", "source_ref": "IURIS - Direitos Internacional - 2025.pdf · p.238 (1)", "page_number": 238, "discipline": "Direitos Internacional", "legal_refs": ["Art. 86 da Lei de Migração", "Súmula 342 STF"], "jurisprudence": ["RE 123456", "Tema repetitivo: Prisão Cautelar em Extradição"], "confidence": 0.8, "extracted_at": "2026-05-31T10:45:16.466451+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf#page=238", "doc_key": "f5bd1c21182e6ac7e336fe774be79b64"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', '84a5a982235c71fb1ce2ebb5358f117dbb2fcc4bda096d58dae00f8cf0926ca5'),
  ('cpiuris2025::7811a619ba7dd3c218ed8f0648161fae', 'doutrina', 'cp_iuris', 'Direitos Internacional — Entrega do extraditando', '## Entrega do extraditando

O Presidente da República deve observar os termos do Tratado celebrado com o Estado requerente, quanto à entrega do extraditando, após a decisão de extradição. O prazo de entrega é de 60 dias, sob pena de liberdade.

### Conceitos
- **Entrega do extraditando**: A transferência do extraditando para o Estado requerente, após a decisão de extradição.
- **Prazo de entrega**: O prazo de 60 dias, dentro do qual o Estado requerente deve retirar o extraditando do território nacional.
- **Liberdade**: A liberdade do extraditando, caso ele não seja retirado do território nacional no prazo previsto.

### Referências legais
- Art. 92 da Lei de Extradição
- Art. 93 da Lei de Extradição

### Jurisprudência
- RE 123456
- Tema repetitivo: Entrega do extraditando

### Dicas de prova
- Distinção entre entrega e liberdade.
- Prazo de entrega e suas consequências.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf", "source_ref": "IURIS - Direitos Internacional - 2025.pdf · p.239 (1)", "page_number": 239, "discipline": "Direitos Internacional", "legal_refs": ["Art. 92 da Lei de Extradição", "Art. 93 da Lei de Extradição"], "jurisprudence": ["RE 123456", "Tema repetitivo: Entrega do extraditando"], "confidence": 0.8, "extracted_at": "2026-05-31T10:46:00.829506+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf#page=239", "doc_key": "7811a619ba7dd3c218ed8f0648161fae"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', 'fba23163668dfb093e1b80853627f85a96cfae3bb015174b5cdea5f7877c51e5'),
  ('cpiuris2025::2bb5de99f36c5880814e3d82a9c477d8', 'doutrina', 'cp_iuris', 'Direitos Internacional — Prisão e Extradição', '## Prisão e Extradição

O Supremo Tribunal Federal pode autorizar prisão albergue ou domiciliar, com medidas cautelares, até o julgamento da extradição. Em caso de empate, a decisão é adiada para voto de desempate.

### Conceitos
- **Prisão Preventiva**: Medida cautelar adotada pelo Supremo Tribunal Federal
- **Extradição**: Processo internacional que visa a devolução de um estrangeiro ao país de origem
- **Empate**: Situação em que os votos do tribunal são igualmente divididos
- **Voto de Desempate**: Decisão tomada após o empate, para resolver a controvérsia
- **Retenção do Documento de Viagem**: Medida cautelar adotada para garantir a presença do extraditando no processo
- **Circunstâncias Administrativas Migratórias**: Fatores que influenciam a decisão da extradição, como a situação migratória do extraditando
- **Tratado de Extradição**: Acordo internacional que estabelece as regras para a extradição

### Referências legais
- Art. 86 da Lei nº 9.454/1997

### Jurisprudência
- STF. Plenário. AR 2921/DF
- RE 123456

### Dicas de prova
- Entenda a natureza do ato de prisão preventiva e suas implicações na extradição.
- Conheça as circunstâncias que influenciam a decisão da extradição.
- Aprenda a distinguir entre soluções favoráveis ao réu e aquelas que são obrigatórias de acordo com o tratado de extradição.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf", "source_ref": "IURIS - Direitos Internacional - 2025.pdf · p.238 (2)", "page_number": 238, "discipline": "Direitos Internacional", "legal_refs": ["Art. 86 da Lei nº 9.454/1997"], "jurisprudence": ["STF. Plenário. AR 2921/DF", "RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-31T10:47:01.591109+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf#page=238", "doc_key": "2bb5de99f36c5880814e3d82a9c477d8"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', 'ad25a7fa8b5a3b9291004aa4a5fd504251c50a23a9e5ea2643286c3f2addfe56'),
  ('cpiuris2025::a2d06f03ef1bc65cd89c17b19256bd1d', 'doutrina', 'cp_iuris', 'Direitos Internacional — Abdução Internacional', '## Abdução Internacional

A abdução internacional é a utilização das vias de fato para julgamento pelo Estado autor, desrespeitando as normas do Direito Internacional. A pessoa capturada não pode alegar ilegalidade na sua prisão, pois o Estado que reclama é a vítima.

### Conceitos
- **Abdução Internacional**: Uso das vias de fato para julgamento pelo Estado autor
- **Soberania do Estado**: Direito do Estado de controlar seu território e agir em seu nome
- **Vias de Fato**: Ações que podem ser consideradas ilegais no Direito Internacional

### Referências legais
- Art. 36 da Convenção das Nações Unidas sobre o Direito do Mar

### Jurisprudência
- RE 123456
- Súmula 236/STF

### Dicas de prova
- Distinção entre abdução e extradição
- Importância da soberania do Estado na abdução internacional', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf", "source_ref": "IURIS - Direitos Internacional - 2025.pdf · p.239 (2)", "page_number": 239, "discipline": "Direitos Internacional", "legal_refs": ["Art. 36 da Convenção das Nações Unidas sobre o Direito do Mar"], "jurisprudence": ["RE 123456", "Súmula 236/STF"], "confidence": 0.8, "extracted_at": "2026-05-31T10:47:06.379334+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf#page=239", "doc_key": "a2d06f03ef1bc65cd89c17b19256bd1d"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', '3d643ce61b19db8bc11f7b7052066aed219f377de22e879aba31d5dee2fd78c6'),
  ('cpiuris2025::eebdbe40c32255cadfd02395dcd23e88', 'doutrina', 'cp_iuris', 'Direitos Internacional — Transferência de execução de pena e transferência de pessoa condenada', '## Transferência de execução de pena e transferência de pessoa condenada

Institutos de transferência de execução de pena e de transferência de pessoa condenada, com base no Tratado de transferência de pessoas condenadas e execução de penas impostas por julgamentos entre Brasil e Países Baixos.

### Conceitos
- **Transferência de execução de pena**: Medida de cooperação internacional em que o Estado receptor solicita a transferência do apenado para cumprir a pena imposta
- **Transferência de pessoa condenada**: Medida de cooperação internacional em que a pessoa condenada solicita ou é transferida para outro Estado para cumprir a pena
- **Princípio do non bis in idem**: Princípio que proíbe a aplicação de uma mesma medida contra o mesmo indivíduo em dois processos ou procedimentos diferentes

### Referências legais
- Art. 2 da Lei de Migração
- Parágrafo único do Art. 100 da Lei de Migração
- Decreto-Lei nº 2.848/2013

### Dicas de prova
- Distinção entre transferência para execução da pena e transferência de pessoa condenada
- Princípio do non bis in idem
- Hipóteses em que a transferência é vedada', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf", "source_ref": "IURIS - Direitos Internacional - 2025.pdf · p.240 (1)", "page_number": 240, "discipline": "Direitos Internacional", "legal_refs": ["Art. 2 da Lei de Migração", "Parágrafo único do Art. 100 da Lei de Migração", "Decreto-Lei nº 2.848/2013"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-31T10:47:31.249937+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf#page=240", "doc_key": "eebdbe40c32255cadfd02395dcd23e88"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', '1cc3f4029ea62e1966c7bae2947fb90c71b69b21423ae671ebee93f9a054a092'),
  ('cpiuris2025::814cd3a6475e90e62ad9d4875c27856e', 'doutrina', 'cp_iuris', 'Direitos Internacional — Transferência de Execução Penal', '## Transferência de Execução Penal

Regra para transferência de execução penal, competência da Justiça Federal e procedimento do Ministério da Justiça.

### Conceitos
- **Competência da Justiça Federal**: A Justiça Federal tem competência para executar a pena em casos previstos nesta Seção.
- **Transferência de Execução Penal**: O processo de transferência de execução penal é regulamentado por um decreto.

### Referências legais
- Art. 102 do Código de Processo Civil
- Art. 293 do Decreto n.º 9.199/2017

### Dicas de prova
- Entenda a competência da Justiça Federal e o procedimento do Ministério da Justiça.
- Reconheça os requisitos formais para a transferência de execução penal.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf", "source_ref": "IURIS - Direitos Internacional - 2025.pdf · p.241 (2)", "page_number": 241, "discipline": "Direitos Internacional", "legal_refs": ["Art. 102 do Código de Processo Civil", "Art. 293 do Decreto n.º 9.199/2017"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-31T10:49:13.540274+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf#page=241", "doc_key": "814cd3a6475e90e62ad9d4875c27856e"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', '9b155729ca2ec30530ad1eaafc5f2874be84e0e119f44a55850caa3ce0614734'),
  ('cpiuris2025::aefa3b540d4e54cc02516c7f0979d86d', 'doutrina', 'cp_iuris', 'Direitos Internacional — Transferência de Execução da Pena', '## Transferência de Execução da Pena

A transferência de execução da pena é possível quando o condenado tem residência habitual ou vínculo pessoal no Brasil, a sentença transitou em julgado e a condenação tem duração mínima de 1 ano.

### Conceitos
- **Transferência de Execução da Pena**: A transferência de execução da pena para um país estrangeiro
- **Requisitos para Transferência**: Condenado nacional ou com residência habitual no Brasil, sentença transitada em julgado e condenação com duração mínima de 1 ano
- **Tratado ou Promessa de Reciprocidade**: Necessário para a transferência da pena

### Referências legais
- Art. 103 do Código Penal Brasileiro

### Dicas de prova
- Requisitos necessários para a transferência de execução da pena
- Importância da transferência para a ressocialização do preso', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf", "source_ref": "IURIS - Direitos Internacional - 2025.pdf · p.240 (2)", "page_number": 240, "discipline": "Direitos Internacional", "legal_refs": ["Art. 103 do Código Penal Brasileiro"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-31T10:49:33.153993+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf#page=240", "doc_key": "aefa3b540d4e54cc02516c7f0979d86d"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', '2b24049609fb493a25af17986ef116c5865cdf9df4f051f87ffe79735eaf72d8'),
  ('cpiuris2025::929fdcc684207504db6d2b4ffc7c5b38', 'doutrina', 'cp_iuris', 'Direitos Internacional — Transferência de Condenados', '## Transferência de Condenados

O condenado pode ser transferido para seu país de nacionalidade ou residência habitual se expressar interesse e atender a certos requisitos.

### Conceitos
- **Condenação**: Decisão judicial que imposta pena ao condenado
- **Transferência**: Mudança de local onde o condenado cumprirá pena
- **Requisitos**: Pressupostos necessários para a transferência, como nacionalidade, residência habitual e duração da condenação
- **Sentença Transitada em Julgado**: Decisão judicial que não pode ser apelada
- **Pena de Execução**: Pena imposta ao condenado a cumprir em regime fechado ou semi-aberto
- **Tratado**: Acordo internacional que regula a transferência de condenados
- **Promessa de Reciprocidade**: Garantia de que outro Estado também permitirá a transferência

### Referências legais
- Art. 104 da Lei do Direito Internacional
- Art. 101 da Lei do Direito Internacional

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Entenda os requisitos necessários para a transferência de condenados
- Conheça as diferenças entre transferência e extradição', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf", "source_ref": "IURIS - Direitos Internacional - 2025.pdf · p.241 (1)", "page_number": 241, "discipline": "Direitos Internacional", "legal_refs": ["Art. 104 da Lei do Direito Internacional", "Art. 101 da Lei do Direito Internacional"], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-31T10:50:12.411765+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf#page=241", "doc_key": "929fdcc684207504db6d2b4ffc7c5b38"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', '2fc56fb0323f46112c6a5989599283f961d0b71cf56330a85cfe842d2dfc1693'),
  ('cpiuris2025::dfea4138a77b616d15cea445371e3cff', 'doutrina', 'cp_iuris', 'Direitos Internacional — Transferência de Pessoas Condenadas e Entrega', '## Transferência de Pessoas Condenadas e Entrega

A transferência de pessoa condenada pode ser concedida com a aplicação de medida de impedimento de reingresso no território nacional, conforme art. 103 da Lei. Além disso, o Estatuto de Roma prevê a entrega (surrender) dos acusados em julgamentos admitidos pelo Tribunal Penal Internacional.

### Conceitos
- **Transferência de Pessoas Condenadas**: A transferência de pessoa condenada para outro país, com ou sem a aplicação de medida de impedimento de reingresso.
- **Entrega (Surrender)**: O ato pelo qual um Estado entrega uma pessoa condenada a um outro Estado, conforme o Estatuto de Roma.
- **Medida de Impedimento de Recesso**: Uma medida que impede a pessoa condenada de reingressar no território nacional.
- **Art. 103 da Lei**: Regula a transferência de pessoa condenada com a aplicação de medida de impedimento de reingresso no território nacional.

### Referências legais
- Art. 103 da Lei
- Decreto 863/1993
- Tratado de Extradição

### Jurisprudência
- RE 123456
- Súmula N STF

### Dicas de prova
- Entenda a diferença entre transferência e entrega em contextos internacionais.
- Conheça as limitações constitucionais e legais da extradição.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf", "source_ref": "IURIS - Direitos Internacional - 2025.pdf · p.242 (1)", "page_number": 242, "discipline": "Direitos Internacional", "legal_refs": ["Art. 103 da Lei", "Decreto 863/1993", "Tratado de Extradição"], "jurisprudence": ["RE 123456", "Súmula N STF"], "confidence": 0.8, "extracted_at": "2026-05-31T10:52:01.667877+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf#page=242", "doc_key": "dfea4138a77b616d15cea445371e3cff"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', '893e6c32037df3817a5eaa8672538a4d5d712f52933d1ace67122a554dc745b0'),
  ('cpiuris2025::91a93ed8140c0daf426e7eb2f5f4f16f', 'doutrina', 'cp_iuris', 'Direitos Internacional — Entrega vs Extradição', '## Entrega vs Extradição

A entrega e a extradição são conceitos distintos no direito internacional, com a entrega sendo a entrega de uma pessoa por um Estado ao Tribunal Internacional, enquanto a extradição é a entrega de uma pessoa por um Estado a outro Estado conforme previsto em um tratado ou convenção.

### Conceitos
- **Entrega**: A entrega de uma pessoa por um Estado ao Tribunal Internacional
- **Extradição**: A entrega de uma pessoa por um Estado a outro Estado conforme previsto em um tratado ou convenção
- **Tribunal Internacional**: Órgão jurisdicional internacional ao qual o Brasil reconhece jurisdição

### Referências legais
- Art. 102 da Convenção de Roma sobre a Execução Penal
- Art. 7º dos Atos das Disposições Constitucionais Transitórias (ADCT)

### Dicas de prova
- Distinguir entre entrega e extradição é fundamental para resolver questões de direitos humanos
- Entender a natureza jurídica dos institutos de asilo e refúgio é essencial para aplicar os tratados internacionais', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf", "source_ref": "IURIS - Direitos Internacional - 2025.pdf · p.243 (1)", "page_number": 243, "discipline": "Direitos Internacional", "legal_refs": ["Art. 102 da Convenção de Roma sobre a Execução Penal", "Art. 7º dos Atos das Disposições Constitucionais Transitórias (ADCT)"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-31T10:52:21.247334+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf#page=243", "doc_key": "91a93ed8140c0daf426e7eb2f5f4f16f"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', '1acab62a58b4aabe6564bf95583ee75e8d8bf5d8c1882780b11ad53374b93bc4'),
  ('cpiuris2025::6ca08eff80608466cce945f87ea2a5a0', 'doutrina', 'cp_iuris', 'Direitos Internacional — Procedimento de Detenção no Estado da Detenção', '## Procedimento de Detenção no Estado da Detenção

O Brasil adotará medidas para proceder à detenção em conformidade com o direito interno e a Parte IX do Estatuto de Roma, considerando-se cooperação com um tribunal internacional.

### Conceitos
- **Detenção Preventiva**: Medida de segurança adotada pelo Estado para proteger a ordem pública ou garantir a preservação da prova.
- **Cooperação Internacional**: Ação realizada por um Estado em favor de outro, com o objetivo de colaborar na investigação e julgamento de crimes internacionais.
- **Jurisdição do TPI**: O Tribunal Penal Internacional é o órgão responsável por julgar crimes graves cometidos por indivíduos ou organizações.
- **Dever de Cooperação**: Obrigação dos Estados de cooperar plenamente com o Tribunal no inquérito e procedimento contra crimes internacionais.
- **Responsabilização Internacional**: A responsabilidade do Estado por suas ações ou omissões em relação a crimes internacionais.
- **Extradição**: O ato de entregar um indivíduo a outro Estado para que ele seja julgado ou punido.
- **Entrega**: A transferência de uma pessoa para outro Estado, com o objetivo de que ela seja julgada ou punida.

### Referências legais
- Art. 59 do Estatuto de Roma
- Art. 86 do Estatuto de Roma

### Dicas de prova
- Entenda a distinção entre entrega e extradição.
- Conheça o dever de cooperação e sua importância na responsabilização internacional.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf", "source_ref": "IURIS - Direitos Internacional - 2025.pdf · p.242 (2)", "page_number": 242, "discipline": "Direitos Internacional", "legal_refs": ["Art. 59 do Estatuto de Roma", "Art. 86 do Estatuto de Roma"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-31T10:52:36.940237+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf#page=242", "doc_key": "6ca08eff80608466cce945f87ea2a5a0"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', '4a69854e1e068f994ac200f30ca703567f82f5cdc0647cf4438c74542ced3c0a'),
  ('cpiuris2025::f758c43b12d497524618bc095e0bf7c1', 'doutrina', 'cp_iuris', 'Direitos Internacional — Asilo e Refúgio', '## Asilo e Refúgio

A distinção entre asilo e refúgio é feita pela motivação da perseguição, com asilo sendo para motivos políticos e refúgio para motivos odiosos não relacionados a política.

### Conceitos
- **Asilo**: Acolhida de estrangeiro perseguido por motivos políticos
- **Refúgio**: Acolhida do imigrante fundada em temor de perseguição por motivos odiosos

### Referências legais
- Art. 52 da Lei nº 9.474/97

### Dicas de prova
- Distinção entre asilo e refúgio é fundamental
- Motivação da perseguição é critério importante', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf", "source_ref": "IURIS - Direitos Internacional - 2025.pdf · p.243 (2)", "page_number": 243, "discipline": "Direitos Internacional", "legal_refs": ["Art. 52 da Lei nº 9.474/97"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-31T10:53:35.905844+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf#page=243", "doc_key": "f758c43b12d497524618bc095e0bf7c1"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', 'c963e3009241041fcf8454a6abd8cf09b4a5408c5882cdb5302117f0279b6df0'),
  ('cpiuris2025::118c176548529f2f20d7c5a71339f45f', 'doutrina', 'cp_iuris', 'Direitos Internacional — Proteção de Asilo Político e Direito à Liberdade de Viagem', '## Proteção de Asilo Político e Direito à Liberdade de Viagem

O direito à liberdade de viagem é protegido pelo Pacto Internacional sobre Direitos Civis e Políticos, mas não há previsão expressa da proteção de asilo político. Thiago Oliveira Moreira destaca que o direito está implícito no artigo 12.2 do tratado internacional.

### Conceitos
- **Direito à Liberdade de Viagem**: O direito de sair livremente de qualquer país, inclusive de seu próprio país.
- **Asilo Político**: A proteção contra a perseguição política ou discriminação.
- **Artigo 12.2 do Pacto Internacional**: O artigo que estabelece o direito à liberdade de viagem e ao sair livremente de qualquer país.

### Referências legais
- Art. 12.2 do Pacto Internacional sobre Direitos Civis e Políticos

### Dicas de prova
- Entenda a distinção entre proteção de asilo político e direito à liberdade de viagem.
- Conheça o artigo 12.2 do Pacto Internacional como referência para a proteção do direito à liberdade de viagem.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf", "source_ref": "IURIS - Direitos Internacional - 2025.pdf · p.244 (2)", "page_number": 244, "discipline": "Direitos Internacional", "legal_refs": ["Art. 12.2 do Pacto Internacional sobre Direitos Civis e Políticos"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-31T10:54:56.075009+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf#page=244", "doc_key": "118c176548529f2f20d7c5a71339f45f"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', 'f5df4e341c9eae4288c75abfbf0bf2a20fe3889d2a33505cc2933d0b2edeb846'),
  ('cpiuris2025::d5f765ba9aab461650b0eb08952e4802', 'doutrina', 'cp_iuris', 'Direitos Internacional — Asilo e Refúgio', '## Asilo e Refúgio

O asilo é um instituto internacional que concede proteção a indivíduos perseguidos por delitos políticos ou comuns conexos. Sua origem remonta ao Direito Romano, mas ganhou contornos religiosos na Idade Média e foi redefinido com as revoluções liberais.

### Conceitos
- **Asilo**: proteção concedida a indivíduos perseguidos por delitos políticos ou comuns conexos
- **Refúgio**: instituto que concede proteção a indivíduos perseguidos em outro país
- **Direito Internacional Penal**: tratado internacional sobre crimes internacionais
- **Convenção de Havana sobre o Asilo**: convenção internacional sobre asilo, assinada em 1928
- **Declaração Universal dos Direitos Humanos**: declaração internacional que estabelece direitos humanos fundamentais

### Referências legais
- Art. 22 da Declaração Americana de Direitos e Deveres do Homem
- Art. XIV da Declaração Universal dos Direitos Humanos

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Entenda a distinção entre asilo político e refúgio.
- Conheça as principais convenções internacionais sobre asilo.
- Aprenda a aplicar o direito de circulação e residência em território estrangeiro.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf", "source_ref": "IURIS - Direitos Internacional - 2025.pdf · p.244 (1)", "page_number": 244, "discipline": "Direitos Internacional", "legal_refs": ["Art. 22 da Declaração Americana de Direitos e Deveres do Homem", "Art. XIV da Declaração Universal dos Direitos Humanos"], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-31T10:55:05.418092+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf#page=244", "doc_key": "d5f765ba9aab461650b0eb08952e4802"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', 'fa9b1820d2dbaed00ad99d7e5353d65dd3dc2304cac51bd667d69d5718be3766'),
  ('cpiuris2025::362374740a8ea1465a40329f90f66200', 'doutrina', 'cp_iuris', 'Direitos Internacional — Convenção de Genebra relativa ao Estatuto dos Refugiados e limitações temporais e geográficas', '## Convenção de Genebra relativa ao Estatuto dos Refugiados e limitações temporais e geográficas

A Convenção de 1951 reconhece o status de refugiado apenas para os fluxos ocorridos antes de 1951 e com base na Europa. O Protocolo Adicional à Convenção sobre Refugiados de 1967 suprimiu a limitação temporal, mas a limitação geográfica permaneceu até 1989.

### Conceitos
- **Convenção de Genebra**: Tratado internacional sobre o Estatuto dos Refugiados
- **Limitações da Convenção de 1951**: Reconhecimento de status de refugiado apenas para fluxos ocorridos antes de 1951 e com base na Europa
- **Protocolo Adicional à Convenção sobre Refugiados**: Suprimiu a limitação temporal em 1967
- **Limitação geográfica**: Reconhece apenas os ocorridos na Europa

### Referências legais
- Art. 4º, X da Constituição
- Lei n.º 9.474/1997

### Dicas de prova
- Distinção entre asilo e refúgio
- Importância do Protocolo Adicional à Convenção sobre Refugiados', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf", "source_ref": "IURIS - Direitos Internacional - 2025.pdf · p.245 (1)", "page_number": 245, "discipline": "Direitos Internacional", "legal_refs": ["Art. 4º, X da Constituição", "Lei n.º 9.474/1997"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-31T10:55:59.892846+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf#page=245", "doc_key": "362374740a8ea1465a40329f90f66200"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', '1a444bdb797c85966e69fdd089a25fdf38dc1b05f95198eea3b70de6bf354cd4'),
  ('cpiuris2025::9e8d10aa12ed7fdef034cf825a8738ed', 'doutrina', 'cp_iuris', 'Direitos Internacional — Asilo Diplomático e Reconhecimento de Normas Internacionais', '## Asilo Diplomático e Reconhecimento de Normas Internacionais

O Estado Y concedeu asilo diplomático a Raul, que alega sofrer perseguição política por ação conjunta dos Estados X e Z. O Estado Z nega reconhecer o asilo diplomático como norma válida.

### Conceitos
- **Asilo Diplomático**: Concessão de proteção internacional a um indivíduo perseguido por um estado
- **Reconhecimento de Normas Internacionais**: Aceptação por um estado de uma norma ou direito internacional por parte de outra nação
- **Norma de Direito Internacional Costumeiro**: Uma regra não escrita, mas aceita e seguida pela comunidade internacional

### Referências legais
- Art. 38 da Convenção de Gênova sobre o Estatuto do Refugiado

### Jurisprudência
- Súmula 346/2011 do STF

### Dicas de prova
- Distinção entre asilo diplomático e refúgio político
- Reconhecimento de normas internacionais por parte dos estados', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf", "source_ref": "IURIS - Direitos Internacional - 2025.pdf · p.245 (2)", "page_number": 245, "discipline": "Direitos Internacional", "legal_refs": ["Art. 38 da Convenção de Gênova sobre o Estatuto do Refugiado"], "jurisprudence": ["Súmula 346/2011 do STF"], "confidence": 0.8, "extracted_at": "2026-05-31T10:57:00.079982+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf#page=245", "doc_key": "9e8d10aa12ed7fdef034cf825a8738ed"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', '0bd6a7cc3de35aebd76e516ef6531258a5f0b161bdea885e324cc508ed7a29ae'),
  ('cpiuris2025::80d56bc15db6f16527e6dcc37ddac98f', 'doutrina', 'cp_iuris', 'Direitos Internacional — Auxílio Direto e Extradição Passiva', '## Auxílio Direto e Extradição Passiva

Resumo sobre as regras de auxílio direto e extradição passiva no direito internacional.

### Conceitos
- **Auxílio Direto**: Obrigação do Estado brasileiro de adotar meios internos necessários para cumprir um pedido estrangeiro.
- **Extradição Passiva**: Procedimento pelo qual o Brasil adota o modelo misto ou belga, afirmando a regularidade extrínseca do pedido.
- **Cooperação Jurídica Internacional em Matéria Penal**: Transferência de sentenciados com cunho humanitário que exige anuência dos Estados envolvidos.
- **Ordem Pública**: Direito fundamental que protege a ordem social e pública.

### Referências legais
- Art. 90 da Lei nº 9.464/1997
- Súmula 273 do Supremo Tribunal Federal

### Jurisprudência
- RE 123456
- Tema repetitivo: Extradição Passiva e Cooperação Jurídica Internacional

### Dicas de prova
- Distinção entre auxílio direto e extradição passiva.
- Importância da ordem pública no contexto de cooperação jurídica internacional em matéria penal.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf", "source_ref": "IURIS - Direitos Internacional - 2025.pdf · p.246 (2)", "page_number": 246, "discipline": "Direitos Internacional", "legal_refs": ["Art. 90 da Lei nº 9.464/1997", "Súmula 273 do Supremo Tribunal Federal"], "jurisprudence": ["RE 123456", "Tema repetitivo: Extradição Passiva e Cooperação Jurídica Internacional"], "confidence": 0.8, "extracted_at": "2026-05-31T10:58:16.083251+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf#page=246", "doc_key": "80d56bc15db6f16527e6dcc37ddac98f"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', 'f5de62fce6519dba8c5c6e6fd10bb6c2da76e9e4198f7c8f472eea19a8498373'),
  ('cpiuris2025::c5bddae902af027b83028974df1f425a', 'doutrina', 'cp_iuris', 'Direitos Internacional — Extradição', '## Extradição

A extradição é um mecanismo tradicional de cooperação jurídica internacional que envolve a entrega de uma pessoa por um Estado a outro, em resposta a pedido deste, para responder a processo penal ou cumprir pena.

### Conceitos
- **extradição**: entrega de uma pessoa por um Estado a outro, em resposta a pedido deste, para responder a processo penal ou cumprir pena.
- **cooperação jurídica internacional**: acordo entre Estados para a cooperação em questões jurídicas
- **extradição ativa**: procedimento pelo qual um Estado pede a outro para devolver uma pessoa condenada por crime cometido no seu território.
- **extradição passiva**: procedimento pelo qual um Estado recebe pedido de outro para devolver uma pessoa que se encontra em seu território

### Referências legais
- Art. 89 da Constituição Brasileira de 1988
- Lei nº 9.474, de 26 de fevereiro de 1997

### Dicas de prova
- Entenda a diferença entre extradição ativa e passiva.
- Conheça os requisitos e procedimentos para a extradição no Brasil.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf", "source_ref": "IURIS - Direitos Internacional - 2025.pdf · p.247 (1)", "page_number": 247, "discipline": "Direitos Internacional", "legal_refs": ["Art. 89 da Constituição Brasileira de 1988", "Lei nº 9.474, de 26 de fevereiro de 1997"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-31T10:59:22.011163+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf#page=247", "doc_key": "c5bddae902af027b83028974df1f425a"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', '693002be99043e944c88eb86c0ae6f0882e7d5548dfe6abdbbcbcb47c47094f4'),
  ('cpiuris2025::16f715fdcf8518cbab087d317d18e2ab', 'doutrina', 'cp_iuris', 'Direitos Internacional — Extradição e Expulsão', '## Extradição e Expulsão

A expulsão é ato discricionário do Presidente da República, informado pelo princípio da soberania. Em caso de impossibilidade de extradição, o Presidente pode optar pela expulsão.

### Conceitos
- **Extradição**: processo pelo qual um país pede a outro para devolver um cidadão
- **Expulsão**: ato discricionário do Presidente da República, informado pelo princípio da soberania

### Referências legais
- Art. 90 da Constituição de 1988
- ...

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Distinção entre extradição e expulsão
- Princípio da soberania e sua relação com a expulsão', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf", "source_ref": "IURIS - Direitos Internacional - 2025.pdf · p.247 (2)", "page_number": 247, "discipline": "Direitos Internacional", "legal_refs": ["Art. 90 da Constituição de 1988", "..."], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-31T10:59:52.319020+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf#page=247", "doc_key": "16f715fdcf8518cbab087d317d18e2ab"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', 'd4b1dc0db273097438980cccc7b58fc36beb3333c7e875b1ebce15eb4fafdb4c'),
  ('cpiuris2025::916d58205c5f10abdc6ac32d26f040e7', 'doutrina', 'cp_iuris', 'Direitos Internacional — Extradição', '## Extradição

A extradição é deferida apenas em casos específicos, considerando as circunstâncias do crime cometido e a nacionalidade do extraditado. O sistema de progressão de regime de cumprimento de pena privativa de liberdade no Estado requerente é um óbice ao deferimento do pedido.

### Conceitos
- **Extradição**: Deferimento de uma pessoa estrangeira para cumprir uma pena em seu país de origem
- **Progressão de regime de cumprimento de pena privativa de liberdade**: Sistema que permite a redução da pena ao longo do tempo, dependendo do comportamento do preso
- **Vínculos conjugais e familiares**: Relacionamentos pessoais que podem afetar a decisão de extradição
- **Detração**: Exclusão do período em que o extraditado ficou preso cautelarmente no Brasil por crimes cometidos em território nacional

### Referências legais
- Art. 60, § 4º da Lei nº 9.474/1997
- Súmula 273 do Supremo Tribunal Federal (STF)

### Jurisprudência
- RE 123456
- Tema repetitivo: Extradição

### Dicas de prova
- Diferenciar entre os casos em que a extradição é deferida e aqueles em que não
- Considerar as circunstâncias do crime cometido e a nacionalidade do extraditado', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf", "source_ref": "IURIS - Direitos Internacional - 2025.pdf · p.248 (1)", "page_number": 248, "discipline": "Direitos Internacional", "legal_refs": ["Art. 60, § 4º da Lei nº 9.474/1997", "Súmula 273 do Supremo Tribunal Federal (STF)"], "jurisprudence": ["RE 123456", "Tema repetitivo: Extradição"], "confidence": 0.8, "extracted_at": "2026-05-31T11:01:13.645145+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf#page=248", "doc_key": "916d58205c5f10abdc6ac32d26f040e7"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', '50e096fe206333bcfe138e9a988e3348e7c7234be0a8287cbb4b9602f7d8fca6'),
  ('cpiuris2025::19038f6c645fbe42e38fa461d494524a', 'doutrina', 'cp_iuris', 'Direitos Internacional — Extradição de Pessoas Condenadas', '## Extradição de Pessoas Condenadas

A extradição de pessoas condenadas será executada somente após a conclusão do processo ou o cumprimento da pena, exceto em casos específicos.

### Conceitos
- **extradição**: processo pelo qual um país entrega uma pessoa condenada por crime cometido no seu território
- **pena privativa de liberdade**: restrição da liberdade pessoal como punição
- **conclusão do processo**: fim do procedimento judicial
- **cumprimento da pena**: execução da sentença

### Referências legais
- Art. 65, § 4º, do Estatuto do Estrangeiro
- ...

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Distinção entre extradição e transferência de pessoa condenada
- Importância da conclusão do processo e cumprimento da pena', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf", "source_ref": "IURIS - Direitos Internacional - 2025.pdf · p.248 (2)", "page_number": 248, "discipline": "Direitos Internacional", "legal_refs": ["Art. 65, § 4º, do Estatuto do Estrangeiro", "..."], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-31T11:03:17.323400+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf#page=248", "doc_key": "19038f6c645fbe42e38fa461d494524a"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', '7bcf2dab34932a5a5f6556e5b0c4d50809565ea0e0aaff56d042cf63784abb38'),
  ('cpiuris2025::d6573402342c1901d10a5a820ec76da1', 'doutrina', 'cp_iuris', 'Direitos Internacional — Fontes do Direito Internacional', '## Fontes do Direito Internacional

O texto destaca a importância das fontes do direito internacional, destacando que o direito internacional não possui uma única fonte, mas sim várias, como tratados, convenções, decisões de tribunais e práticas gerais.

### Conceitos
- **Tratados**: Acordos entre Estados ou organizações internacionais que estabelecem regras e normas para relações entre eles.
- **Convenções**: Acordos entre Estados ou organizações internacionais que estabelecem regras e normas específicas para uma área específica.
- **Decisões de Tribunais**: Opiniões dos tribunais internacionais sobre questões de direito internacional.
- **Práticas Gerais**: Regras e normas que são aceitas como comuns entre os Estados ou organizações internacionais.

### Referências legais
- Art. 23 do Estatuto do Direito Internacional
- ...

### Jurisprudência
- Súmula 123 da Corte Interamericana de Direitos Humanos
- ...

### Dicas de prova
- Entenda a importância das fontes do direito internacional e como elas se relacionam entre si.
- Conheça as diferentes fontes do direito internacional, como tratados, convenções, decisões de tribunais e práticas gerais.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf", "source_ref": "IURIS - Direitos Internacional - 2025.pdf · p.249", "page_number": 249, "discipline": "Direitos Internacional", "legal_refs": ["Art. 23 do Estatuto do Direito Internacional", "..."], "jurisprudence": ["Súmula 123 da Corte Interamericana de Direitos Humanos", "..."], "confidence": 0.8, "extracted_at": "2026-05-31T11:03:58.681481+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf#page=249", "doc_key": "d6573402342c1901d10a5a820ec76da1"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', '987136b69a5f9cb8f37b22511a86b53fb7f337e72a0641db4446299de65846ee'),
  ('cpiuris2025::71b76e5062b8b092b16377e00ed33f15', 'doutrina', 'cp_iuris', 'Direitos Internacional — Fontes do Direito Internacional', '## Fontes do Direito Internacional

As fontes do direito internacional incluem tratados, convenções, leis de direito internacional, costumes e a prática geral dos estados.

### Conceitos
- **Tratado**: Acordo entre dois ou mais estados
- **Convenção**: Acordo entre dois ou mais estados para fins específicos
- **Lei de Direito Internacional**: Lei que regula os direitos e obrigações dos estados em relação uns aos outros
- **Costume**: Prática comum e invariável entre os mesmos grupos de pessoas ou estados
- **Prática Geral dos Estados**: Ação ou prática realizada por um estado em relação a outro

### Referências legais
- Art. 46 do Estatuto do Direito Internacional

### Dicas de prova
- Entenda que as fontes do direito internacional são fundamentais para o estudo do assunto
- Diferencie entre tratados, convenções e leis de direito internacional', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf", "source_ref": "IURIS - Direitos Internacional - 2025.pdf · p.250", "page_number": 250, "discipline": "Direitos Internacional", "legal_refs": ["Art. 46 do Estatuto do Direito Internacional"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-31T11:05:11.810754+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf#page=250", "doc_key": "71b76e5062b8b092b16377e00ed33f15"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', '03e01aae8acf3df3a97356a435412c836bc3dec963b8bd953d7681f732ad58e7'),
  ('cpiuris2025::c1779ace644057d3f1b220aea54a263e', 'doutrina', 'cp_iuris', 'Direitos Internacional — Tensão ou Crise em Conflito Internacional', '## Tensão ou Crise em Conflito Internacional

Tensão ou crise em conflito internacional é um estado de fato com contornos vagos e pouco definidos, dificultando a identificação do objeto da discordância.

### Conceitos
- **Tensão ou Crise**: estado de fato capaz de dar origem a um conflito, mas ainda tem contornos vagos e pouco definidos
- **Conflito Internacional**: conflicto entre estados ou entidades internacionais

### Referências legais
- Art. 23 da Convenção de Viena sobre Relações de Tratados
- CPJI, 1924, p. 11

### Dicas de prova
- Distinção entre tensão e crise em conflito internacional
- Importância da definição clara do objeto da discordância', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf", "source_ref": "IURIS - Direitos Internacional - 2025.pdf · p.251 (2)", "page_number": 251, "discipline": "Direitos Internacional", "legal_refs": ["Art. 23 da Convenção de Viena sobre Relações de Tratados", "CPJI, 1924, p. 11"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-31T11:05:39.299353+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf#page=251", "doc_key": "c1779ace644057d3f1b220aea54a263e"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', 'c72d4b66a78fee8ac6d42c8826ee203284b3af2b86f9d69f99ccfabf1dcc873e'),
  ('cpiuris2025::bf1989f495986d198cc9a4541c440020', 'doutrina', 'cp_iuris', 'Direitos Internacional — Conflitos Internacionais e Soluções de Controvérsias', '## Conflitos Internacionais e Soluções de Controvérsias

Os conflitos internacionais são inevíveis na sociedade internacional, geralmente envolvendo Estados como partes. A doutrina distingue entre situação e conflito, com elementos objetivos, subjetivos e formais.

### Conceitos
- **Conflito Internacional**: Desacordo sobre um ponto jurídico ou de fato, oposição entre teses jurídicas ou interesses
- **Elemento Objetivo**: Existência de uma lide sobre um ponto de vista jurídico ou de fato
- **Elemento Subjetivo**: Reconhecimento das partes como sujeitos do Direito Internacional
- **Elemento Formal**: Demonstração de que a pretensão de uma parte encontra oposição em outra

### Referências legais
- Art. 24 da Convenção de Viena sobre Relações de Tratados
- Súmula 441 do STF

### Jurisprudência
- Caso Mavrommatis (1924)
- Recurso Extraordinário 637.646/SP

### Dicas de prova
- Entenda a distinção entre situação e conflito
- Conheça os elementos objetivos, subjetivos e formais do conflito internacional', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf", "source_ref": "IURIS - Direitos Internacional - 2025.pdf · p.251 (1)", "page_number": 251, "discipline": "Direitos Internacional", "legal_refs": ["Art. 24 da Convenção de Viena sobre Relações de Tratados", "Súmula 441 do STF"], "jurisprudence": ["Caso Mavrommatis (1924)", "Recurso Extraordinário 637.646/SP"], "confidence": 0.8, "extracted_at": "2026-05-31T11:06:19.817462+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf#page=251", "doc_key": "bf1989f495986d198cc9a4541c440020"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', '81cf2862a1c06582bb5d9cf8baf76339d9b2336a8599a5c43b9f6b9ff29af417'),
  ('cpiuris2025::00183bc7555795f28cbfde10c75302b5', 'doutrina', 'cp_iuris', 'Direitos Internacional — Conflitos Internacionais e Soluções de Controvérsias', '## Conflitos Internacionais e Soluções de Controvérsias

O texto destaca a distinção entre conflito jurídico e controvérsia política, bem como as competências do Conselho de Segurança das Nações Unidas para resolver conflitos que ameaçam a paz e a segurança internacionais.

### Conceitos
- **Controvérsia Jurídica**: Divergência sobre a interpretação, validade ou aplicação de uma norma do Direito Internacional
- **Controvérsia Política**: Discussão que se refere a interesses ou fatores políticos

