  ('cpiuris2025::8161ae9308b9880d9b692ce6a9f428c8', 'doutrina', 'cp_iuris', 'Direitos Internacional — Obrigatoriedade da adoção de um meio pacífico de solução das controvérsias no Direito Internacional', '## Obrigatoriedade da adoção de um meio pacífico de solução das controvérsias no Direito Internacional

Regras para a resolução de controvérsias internacionais, destacando a obrigatoriedade do uso de meios pacíficos.

### Conceitos
- **Obrigatoriedade da adoção de um meio pacífico de solução das controvérsias**: Regra que estabelece a necessidade do uso de métodos pacíficos para resolver disputas internacionais
- **Força**: Uso da força como forma de resolução de controvérsias, considerado limitado pela Doutrina Draco
- **Liga das Nações**: Organização internacional que buscou acomodar a utilização da força em conflitos internacionais

### Referências legais
- Art. 11 do Direito Internacional
- Art. 12 do Direito Internacional

### Dicas de prova
- Entenda a importância da adoção de meios pacíficos na resolução de controvérsias internacionais.
- Conheça a Doutrina Draco e sua influência no uso da força em conflitos internacionais.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf", "source_ref": "IURIS - Direitos Internacional - 2025.pdf · p.252 (2)", "page_number": 252, "discipline": "Direitos Internacional", "legal_refs": ["Art. 11 do Direito Internacional", "Art. 12 do Direito Internacional"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-31T11:07:55.767760+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf#page=252", "doc_key": "8161ae9308b9880d9b692ce6a9f428c8"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', '16602eb440e0755b37ba86ceb118ea42080b9e702a563d83157f2bb3dec3fa49'),
  ('cpiuris2025::fc7aaafceefc9afba4ffab2b2df3363c', 'doutrina', 'cp_iuris', 'Direitos Internacional — Princípio da igualdade soberana dos Estados na solução de controvérsias internacionais', '## Princípio da igualdade soberana dos Estados na solução de controvérsias internacionais

A solução de controvérsias internacionais se baseará na igualdade soberana dos Estados, segundo o princípio da livre eleição dos meios em conformidade com as obrigações contraídas e os princípios da justiça e do direito internacional.

### Conceitos
- **Igualdade soberana**: Princípio que afirma a igualdade dos Estados em relação às outras nações
- **Procedimento de solução aceitado livremente**: Método de resolução de controvérsias internacionalmente reconhecido e aceito pelos Estados

### Referências legais
- Art. 27 da Carta das Nações Unidas

### Dicas de prova
- Entenda a importância do princípio da igualdade soberana nos procedimentos de solução de controvérsias internacionais
- Identifique o tipo de procedimento de solução aceitado livremente pelos Estados', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf", "source_ref": "IURIS - Direitos Internacional - 2025.pdf · p.253 (2)", "page_number": 253, "discipline": "Direitos Internacional", "legal_refs": ["Art. 27 da Carta das Nações Unidas"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-31T11:09:15.052396+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf#page=253", "doc_key": "fc7aaafceefc9afba4ffab2b2df3363c"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', '9b0b52ecb10022b587e0c27c68cf95af61b76ce873b17a60c53e141849da3fca'),
  ('cpiuris2025::cd81ee82a07dea4cc791027a06b18cd0', 'doutrina', 'cp_iuris', 'Direitos Internacional — Métodos de solução de conflitos internacionais', '## Métodos de solução de conflitos internacionais

Os Estados têm liberdade para escolher o método de solução de conflitos internacionais, com a obrigação de buscar uma solução pacífica e justa, prevista na Carta das Nações Unidas.

### Conceitos
- **Carta das Nações Unidas**: Instrumento internacional que estabelece regras para relações entre os Estados
- **Declaração de Manila**: Declaração de 1982 que exorta os Estados a buscar uma solução rápida e justa para as suas controvérsias
- **Declaração relativa aos princípios de Direito Internacional referente às relações amistosas e de cooperação entre os Estados**: Resolução da Assembleia Geral da ONU de 1970 que estabelece princípios para as relações amistosas e de cooperação entre os Estados
- **Corte Permanente de Justiça Internacional**: Organismo internacional que emitiu a Opinião Consultiva sobre o Status da Carélia Oriental, de 1923

### Referências legais
- Artigo 2.3 da Carta das Nações Unidas
- Artigo 33 da Carta das Nações Unidas
- Declaração de Manila de 1982
- Resolução 2625 (XXV) da Assembleia Geral da ONU de 1970

### Jurisprudência
- Opinião Consultiva sobre o Status da Carélia Oriental, Corte Permanente de Justiça Internacional, de 1923
- Opinião Consultiva Interpretação dos tratados de paz entre Bulgária, Hungria e Romênia, Corte Internacional de Justiça, de 1950

### Dicas de prova
- Entenda a liberdade de escolha do método de solução de conflitos internacionais
