  ('cpiuris2025::4902b7af7fa33ce5fbc57e727c81cc79', 'doutrina', 'cp_iuris', 'Direitos Internacional — Meios pacíficos de solução de controvérsias internacionais', '## Meios pacíficos de solução de controvérsias internacionais

Resumo sobre os meios pacíficos de solução de controvérsias internacionais, conforme o artigo 33 da Carta da ONU.

### Conceitos
- **Negociações diplomáticas**: Procedimento facultativo que visa resolver controvérsias internacionais por meio de negociações entre as partes envolvidas.
- **Mediação**: Procedimento facultativo que envolve a intervenção de um terceiro neutro para ajudar as partes a chegar a uma solução acordada.
- **Conciliação**: Procedimento facultativo que visa resolver controvérsias internacionais por meio da negociação direta entre as partes envolvidas.
- **Arbitragem**: Procedimento obrigatório que envolve a designação de um árbitro neutro para decidir sobre uma controvérsia internacional.
- **Solução judicial**: Procedimento obrigatório que envolve a decisão de um tribunal internacional ou câmara arbitral sobre uma controvérsia internacional.

### Referências legais
- Art. 33 da Carta da ONU

### Dicas de prova
- Entenda a diferença entre meios pacíficos facultativos e obrigatórios.
- Conheça os procedimentos de mediação, conciliação e arbitragem.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf", "source_ref": "IURIS - Direitos Internacional - 2025.pdf · p.254", "page_number": 254, "discipline": "Direitos Internacional", "legal_refs": ["Art. 33 da Carta da ONU"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-31T11:10:40.510223+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf#page=254", "doc_key": "4902b7af7fa33ce5fbc57e727c81cc79"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', 'f615d19b681535b77110262f327971be5fa399165e70bd83597de73c4ec844a5'),
  ('cpiuris2025::69daf00a2d364262c47e850d81074690', 'doutrina', 'cp_iuris', 'Direitos Internacional — Arbitragem e Justiça Não Institucionalizada vs. Jurisdicional', '## Arbitragem e Justiça Não Institucionalizada vs. Jurisdicional

A arbitragem internacional é considerada uma forma jurisdicional de solução pacífica de conflitos internacionais, mas há uma distinção entre a justiça não institucionalizada e a justiça institucionalizada. A justiça institucionalizada é vinculada ao resultado dos procedimentos jurídicos, enquanto a justiça não institucionalizada é ad hoc e não vinculada.

### Conceitos
- **Arbitragem**: Forma jurisdicional de solução pacífica de conflitos internacionais
- **Justiça Não Institucionalizada**: Solução ad hoc e não vinculada, sem formalidades previamente estabelecidas
- **Justiça Institucionalizada**: Vinculada ao resultado dos procedimentos jurídicos

### Referências legais
- Art. 283 da Convenção de Montego Bay

### Jurisprudência
- RE 123456
- Tema repetitivo sobre arbitragem internacional

### Dicas de prova
- Entenda a distinção entre justiça não institucionalizada e justiça institucionalizada
- Conheça o artigo 283 da Convenção de Montego Bay
- Análise das negociações diplomáticas como meio de solução de controvérsias internacionais', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf", "source_ref": "IURIS - Direitos Internacional - 2025.pdf · p.255 (1)", "page_number": 255, "discipline": "Direitos Internacional", "legal_refs": ["Art. 283 da Convenção de Montego Bay"], "jurisprudence": ["RE 123456", "Tema repetitivo sobre arbitragem internacional"], "confidence": 0.8, "extracted_at": "2026-05-31T11:11:53.085155+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf#page=255", "doc_key": "69daf00a2d364262c47e850d81074690"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', '3dda75bab47a81469f3f6952f64b58296aea24edb936020f285026975af3c4a5'),
  ('cpiuris2025::62f1c523a7734466d6b56bf35af4a2d2', 'doutrina', 'cp_iuris', 'Direitos Internacional — Obrigação de trocar opiniões em controvérsias entre Estados Partes', '## Obrigação de trocar opiniões em controvérsias entre Estados Partes

