  ('cpiuris2025::4065e76dbe6246ed79e4ffad197c2146', 'doutrina', 'cp_iuris', 'Direitos Internacional — Métodos de solução de controvérsias internacionais', '## Métodos de solução de controvérsias internacionais

Discute os métodos de solução de controvérsias internacionais, incluindo negociação, consultas, inquérito, bons ofícios, mediação e conciliação.

### Conceitos
- **Negociação**: Método de solução de controvérsias em que as partes buscam um acordo através de pressões e negociações.
- **Consultas**: Sistema diplomático de solução de controvérsias, onde as partes consultam-se mutuamente sobre pontos controvertidos.
- **Inquérito**: Procedimento previsto na Convenção de Haia de 1899 e posteriormente aprimorado, que busca esclarecer os fatos controversos.
- **Bons ofícios**: Método de solução de controvérsias em que um terceiro busca que as partes cheguem a um acordo para pôr fim à controvérsia.

### Referências legais
- Convenção de Haia de 1899
- Convenção de Haia de 1907

### Dicas de prova
- Entenda a diferença entre negociação e consultas.
- Conheça o procedimento do inquérito e sua importância na solução de controvérsias internacionais.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf", "source_ref": "IURIS - Direitos Internacional - 2025.pdf · p.256 (1)", "page_number": 256, "discipline": "Direitos Internacional", "legal_refs": ["Convenção de Haia de 1899", "Convenção de Haia de 1907"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-31T11:13:14.332089+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf#page=256", "doc_key": "4065e76dbe6246ed79e4ffad197c2146"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', '3e4ad8970fedaa65f85ab4557a322d7799022c90b8c430796741a88d499b5ea1'),
  ('cpiuris2025::3e6aa418954593b56131da125c5c5397', 'doutrina', 'cp_iuris', 'Direitos Internacional — Intervenção em negociações internacionais', '## Intervenção em negociações internacionais

A intervenção de um terceiro é mais modesta nos bons ofícios ou facilitação, limitando-se a influência moral ou política para que as partes conversem ou organizem as negociações diretas entre elas.

### Conceitos
- **Intervenção**: Ação de um terceiro em uma negociação internacional
- **Bons ofícios**: Facilitação da negociação por meio de influência moral ou política
- **Mediação**: Técnica de resolução de conflitos por meio de um terceiro neutro

### Referências legais
- Art. 96 da Convenção de Viena sobre Direito do Comércio Internacional
- ...

