- Conheça as técnicas de facilitação da negociação', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf", "source_ref": "IURIS - Direitos Internacional - 2025.pdf · p.256 (2)", "page_number": 256, "discipline": "Direitos Internacional", "legal_refs": ["Art. 96 da Convenção de Viena sobre Direito do Comércio Internacional", "..."], "jurisprudence": ["RE 123456", "Tema repetitivo sobre intervenção em negociações internacionais ..."], "confidence": 0.8, "extracted_at": "2026-05-31T11:13:35.149641+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf#page=256", "doc_key": "3e6aa418954593b56131da125c5c5397"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', 'a8fdf154a75bd93e081547701f0b1fcfd68eff1a48a431e4bd774b50603844d7'),
  ('cpiuris2025::0faf526c2527f14694a10928b037614f', 'doutrina', 'cp_iuris', 'Direitos Internacional — Mediação e Conciliação em Conflitos Internacionais', '## Mediação e Conciliação em Conflitos Internacionais

A mediação é uma técnica facultativa ou obrigatória que envolve a intervenção de um terceiro para ajudar as partes a chegar a um acordo. A conciliação é uma análise de controvérsia por um órgão colegiado pré-constituído ou ad hoc, aceito pelas partes.

### Conceitos
- **Mediação**: Intervenção de um terceiro para ajudar as partes a chegar a um acordo
- **Conciliação**: Análise de controvérsia por um órgão colegiado pré-constituído ou ad hoc, aceito pelas partes
- **Técnica facultativa/obrigatória**: Pode ser escolhida pelas partes ou ser obrigatória por acordo previo
- **Terceiro**: Pessoa natural, Estado ou organização internacional que intervém na negociação
- **Órgão colegiado**: Comissão de conciliação pré-constituído ou ad hoc que analisa os fatos e o direito

### Referências legais
- Art. X da Lei Y

### Jurisprudência
- RE 123456
- Tema repetitivo ...
- CVDT

### Dicas de prova
- Entenda a diferença entre mediação e conciliação
- Conheça as características do terceiro e do órgão colegiado
- Avalie a importância da aceitação pelas partes no processo de conciliação', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf", "source_ref": "IURIS - Direitos Internacional - 2025.pdf · p.257 (1)", "page_number": 257, "discipline": "Direitos Internacional", "legal_refs": ["Art. X da Lei Y"], "jurisprudence": ["RE 123456", "Tema repetitivo ...", "CVDT"], "confidence": 0.8, "extracted_at": "2026-05-31T11:13:59.735593+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf#page=257", "doc_key": "0faf526c2527f14694a10928b037614f"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', '9b8a22903d74c8beb887ded23e008137a3bd9d3ab143b99481b94702e8d6a38b'),
  ('cpiuris2025::03bd6631538e8be98bf04bede0561763', 'doutrina', 'cp_iuris', 'Direitos Internacional — Compromisso Arbitral', '## Compromisso Arbitral

O compromisso arbitral é uma decisão de submissão à arbitragem que pode ser feito antes ou após o surgimento do conflito, regido pelas regras dos Direitos dos Tratados.

### Conceitos
- **Compromisso Arbitral**: Decisão de submissão à arbitragem
- **Cláusula de Arbitragem**: Cláusula que estabelece a arbitragem como meio de resolução do conflito
- **Validade do Compromisso Arbitral**: Inicia-se após a ratificação pelos Estados partes da controvérsia
- **Laudo Arbitral**: Decisão dos árbitros que os Estados se comprometem a cumprir
- **Ilícito Internacional**: Descumprimento do laudo arbitral

### Referências legais
- Art. X da Lei Y

### Jurisprudência
- RE 123456
- Súmula N STF

### Dicas de prova
- Entenda a diferença entre compromisso arbitral e cláusula de arbitragem
- Conheça as regras de validade do compromisso arbitral
- A importância do laudo arbitral e seus consequências', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf", "source_ref": "IURIS - Direitos Internacional - 2025.pdf · p.258 (2)", "page_number": 258, "discipline": "Direitos Internacional", "legal_refs": ["Art. X da Lei Y"], "jurisprudence": ["RE 123456", "Súmula N STF"], "confidence": 0.8, "extracted_at": "2026-05-31T11:16:21.076730+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf#page=258", "doc_key": "03bd6631538e8be98bf04bede0561763"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', '63204244bc27d129d3a828054fb8dab816a195072aff274cd774b74b0e682576'),
  ('cpiuris2025::cbe18a18fc5751ff030d3288f1f138ce', 'doutrina', 'cp_iuris', 'Direitos Internacional — Arbitragem e Processo de Controvérsia', '## Arbitragem e Processo de Controvérsia

A arbitragem é um meio jurídico de solução de controvérsias, com caráter vinculante e proferida por um órgão imparcial. As partes podem decidir submeter a controvérsia à arbitragem ou iniciar o processo previsto no Anexo da Convenção.

### Conceitos
- **Arbitragem**: Meio jurídico de solução de controvérsias com caráter vinculante
- **Processo de Controvérsia**: Procedimento para resolver disputas entre partes
- **Órgão Imparcial**: Entidade que proferirá a decisão (laudo arbitral)
- **Caráter Vinculante**: A decisão do órgão imparcial tem força de lei para as partes
- **Anexo da Convenção**: Documento que estabelece o procedimento para resolver controvérsias

### Referências legais
- Art. [inserir número do artigo] da [inserir nome da convenção]

### Dicas de prova
- Entenda a diferença entre arbitragem e processo de controvérsia
