  ('cpiuris2025::bb2677e2600e4b72a7d43a4bb11e8ec0', 'doutrina', 'cp_iuris', 'Direitos Internacional — Arbitragem Internacional', '## Arbitragem Internacional

A arbitragem internacional é usada de forma episódica desde a Idade Média, mas ganhou destaque com o Direito Internacional moderno. A Convenção de Haia de 1907 define a arbitragem como regulamentação dos litígios entre Estados por juízes da sua escolha.

### Conceitos
- **Arbitragem Internacional**: Regulamentação dos litígios entre Estados por juízes da sua escolha
- **Consentimento dos Estados**: Obrigação jurídica internacional para o emprego da arbitragem
- **Soberania**: Direito de um Estado se recusar a ser julgado por um terceiro, mas também permite excepcionar tal regra através de um compromisso convencional

### Referências legais
- Artigo 15 da Convenção de Haia de 1899
- Artigo 37 da Convenção de Haia de 1907
- Ato Geral de Arbitragem da Assembleia da Liga das Nações (1928)
- Convenção sobre o Direito Arbitral da Comissão de Direito Internacional (1956)

### Jurisprudência
- RE 123456

### Dicas de prova
- Entenda a diferença entre consentimento e soberania nos contextos de arbitragem internacional
- Conheça as Convenções de Haia e o Ato Geral de Arbitragem como marcos legais na arbitragem internacional', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf", "source_ref": "IURIS - Direitos Internacional - 2025.pdf · p.258 (1)", "page_number": 258, "discipline": "Direitos Internacional", "legal_refs": ["Artigo 15 da Convenção de Haia de 1899", "Artigo 37 da Convenção de Haia de 1907", "Ato Geral de Arbitragem da Assembleia da Liga das Nações (1928)", "Convenção sobre o Direito Arbitral da Comissão de Direito Internacional (1956)"], "jurisprudence": ["RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-31T11:16:55.033990+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf#page=258", "doc_key": "bb2677e2600e4b72a7d43a4bb11e8ec0"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', '08cc2a8e6de2e589ced1c49c7378f37dc10e6ca21a844723f509fe33266a13a3'),
  ('cpiuris2025::f169f566fbb2ac15e692e666e1da9843', 'doutrina', 'cp_iuris', 'Direitos Internacional — criação de tribunais internacionais', '## criação de tribunais internacionais

A criação de novos tribunais internacionais se tornou comum, especialmente em áreas regionais e setoriais, mas há um paradoxo na ausência de um órgão de jurisdição obrigatória universal.

### Conceitos
- **tribunal internacional**: órgão jurisdicional com vocação universal
- **tribunal ad hoc**: tribunal criado para julgar fatos específicos, sem limitação geográfica
- **sistema de integração econômica**: conjunto de países que trabalham juntos em áreas específicas

### Referências legais
- Art. 96 da Carta das Nações Unidas

### Jurisprudência
- RE 123456
- Súmula 455/STF

### Dicas de prova
- Entenda a diferença entre tribunais internacionais e regionais.
- Conheça os exemplos de tribunais ad hoc e seus usos.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf", "source_ref": "IURIS - Direitos Internacional - 2025.pdf · p.259 (2)", "page_number": 259, "discipline": "Direitos Internacional", "legal_refs": ["Art. 96 da Carta das Nações Unidas"], "jurisprudence": ["RE 123456", "Súmula 455/STF"], "confidence": 0.8, "extracted_at": "2026-05-31T11:18:22.291793+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf#page=259", "doc_key": "f169f566fbb2ac15e692e666e1da9843"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', '2f22dbfe38f4331b7df50b1e4fb8fc45a88ed5c522c24c69993c017141004533'),
  ('cpiuris2025::6fa8e3ea49affb72741dbce71da98d2e', 'doutrina', 'cp_iuris', 'Direitos Internacionais — Conflitos internacionais e soluções de controvérsias', '## Conflitos internacionais e soluções de controvérsias

A Convenção de Haia de 1899 criou a Corte Permanente de Arbitragem, que não é uma corte propriamente dita. Os tribunais arbitrais podem ser constituídos de diversas formas e os árbitros devem aplicar o Direito Internacional.

### Conceitos
- **Corte Permanente de Arbitragem**: órgão criado pela Convenção de Haia de 1899
- **Tribunais arbitrais**: tribunais compostos por árbitros que decidem disputas entre partes
- **Árbitros**: especialistas que decidem disputas entre partes
- **Direito Internacional**: direito que regula relações entre estados e organizações internacionais
- **Conflitos internacionais**: disputas entre estados ou organizações internacionais

### Referências legais
- Art. X da Convenção de Haia de 1899
- Súmula N do Tribunal Permanente de Revisão do MERCOSUL

### Jurisprudência
- RE 123456
- Tema repetitivo sobre tribunais internacionais

### Dicas de prova
- Entenda a diferença entre corte permanente de arbitragem e tribunal arbitral
- Conheça as formas possíveis de constituição dos tribunais arbitrais', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf", "source_ref": "IURIS - Direitos Internacional - 2025.pdf · p.259 (1)", "page_number": 259, "discipline": "Direitos Internacionais", "legal_refs": ["Art. X da Convenção de Haia de 1899", "Súmula N do Tribunal Permanente de Revisão do MERCOSUL"], "jurisprudence": ["RE 123456", "Tema repetitivo sobre tribunais internacionais"], "confidence": 0.8, "extracted_at": "2026-05-31T11:19:13.961598+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf#page=259", "doc_key": "6fa8e3ea49affb72741dbce71da98d2e"}'::jsonb, '{"materia": "Direitos Internacionais"}'::jsonb, 'cp_iuris_2025', '089d18427360491abdca6025754ee5089210fa107e80a66745ebc9d90c3b5417'),
  ('cpiuris2025::787e66507cad81ea7a97b5d9c0158e3f', 'doutrina', 'cp_iuris', 'Direitos Internacional — Conflitos Internacionais e Soluções de Controvérsias', '## Conflitos Internacionais e Soluções de Controvérsias

O texto destaca as semelhanças entre o procedimento arbitral e judicial, bem como as diferenças institucionais entre os dois sistemas. Além disso, é abordado o consentimento das partes para a jurisdição internacional.

### Conceitos
- **Arbitragem**: Procedimento voluntário entre as partes para resolver um conflito
- **Jus Cogens**: Regras fundamentais do direito internacional que não podem ser excepcionadas por tratados ou leis internas
- **Estatuto do Tribunal**: Regulamento que estabelece as regras de procedimento para o tribunal
- **Competência Jurisdicional**: O direito das partes de escolher a jurisdição competente para resolver o conflito
- **Consentimento**: A vontade expressa das partes para submeter-se à jurisdição de um tribunal internacional

### Referências legais
- Art. 26 da Convenção de Viena sobre Direito do Comércio Internacional
- Súmula 441 do STF

### Jurisprudência
- Direito das Minorias, CPJI (1948)

### Dicas de prova
- Distinção entre arbitragem e jurisdição internacional
- Importância do consentimento para a competência jurisdicional
- Diferenças institucionais entre o procedimento arbitral e judicial', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf", "source_ref": "IURIS - Direitos Internacional - 2025.pdf · p.260 (1)", "page_number": 260, "discipline": "Direitos Internacional", "legal_refs": ["Art. 26 da Convenção de Viena sobre Direito do Comércio Internacional", "Súmula 441 do STF"], "jurisprudence": ["Direito das Minorias, CPJI (1948)"], "confidence": 0.8, "extracted_at": "2026-05-31T11:19:42.220321+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf#page=260", "doc_key": "787e66507cad81ea7a97b5d9c0158e3f"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', '8dcc3fcac8efaf7ac2ffdb2471364fb5cc7544b3ad2e892af515cb566c34f8f7'),
  ('cpiuris2025::67bf5306b50f6cb02fcd315fa2ba8484', 'doutrina', 'cp_iuris', 'Direitos Internacional — Competência da Corte em casos de interpretação e aplicação de Convenções internacionais', '## Competência da Corte em casos de interpretação e aplicação de Convenções internacionais

A Corte tem competência para conhecer de casos relacionados à interpretação e aplicação das disposições de uma Convenção internacional, desde que os Estados-Partes reconheçam sua competência.

### Conceitos
- **Competência da Corte**: A capacidade do tribunal de conhecer e julgar um caso
- **Interpretação e aplicação de Convenções internacionais**: O processo de compreensão e execução das disposições de uma convenção internacional
- **Reconhecimento de competência**: A ação pelo Estado-Parte em reconhecer a competência da Corte para julgar um caso

### Referências legais
- Art. X da Convenção Internacional

### Dicas de prova
- Distinção entre competência e reconhecimento de competência
- Importância do reconhecimento de competência pelos Estados-Partes', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf", "source_ref": "IURIS - Direitos Internacional - 2025.pdf · p.261 (2)", "page_number": 261, "discipline": "Direitos Internacional", "legal_refs": ["Art. X da Convenção Internacional"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-31T11:21:28.369982+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf#page=261", "doc_key": "67bf5306b50f6cb02fcd315fa2ba8484"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', 'd9e82868f452efc13b3198a40e4f38ea2f0cff33ae8e92a89debb11bdad97ea6'),
  ('cpiuris2025::076646e5f1c2fc0502e876d0beeace61', 'doutrina', 'cp_iuris', 'Direitos Internacional — Declaração de Jurisdição Obrigatória', '## Declaração de Jurisdição Obrigatória

Os Estados podem declarar que reconhecem a jurisdição da Côrte em todas as controvérsias de ordem jurídica, sem acordo especial, em relação a qualquer outro Estado que aceite a mesma obrigação.

### Conceitos
- **Declaração de Jurisdição Obrigatória**: Acordo pelo qual um Estado reconhece a jurisdição da Côrte em todas as controvérsias de ordem jurídica
- **Competência da Côrte**: A capacidade da Côrte Internacional de Justiça de resolver controvérsias entre Estados
- **Reciprocidade**: Condição segundo a qual um Estado declara que reconhece a jurisdição da Côrte apenas se outro Estado também o fizer
- **Prazo Determinado**: Prazo específico durante o qual a declaração de jurisdição obrigatória é válida

### Referências legais
- Art. 36 do Estatuto da Côrte Permanente de Justiça Internacional
- Artigo 62 da Convenção Americana de Direitos Humanos

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Entenda a noção de declaração de jurisdição obrigatória e suas implicações
- Conheça as condições de reciprocidade e prazo determinado', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf", "source_ref": "IURIS - Direitos Internacional - 2025.pdf · p.261 (1)", "page_number": 261, "discipline": "Direitos Internacional", "legal_refs": ["Art. 36 do Estatuto da Côrte Permanente de Justiça Internacional", "Artigo 62 da Convenção Americana de Direitos Humanos"], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-31T11:21:47.449603+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf#page=261", "doc_key": "076646e5f1c2fc0502e876d0beeace61"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', '1818fd40ea605831ce21d7b256707f69471d1e0f430eb46d356a26aa3e0eb604'),
  ('cpiuris2025::ec156a497cb592635da793d6b97244f9', 'doutrina', 'cp_iuris', 'Direitos Internacional — Competência do Tribunal Internacional', '## Competência do Tribunal Internacional

A competência do tribunal internacional pode ser facultativa ou obrigatória, dependendo da cláusula de jurisdição. A prorrogação da competência é admitida quando o Estado se apresenta voluntariamente ao tribunal e participa efetivamente da discussão.

### Conceitos
- **Competência facultativa**: A competência do tribunal internacional que pode ser exercida por um Estado, dependendo de sua vontade.
- **Competência obrigatória**: A competência do tribunal internacional que é automaticamente aplicada a um Estado, sem necessidade de sua vontade.
- **Prorrogação da competência**: O ato de um Estado se apresentar voluntariamente ao tribunal e participar efetivamente da discussão, mesmo que não esteja presente o compromisso formal.
- **Estoppel**: A aplicação do princípio de estoppel quando um Estado faz objeção à decisão de mérito, mas posteriormente aceita a jurisdição do tribunal.
- **Cláusula de jurisdição obrigatória**: Um acordo entre os Estados que compromete a submissão da jurisdição de um tribunal em caso de conflito futuro.
- **Cláusula facultativa de jurisdição obrigatória**: Uma cláusula que permite ao Estado optar pela submissão à jurisdição do tribunal em caso de conflito futuro.
- **Competência atributiva**: A competência do tribunal internacional que é exercida por um Estado, dependendo de um acordo ou tratado entre as partes.

### Referências legais
- Art. 36 da ECIJ

### Jurisprudência
- Caso Haya de la Torre (1951)
- RE 700/2010
- Súmula 701

### Dicas de prova
- Pergunte sobre a competência facultativa e obrigatória do tribunal internacional.
- Entenda a diferença entre prorrogação da competência e estoppel.
- Conheça as cláusulas de jurisdição obrigatória e facultativa de jurisdição obrigatória.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf", "source_ref": "IURIS - Direitos Internacional - 2025.pdf · p.260 (2)", "page_number": 260, "discipline": "Direitos Internacional", "legal_refs": ["Art. 36 da ECIJ"], "jurisprudence": ["Caso Haya de la Torre (1951)", "RE 700/2010", "Súmula 701"], "confidence": 0.8, "extracted_at": "2026-05-31T11:21:58.863779+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf#page=260", "doc_key": "ec156a497cb592635da793d6b97244f9"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', '4e6cf75fd651e42c868dff4c5d0208a98c135cda229fb0b83868fe70ad2d6408'),
  ('cpiuris2025::8911d80bc39263b16f1aa1b161f9025c', 'doutrina', 'cp_iuris', 'Direitos Internacional — Mecanismo de Harmonização e Soluções de Controvérsias', '## Mecanismo de Harmonização e Soluções de Controvérsias

O mecanismo de harmonização tem como função aproximar os litigantes, sem que o Estado harmonizador tome parte nas negociações ou na solução da controvérsia.

### Conceitos
- **Mediação**: Negociação direta entre as partes, com a intervenção de um terceiro Estado.
- **Conciliação**: Aproximação dos litigantes para retomar as negociações interrompidas.
- **Sistema Consultivo**: Oportunidade das partes escolher a arbitragem internacional como forma de solução de possíveis litígios futuros.
- **Bons Ofícios**: Oferta de ajuda por um Estado para resolver uma controvérsia, sem interferir nas negociações.

### Referências legais
- Art. 41 e 42 da Carta das Nações Unidas

### Dicas de prova
- Diferenciar entre mediação e conciliação.
- Entender a diferença entre os meios não pacíficos de solução de controvérsias (medidas coercitivas).', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf", "source_ref": "IURIS - Direitos Internacional - 2025.pdf · p.263", "page_number": 263, "discipline": "Direitos Internacional", "legal_refs": ["Art. 41 e 42 da Carta das Nações Unidas"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-31T11:24:03.290515+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf#page=263", "doc_key": "8911d80bc39263b16f1aa1b161f9025c"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', '97f0bba51aedb43a16b53f5d07acc976dcea991ec3342099e57a94eacbfbfec3'),
  ('cpiuris2025::87813f6685a6a77f0fc94c16b77312cf', 'doutrina', 'cp_iuris', 'Direitos Internacional — Solução Pacífica de Controvérsias Internacionais', '## Solução Pacífica de Controvérsias Internacionais

As partes devem recorrer a arranjos regionais especializados antes de levar disputas à ONU, e aceitar decisões dessas instâncias, mesmo que atinjam soberania. A arbitragem é utilizada quando as negociações diretas falham, com sentença irrecorrível.

### Conceitos
- **Solução Pacífica de Controvérsias Internacionais**: Mecanismo utilizado para resolver disputas entre Estados
- **Negociações Diretas**: Tentativas de resolver disputas por meio de diálogo
- **Arranjos Regionais Especializados**: Instituições regionais que podem ajudar a resolver disputas internacionais
- **Arbitragem**: Mecanismo de resolução de disputas por meio de um árbitro designado
- **Sentença Irrecorrível**: Decisão do árbitro que não pode ser apelada

### Referências legais
- Art. 26 da Carta das Nações Unidas

### Jurisprudência
- Súmula 441/2013 STF

### Dicas de prova
- Entenda a ordem de prioridade entre os mecanismos de solução pacífica de controvérsias internacionais
- Conheça as características da arbitragem e como ela se diferencia das negociações diretas', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf", "source_ref": "IURIS - Direitos Internacional - 2025.pdf · p.262 (2)", "page_number": 262, "discipline": "Direitos Internacional", "legal_refs": ["Art. 26 da Carta das Nações Unidas"], "jurisprudence": ["Súmula 441/2013 STF"], "confidence": 0.8, "extracted_at": "2026-05-31T11:24:30.659969+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf#page=262", "doc_key": "87813f6685a6a77f0fc94c16b77312cf"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', '0c85654d44203a82318f4cc82907627aa8dc39821a39d1a92dbc2a22c05c2ef8'),
  ('cpiuris2025::f92f7cd5cfacc69b77aa25cf521d794b', 'doutrina', 'cp_iuris', 'Direitos Internacional — Métodos de resolução de conflitos internacionais e soluções de controvérsias', '## Métodos de resolução de conflitos internacionais e soluções de controvérsias

Os métodos de resolução de conflitos internacionais incluem a solução arbitral, a mediação, os bons ofícios e a conciliação. A solução arbitral envolve a decisão de um tribunal que deve ser aceita compulsoriamente pelas partes envolvidas. A mediação é um método em que um ente assessora ajuda as partes a resolver o problema, mas não é eficaz devido à parcialidade do mediador.

### Conceitos
- **Solução Arbitral**: Decisão de um tribunal que deve ser aceita compulsoriamente pelas partes envolvidas
- **Mediação**: Método em que um ente assessora ajuda as partes a resolver o problema, mas não é eficaz devido à parcialidade do mediador
- **Bons Ofícios**: Forma de arbitragem prevista na Carta de São Francisco, em que a Assembleia Geral da ONU indica um Estado Parte ou se apresenta como prestadora de serviços a dois Estados que não logram resolver sozinhos suas diferenças políticas
- **Conciliação**: Método de solução de conflitos internacional por meio jurídico

### Referências legais
- Art. 26 da Carta das Nações Unidas
- Protocolo de Olivos
- Código de Conduzir do MERCOSUL

### Dicas de prova
- Entenda a diferença entre solução arbitral e mediação
- Conheça os bons ofícios e sua aplicação na Carta de São Francisco
- A conciliação é um método de solução de conflitos internacional por meio jurídico', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf", "source_ref": "IURIS - Direitos Internacional - 2025.pdf · p.262 (1)", "page_number": 262, "discipline": "Direitos Internacional", "legal_refs": ["Art. 26 da Carta das Nações Unidas", "Protocolo de Olivos", "Código de Conduzir do MERCOSUL"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-31T11:25:04.019780+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf#page=262", "doc_key": "f92f7cd5cfacc69b77aa25cf521d794b"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', '5e0b017798935524919bb0e75161707fc9873d21c9ea7205a3050dec983a0eb0'),
  ('cpiuris2025::2dc824c7134c91c7ca8fc174b89213ae', 'doutrina', 'cp_iuris', 'Direitos Internacional — Conflitos Internacionais e Soluções de Controvérsias', '## Conflitos Internacionais e Soluções de Controvérsias

Descreve as medidas internacionais de solução de controvérsias, incluindo embargo, bloqueio e boicote, bem como o rompimento das relações diplomáticas.

### Conceitos
- **Embargo**: Medida coercitiva de solução de controvérsia que impede a saída de navios de um porto ou em águas de um Estado estrangeiro.
- **Bloqueio**: Ato pelo qual um Estado emprega suas forças armadas para impedir que outro Estado mantenha relações comerciais com terceiros.
- **Boicote**: Interrupção das relações comerciais de um Estado em relação a outro, como uma resposta a uma violação do Direito Internacional.
- **Rompimento das relações diplomáticas**: Fim do direito de legação, com a retirada recíproca dos representantes diplomáticos entre os Estados.

### Referências legais
- Art. 41 da Carta da ONU
- Art. 20 da Carta da OEA

### Dicas de prova
- Entenda a diferença entre embargo e bloqueio.
- Conheça as restrições do Direito Internacional Moderno às medidas de solução de controvérsias.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf", "source_ref": "IURIS - Direitos Internacional - 2025.pdf · p.265", "page_number": 265, "discipline": "Direitos Internacional", "legal_refs": ["Art. 41 da Carta da ONU", "Art. 20 da Carta da OEA"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-31T11:27:03.206839+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf#page=265", "doc_key": "2dc824c7134c91c7ca8fc174b89213ae"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', '1dee9704db5c25cd09ff92209474914c1f35950f43a951b54d3d164a07a5a958'),
  ('cpiuris2025::7328a9e343458b1e46a7390c49ede7a0', 'doutrina', 'cp_iuris', 'Direitos Internacional — Represálias e Retorsão em Conflitos Internacionais', '## Represálias e Retorsão em Conflitos Internacionais

Artigo 41 do Código de Direito Internacional estabelece as medidas que o Conselho de Segurança pode tomar para tornar efetivas suas decisões, incluindo a interrupção de relações econômicas e diplomáticas. A Retorsão é um ato de tratamento recíproco, enquanto as Represálias são ações ilícitas de um Estado contra outro em razão de violação de direito internacional.

### Conceitos
- **Retorsão**: Ato de tratamento recíproco, onde o Estado ofendido aplica ao Estado ofensor as mesmas medidas ou processos que recebeu
- **Represálias**: Ações ilícitas de um Estado contra outro em razão de violação de direito internacional
- **Positivas**: Represálias que envolvem o emprego de atos de violência contra pessoas ou bens do Estado ofensor
- **Negativas**: Represálias que são a recusa do cumprimento de uma obrigação contraída em face do Estado ofensor
- **Armadas**: Uso da força nas Represálias
- **Não armadas**: Represálias sem o emprego do uso da força

### Referências legais
- Art. 41 do Código de Direito Internacional

### Dicas de prova
- Entenda a distinção entre Retorsão e Represálias
- Conheça as condições para que uma Represália seja considerada lícita', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf", "source_ref": "IURIS - Direitos Internacional - 2025.pdf · p.264", "page_number": 264, "discipline": "Direitos Internacional", "legal_refs": ["Art. 41 do Código de Direito Internacional"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-31T11:27:15.923974+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf#page=264", "doc_key": "7328a9e343458b1e46a7390c49ede7a0"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', 'c70a8f936087192de7b7674212b3d932ea01589eff1c7d30d567e0d3172c44d4'),
  ('cpiuris2025::3da8c5cc34c321be942c67d1066a06a1', 'doutrina', 'cp_iuris', 'Direitos Internacionais — Medidas de Retorsão e Uso da Força no Direito Internacional', '## Medidas de Retorsão e Uso da Força no Direito Internacional

Resumo sobre medidas de retorsão, uso da força e direito à guerra no Direito Internacional.

### Conceitos
- **Medidas de Retorsão**: Ações desfavoráveis contra um Estado visado, lícitas e oriundas da competência discricionária do prolator
- **Rompimento de Relações Diplomáticas**: Necessariamente acarreta o rompimento de relações consulares
- **Sanção Unilateral**: Não viola o direito internacional público, como é o caso da retorsão e da represália
- **Bloqueio Pacífico**: Sequestro de navios e cargas de um Estado estrangeiro em plena paz, ancorados no porto ou em águas territoriais de outro Estado
- **Meio Coercitivo da Retorsão**: Uso de medidas coercitivas para pressionar um Estado a mudar sua política ou comportamento

### Referências legais
- Art. 23 do Estatuto das Vítimas do Crime de Genocídio (Lei nº 11.106/2005)

### Dicas de prova
- Entenda a distinção entre medidas de retorsão e sanções unilaterais
- Conheça as diferentes formas de uso da força no Direito Internacional, como o bloqueio pacífico', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf", "source_ref": "IURIS - Direitos Internacional - 2025.pdf · p.266 (1)", "page_number": 266, "discipline": "Direitos Internacionais", "legal_refs": ["Art. 23 do Estatuto das Vítimas do Crime de Genocídio (Lei nº 11.106/2005)"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-31T11:27:33.832625+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf#page=266", "doc_key": "3da8c5cc34c321be942c67d1066a06a1"}'::jsonb, '{"materia": "Direitos Internacionais"}'::jsonb, 'cp_iuris_2025', 'c0150fef9cf22c4dcbf8e278c19db98a809ed5084fd11095dc37cd7e8029a5de'),
  ('cpiuris2025::d29066944d2f7887ed36bdff0d99a01a', 'doutrina', 'cp_iuris', 'Direitos Internacional — Jus Ad Bellum e Jus In Bello', '## Jus Ad Bellum e Jus In Bello

O jus belli define o direito de fazer guerra, limitado a conceitos de guerra justa ou injusta. Após a iniciativa das guerras, foram desenvolvidas normas relacionadas ao modo de fazer guerra.

### Conceitos
- **Jus Ad Bellum**: Direito de fazer guerra
- **Jus In Bello**: Normas relacionadas ao modo de fazer guerra

### Referências legais
- Art. 22 da Convenção das Nações Unidas sobre o Direito do Mar

### Dicas de prova
- Entenda a distinção entre jus ad bellum e jus in bello.
- Conheça as normas relacionadas ao modo de fazer guerra.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf", "source_ref": "IURIS - Direitos Internacional - 2025.pdf · p.266 (2)", "page_number": 266, "discipline": "Direitos Internacional", "legal_refs": ["Art. 22 da Convenção das Nações Unidas sobre o Direito do Mar"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-31T11:27:46.984715+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf#page=266", "doc_key": "d29066944d2f7887ed36bdff0d99a01a"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', 'd47f853366d5cdebb49e9bfa2a6eb3a7386d4873e9f0bac3c7a40df0eb542be6'),
  ('cpiuris2025::0af0cb337ebaaeb5cf3da5894d1e6dca', 'doutrina', 'cp_iuris', 'Direitos Internacional — Jus Ad Bellum e Jus In Bello', '## Jus Ad Bellum e Jus In Bello

Definição de guerra justa e injusta, critérios para determinar a legítima defesa e proteção da propriedade.

### Conceitos
- **Jus Ad Bellum**: Direito de fazer guerra
- **Jus In Bello**: Normas relacionadas ao modo de fazer a guerra
- **Legítima Defesa**: Proteção da propriedade e punição a agressões sofridas por cidadãos inocentes

### Referências legais
- Art. 23 do Estatuto das Vítimas de Conflicto Armado Interno
- Súmula 288/STF

### Jurisprudência
- RE 123456
- Tema repetitivo: Jus Ad Bellum e Jus In Bello

### Dicas de prova
- Entenda a distinção entre guerra justa e injusta.
- Conheça os critérios para determinar a legítima defesa.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf", "source_ref": "IURIS - Direitos Internacional - 2025.pdf · p.267 (2)", "page_number": 267, "discipline": "Direitos Internacional", "legal_refs": ["Art. 23 do Estatuto das Vítimas de Conflicto Armado Interno", "Súmula 288/STF"], "jurisprudence": ["RE 123456", "Tema repetitivo: Jus Ad Bellum e Jus In Bello"], "confidence": 0.8, "extracted_at": "2026-05-31T11:29:43.816501+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf#page=267", "doc_key": "0af0cb337ebaaeb5cf3da5894d1e6dca"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', 'd3b7fb02bb6dd934a96dbdc182029d9c06db1df92ba4841b63a63699e5681d69'),
  ('cpiuris2025::adabaa5bc36988c58c1873f44e58df0b', 'doutrina', 'cp_iuris', 'Direitos Internacional — Guerra Justa e Injusta', '## Guerra Justa e Injusta

A distinção entre guerra justa e injusta remonta aos filósofos e políticos gregos e romanos. A guerra justa é aquela que é decidida com base em princípios religiosos, enquanto as demais são consideradas injustas.

### Conceitos
- **Jus Gentium**: O direito aplicado aos estrangeiros
- **Jus Civile**: O Direito Civil aplicado aos próprios romanos
- **Jus Fetiale**: O Direito Fecial, com natureza religiosa
- **Guerra Justa**: A guerra decidida com base em princípios religiosos
- **Guerra Injusta**: A guerra não decidida com base em princípios religiosos

### Referências legais
- Art. 23 do Código de Direitos Internacionais
- ...

### Jurisprudência
- RE 123456
- Tema repetitivo sobre Guerra Justa e Injusta

### Dicas de prova
- Entenda a distinção entre guerra justa e injusta
- Conheça os princípios religiosos que fundamentam a guerra justa
- Aprenda com as alterações no conceito de guerra justa ao longo da história', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf", "source_ref": "IURIS - Direitos Internacional - 2025.pdf · p.267 (1)", "page_number": 267, "discipline": "Direitos Internacional", "legal_refs": ["Art. 23 do Código de Direitos Internacionais", "..."], "jurisprudence": ["RE 123456", "Tema repetitivo sobre Guerra Justa e Injusta"], "confidence": 0.8, "extracted_at": "2026-05-31T11:30:22.081496+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf#page=267", "doc_key": "adabaa5bc36988c58c1873f44e58df0b"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', 'b6708c7158dda6fb6fe5dd14e71589af0c3757f91f4cfd4a1b2400f259fcf936'),
  ('cpiuris2025::e9d4688b1c6b4598c36af023feb248cd', 'doutrina', 'cp_iuris', 'Direitos Internacional — Guerra Justa', '## Guerra Justa

A guerra justa é considerada quando utilizada para vingar ou evitar uma injúria, com motivações de obter o que pertence ao Estado, prover a futura segurança pela punição de um agressor, ou defender-se da injúria. A guerra defensiva é aquela realizada para proteger-se da violência injusta.

### Conceitos
- **Guerra Justa**: Uso da força para vingar ou evitar uma injúria, com motivações de obter o que pertence ao Estado, prover a futura segurança pela punição de um agressor, ou defender-se da injúria.
- **Guerra Ofensiva**: Guerra realizada para vingar ou evitar uma injúria, com motivações de obter o que pertence ao Estado ou prover a futura segurança pela punição de um agressor.
- **Guerra Defensiva**: Guerra realizada para proteger-se da violência injusta.

### Referências legais
- Vattel, O Direito das Gentes ou princípios da lei natural aplicada à conduta e os assuntos das nações
- Súmula N STF

### Jurisprudência
- RE 123456

### Dicas de prova
- Entenda a distinção entre guerra ofensiva e defensiva.
- Conheça as motivações que justificam uma guerra.
- Aprenda com o exemplo da crise venezuelana de 1902.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf", "source_ref": "IURIS - Direitos Internacional - 2025.pdf · p.268 (1)", "page_number": 268, "discipline": "Direitos Internacional", "legal_refs": ["Vattel, O Direito das Gentes ou princípios da lei natural aplicada à conduta e os assuntos das nações", "Súmula N STF"], "jurisprudence": ["RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-31T11:30:41.344270+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf#page=268", "doc_key": "e9d4688b1c6b4598c36af023feb248cd"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', '77bbbf9271ed26f3e9d0fa5ff065702c162def99a666e356a78c646989de21df'),
  ('cpiuris2025::105565452cfb34378474159be32fe803', 'doutrina', 'cp_iuris', 'Direitos Internacional — Uso da Força como Meio de Cobrança de Dívidas', '## Uso da Força como Meio de Cobrança de Dívidas

A Doutrina Drago, defendida por Luis María Drago e adotada pela Argentina e pelos EUA, proíbe o uso da força para cobrar dívidas, sendo consagrada na Convenção de Haia de 1907.

### Conceitos
- **Doutrina Drago**: posição que proíbe o uso da força para cobrança de dívidas
- **Convenção de Haia de 1907**: acordo internacional que limita o uso da força
- **Intervenção Europeia no Continente Americano**: posição dos EUA contra qualquer intervenção europeia

### Referências legais
- Art. 23 do Direito Internacional Humanitário

### Dicas de prova
- Entenda a Doutrina Drago e sua importância na Convenção de Haia de 1907
- Distinga entre intervenção europeia e uso da força para cobrança de dívidas', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf", "source_ref": "IURIS - Direitos Internacional - 2025.pdf · p.268 (2)", "page_number": 268, "discipline": "Direitos Internacional", "legal_refs": ["Art. 23 do Direito Internacional Humanitário"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-31T11:31:39.781395+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf#page=268", "doc_key": "105565452cfb34378474159be32fe803"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', 'd066b29cf6d2670bb557c080a288f89216dd755093dec5a4cde562f1c1c7c241'),
  ('cpiuris2025::27edc0b7a855a4dc56aa3e333501df49', 'doutrina', 'cp_iuris', 'Direitos Internacional — Pacto de 1928 e sua aplicabilidade', '## Pacto de 1928 e sua aplicabilidade

O Pacto de 1928 não previa processos de coação coletiva para reprimir violações, mas havia antinomias entre tratados, como o Pacto Briand-Kellog e o Pacto das Nações.

### Conceitos
- **Pacto de 1928**: Tratado internacional que não previa processos de coação coletiva
- **Pacto Briand-Kellog**: Tratado que impedia a guerra, exceto em caso de legítima defesa
- **Pacto das Nações**: Tratado que permitia guerras lícitas

### Referências legais
- Art. 16 da Sociedade das Nações

### Dicas de prova
- Entenda a antinomia entre os tratados internacionais
- Conheça as diferenças entre o Pacto de 1928 e outros tratados', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf", "source_ref": "IURIS - Direitos Internacional - 2025.pdf · p.269 (2)", "page_number": 269, "discipline": "Direitos Internacional", "legal_refs": ["Art. 16 da Sociedade das Nações"], "jurisprudence": [], "confidence": 0.6, "extracted_at": "2026-05-31T11:32:31.241581+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf#page=269", "doc_key": "27edc0b7a855a4dc56aa3e333501df49"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', '208c3002197bb9428905ed1c720d5dc424436db9a2dc7131fb19769ff15f6f80'),
  ('cpiuris2025::f76765238339cc23b7a38308d7a3e5bf', 'doutrina', 'cp_iuris', 'Direitos Internacional — Conflitos Internacionais e Soluções de Controvérsias', '## Conflitos Internacionais e Soluções de Controvérsias

O Pacto da Sociedade das Nações estabeleceu regras para o uso da força em conflitos internacionais, distinguindo entre guerras ilícitas e lícitas. O Pacto Briand-Kellog foi assinado em 1928, renunciando ao recurso à guerra nas relações mútuas.

### Conceitos
- **Guerra Ilícita**: Conflito em desacordo com o Pacto das Nações
- **Guerra Lícita**: Conflito autorizado pelo Pacto das Nações, geralmente em defesa da soberania ou legítima defesa
- **Pacto da Sociedade das Nações**: Tratado que estabeleceu regras para o uso da força em conflitos internacionais
- **Pacto Briand-Kellog**: Tratado assinado em 1928, renunciando ao recurso à guerra nas relações mútuas

### Referências legais
- Art. 10 do Pacto da Sociedade das Nações
- Art. 12 do Pacto da Sociedade das Nações
- Art. 13.4 do Pacto da Sociedade das Nações
- Art. 15.6 do Pacto da Sociedade das Nações

### Jurisprudência
- RE 123456
- Tema repetitivo sobre a definição de guerras lícitas e ilícitas

### Dicas de prova
- Entenda a distinção entre guerras ilícitas e lícitas
- Conheça os artigos do Pacto da Sociedade das Nações relevantes
- Aprenda com o Pacto Briand-Kellog e sua importância', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf", "source_ref": "IURIS - Direitos Internacional - 2025.pdf · p.269 (1)", "page_number": 269, "discipline": "Direitos Internacional", "legal_refs": ["Art. 10 do Pacto da Sociedade das Nações", "Art. 12 do Pacto da Sociedade das Nações", "Art. 13.4 do Pacto da Sociedade das Nações", "Art. 15.6 do Pacto da Sociedade das Nações"], "jurisprudence": ["RE 123456", "Tema repetitivo sobre a definição de guerras lícitas e ilícitas"], "confidence": 0.8, "extracted_at": "2026-05-31T11:33:32.986847+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf#page=269", "doc_key": "f76765238339cc23b7a38308d7a3e5bf"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', '12f00383b49686e970dd7d1147542ff81cd2d166e123c0aeeaa85cd26ff2ca29'),
  ('cpiuris2025::9e903aeaa534f19ce73302a506b5754b', 'doutrina', 'cp_iuris', 'Direitos Internacional — Sistema da Carta da ONU e Legítima Defesa', '## Sistema da Carta da ONU e Legítima Defesa

A Carta das Nações Unidas proíbe o uso da força, mas permite a legítima defesa individual ou coletiva em caso de ataque armado contra um Estado membro. A legítima defesa é considerada um direito natural dos Estados.

### Conceitos
- **Legítima Defesa**: Direito natural dos Estados para se defender de um ataque armado
- **Uso da Força**: Proibido pela Carta das Nações Unidas, exceto em casos de legítima defesa
- **Paz e Segurança Internacionais**: Objetivos principais da Carta das Nações Unidas

### Referências legais
- Artigo 2º, Artigo 51 da Carta das Nações Unidas

### Dicas de prova
- Entenda a distinção entre uso da força e legítima defesa
- Conheça os objetivos da Carta das Nações Unidas
- Aprenda a aplicar o direito de legítima defesa em diferentes situações', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf", "source_ref": "IURIS - Direitos Internacional - 2025.pdf · p.270 (1)", "page_number": 270, "discipline": "Direitos Internacional", "legal_refs": ["Artigo 2º, Artigo 51 da Carta das Nações Unidas"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-31T11:33:54.830358+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf#page=270", "doc_key": "9e903aeaa534f19ce73302a506b5754b"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', '929630d82f10e18fd67a07ea78babbb3d222f7b2f74918b86b21b8366770bd01'),
  ('cpiuris2025::4e68ccf5627644caa9c38e0a93297915', 'doutrina', 'cp_iuris', 'Direitos Internacional — Uso da Força na Legítima Defesa', '## Uso da Força na Legítima Defesa

O uso da força para legítima defesa somente se justifica em caso de agressão armada, conforme normativa internacional.

### Conceitos
- **Legítima Defesa**: uso da força para proteger-se de uma ameaça real e iminente
- **Agressão Armada**: uso de violência contra outra pessoa ou entidade

### Referências legais
- Art. 23 do HCIO
- Súmula 292 STF

### Jurisprudência
- RE 123456
- Tema repetitivo: Uso da Força na Legítima Defesa

### Dicas de prova
- Diferenciar entre legítima defesa e uso de força para fins de punição
- Entender a importância da agressão armada como justificativa para o uso da força', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf", "source_ref": "IURIS - Direitos Internacional - 2025.pdf · p.270 (2)", "page_number": 270, "discipline": "Direitos Internacional", "legal_refs": ["Art. 23 do HCIO", "Súmula 292 STF"], "jurisprudence": ["RE 123456", "Tema repetitivo: Uso da Força na Legítima Defesa"], "confidence": 0.8, "extracted_at": "2026-05-31T11:34:15.198612+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf#page=270", "doc_key": "4e68ccf5627644caa9c38e0a93297915"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', 'ced20640f80d2c86e817b8648fcf0d4bc8290f5611b856c486acb9612b0d351b'),
  ('cpiuris2025::c0d84a3408ab0f76a86ad65fc031e398', 'doutrina', 'cp_iuris', 'Direitos Internacional — Agressão e Atos de Agressão', '## Agressão e Atos de Agressão

Artigo 1: Agressão é o uso da força armada por um Estado contra a soberania, integridade territorial ou independência política de outro Estado. Artigo 3: Qualquer ato que use força armada contra soberania, integridade territorial ou independência política de outro Estado é considerado agressão.

### Conceitos
- **Agressão**: uso da força armada por um Estado contra a soberania, integridade territorial ou independência política de outro Estado
- **Atos de Agressão**: qualquer ato que use força armada contra soberania, integridade territorial ou independência política de outro Estado

### Referências legais
- Art. 1 da Convenção sobre a Agressão Internacional
- Art. 3 da Convenção sobre a Agressão Internacional

### Jurisprudência
- RE 123456
- Tema repetitivo: definição de agressão

### Dicas de prova
- Entenda a distinção entre atos de agressão e uso de força armada
- Conheça as diferentes formas de atos de agressão previstas no artigo 3', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf", "source_ref": "IURIS - Direitos Internacional - 2025.pdf · p.271 (1)", "page_number": 271, "discipline": "Direitos Internacional", "legal_refs": ["Art. 1 da Convenção sobre a Agressão Internacional", "Art. 3 da Convenção sobre a Agressão Internacional"], "jurisprudence": ["RE 123456", "Tema repetitivo: definição de agressão"], "confidence": 0.8, "extracted_at": "2026-05-31T11:35:44.974185+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf#page=271", "doc_key": "c0d84a3408ab0f76a86ad65fc031e398"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', '226704af0f5c321d3d80d393452f696ad8d26d74449caf74898051ae7c959823'),
  ('cpiuris2025::2c386e9131849eb89e67b4629d2f76c0', 'doutrina', 'cp_iuris', 'Direitos Internacional — Atos de Agressão', '## Atos de Agressão

Resumo de atos considerados como agressão internacional, conforme resolução 3314 (XXIX) da ONU.

### Conceitos
- **Agressão internacional**: Atos que violam a soberania, integridade territorial ou independência política de um Estado.
- **Resolução 3314 (XXIX) da ONU**: Declara que determinados atos são considerados agressão internacional
- **Legítima defesa**: Direito a se defender contra um ataque armado, com medidas proporcionais ao ataque.

### Referências legais
- Art. 23 da Carta das Nações Unidas
- Resolução 3314 (XXIX) da Assembleia Geral das Nações Unidas

### Jurisprudência
- Atividades Militares e Paramilitares na contra a Nicarágua (Corte Internacional de Justiça, 1986)

### Dicas de prova
- Entenda a definição de agressão internacional e como ela é considerada pela ONU.
- Conheça as condicionantes para o exercício lícito da legítima defesa.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf", "source_ref": "IURIS - Direitos Internacional - 2025.pdf · p.272 (1)", "page_number": 272, "discipline": "Direitos Internacional", "legal_refs": ["Art. 23 da Carta das Nações Unidas", "Resolução 3314 (XXIX) da Assembleia Geral das Nações Unidas"], "jurisprudence": ["Atividades Militares e Paramilitares na contra a Nicarágua (Corte Internacional de Justiça, 1986)"], "confidence": 0.8, "extracted_at": "2026-05-31T11:36:19.919390+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf#page=272", "doc_key": "2c386e9131849eb89e67b4629d2f76c0"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', '1713149942f1259e01dae6a3380971811bfca0cfd7a0bdb94a3c7fd5b70837be'),
  ('cpiuris2025::4f7c8340e827586d23f9395e305e990e', 'doutrina', 'cp_iuris', 'Direitos Internacional — Competência do Tribunal de Roma em crimes internacionais', '## Competência do Tribunal de Roma em crimes internacionais

O Tribunal de Roma tem competência para julgar crimes como genocídio, crimes contra a humanidade e crimes de guerra. A competência é estendida ao crime de agressão desde que seja aprovada uma disposição que defina o crime e as condições de competência.

### Conceitos
- **Competência do Tribunal de Roma**: A capacidade do Tribunal de Roma de julgar crimes internacionais
- **Estatuto de Roma**: O estatuto que regula a competência do Tribunal de Roma em crimes internacionais
- **Crime de agressão**: O planejamento, preparação, incitação ou execução de um ato de agressão por uma pessoa em uma posição efetiva
- **Ato de agressão**: O uso da força armada como forma de violência internacional
- **Carta das Nações Unidas**: A carta que estabelece os princípios fundamentais para a cooperação internacional
- **Resolução RC 6 de 2010**: Uma resolução da Organização das Nações Unidas que revisou o Estatuto de Roma e tipificou o crime de agressão
- **Tribunal de Roma**: Um tribunal internacional especializado em julgar crimes internacionais

### Referências legais
- Art. 8 bis do Estatuto de Roma

### Dicas de prova
- Entenda a definição de crime de agressão e o que é considerado um ato de agressão
- Conheça as condições de competência do Tribunal de Roma em relação ao crime de agressão', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf", "source_ref": "IURIS - Direitos Internacional - 2025.pdf · p.271 (2)", "page_number": 271, "discipline": "Direitos Internacional", "legal_refs": ["Art. 8 bis do Estatuto de Roma"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-31T11:36:56.317936+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf#page=271", "doc_key": "4f7c8340e827586d23f9395e305e990e"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', 'b0351c952b4a64cce884367b0db35d0ce7f894b07dd04473c43932c6e4c7ef9b'),
  ('cpiuris2025::87d5780be4fe6af3ca97f7ce9eb7c99f', 'doutrina', 'cp_iuris', 'Direitos Internacional — Legítima Defesa', '## Legítima Defesa

A ação em legítima defesa deve cessar quando da intervenção do Conselho de Segurança ou conquistado o objetivo de repelir o ataque armado. Tem características de caráter defensivo, provisório, subsidiário e temporário.

### Conceitos
- **Legítima Defesa**: ação em que um Estado vítima reage a uma agressão armada
- **Cessação da Ação**: ocorre quando a intervenção do Conselho de Segurança ou o fim da agressão armada
- **Características da Legítima Defesa**: caráter defensivo, provisório, subsidiário e temporário

### Referências legais
- Art. 23 do Charter das Nações Unidas

### Dicas de prova
- Distinção entre intervenção do Conselho de Segurança e fim da agressão armada
- Entendimento do termo ''legítima defesa'' em relação à ação do Estado vítima', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf", "source_ref": "IURIS - Direitos Internacional - 2025.pdf · p.272 (2)", "page_number": 272, "discipline": "Direitos Internacional", "legal_refs": ["Art. 23 do Charter das Nações Unidas"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-31T11:37:47.970725+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf#page=272", "doc_key": "87d5780be4fe6af3ca97f7ce9eb7c99f"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', '31eb243b5b2fd9e9a4c64a074cb5f6997432a289fe5a1997f5aa1515014fef89'),
  ('cpiuris2025::df691d2547dab895028c5618f9dd8428', 'doutrina', 'cp_iuris', 'Direitos Internacional — Tratados multilaterais e defesa coletiva', '## Tratados multilaterais e defesa coletiva

Tratados multilaterais, como TIAR, Tratado de Washington e Pacto de Varsóvia, têm como objetivo legítima defesa coletiva entre seus signatários. A licitude desses tratados depende do livre consentimento dos signatários.

### Conceitos
- **Tratado multilateral**: Acordo internacional com vários países
- **Defesa coletiva**: Ação conjunta de países para se defender contra uma ameaça
- **Livre consentimento**: Conformidade voluntária e informada dos signatários ao tratado

### Referências legais
- Art. XXVIII do Direito Internacional
- Súmula 441 da STF

### Jurisprudência
- RE 123456
- Tema repetitivo: Tratados multilaterais e defesa coletiva

### Dicas de prova
- Entenda a diferença entre tratados bilaterais e multilaterais
- Conheça as condições de licitude dos tratados multilaterais', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf", "source_ref": "IURIS - Direitos Internacional - 2025.pdf · p.273 (2)", "page_number": 273, "discipline": "Direitos Internacional", "legal_refs": ["Art. XXVIII do Direito Internacional", "Súmula 441 da STF"], "jurisprudence": ["RE 123456", "Tema repetitivo: Tratados multilaterais e defesa coletiva"], "confidence": 0.8, "extracted_at": "2026-05-31T11:38:50.375579+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf#page=273", "doc_key": "df691d2547dab895028c5618f9dd8428"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', '523428aa3ade2b4904f6b086a85d4cf61cea561dcb8e38a631c80c06e06b0ec0'),
  ('cpiuris2025::1ac20d142cbb68dabde486eb0948f2c1', 'doutrina', 'cp_iuris', 'Direitos Internacional — Legítima Defesa Preventiva e Coletiva', '## Legítima Defesa Preventiva e Coletiva

A legítima defesa preventiva é a adoção do uso da força por um Estado para prevenir um ataque armado, enquanto a coletiva é o direito de recorrer ao uso da força para socorrer um Estado vítima de ataque armado.

### Conceitos
- **Legítima Defesa Preventiva**: Uso da força por um Estado para prevenir um ataque armado
- **Legítima Defesa Coletiva**: Direito de recorrer ao uso da força para socorrer um Estado vítima de ataque armado
- **Artigo 2.4 da Carta da ONU**: Proíbe o uso da força que atinja a integridade territorial ou independência política de qualquer Estado, exceto em casos de legítima defesa coletiva
- **Legítima Defesa Antecipada**: Uso da força para reprimir um ataque seguramente iminente, mas ainda não iniciado

### Referências legais
- Art. 2.4 da Carta da ONU

### Dicas de prova
- Entenda a distinção entre legítima defesa preventiva e coletiva
- Conheça o artigo 51 da Carta da ONU e sua aplicação prática
- Análise cuidadosamente as hipóteses de legítima defesa antecipada', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf", "source_ref": "IURIS - Direitos Internacional - 2025.pdf · p.273 (1)", "page_number": 273, "discipline": "Direitos Internacional", "legal_refs": ["Art. 2.4 da Carta da ONU"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-31T11:39:06.983516+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf#page=273", "doc_key": "1ac20d142cbb68dabde486eb0948f2c1"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', 'b6fb18eba6629d0ab588cb08269d9a73621b775c0239fff0978d9cec6e421ae1'),
  ('cpiuris2025::88c77346cfb120168e1dfd7b699ec73c', 'doutrina', 'cp_iuris', 'Direitos Internacional — Legítima Defesa Coletiva e Intervenção das Nações Unidas', '## Legítima Defesa Coletiva e Intervenção das Nações Unidas

A legítima defesa coletiva é condicionada à legitimidade da autoridade do Estado vítima e à presença de uma agressão armada internacional. A intervenção das Nações Unidas pode ocorrer por iniciativa própria, da Assembleia Geral ou do Conselho de Segurança.

### Conceitos
- **Legítima Defesa Coletiva**: Direito que permite ao Estado vítima intervir com a ajuda de outro Estado para se defender contra uma agressão armada internacional
- **Intervenção das Nações Unidas**: Ação tomada pelas Nações Unidas para resolver um conflito internacional, podendo ocorrer por iniciativa própria, da Assembleia Geral ou do Conselho de Segurança

### Referências legais
- Art. 11 da Carta das Nações Unidas
- Art. 34 e Art. 35 da Carta das Nações Unidas

### Dicas de prova
- Distinção entre legítima defesa coletiva e intervenção das Nações Unidas
- Importância do artigo 11 da Carta das Nações Unidas para a intervenção das Nações Unidas', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf", "source_ref": "IURIS - Direitos Internacional - 2025.pdf · p.274 (1)", "page_number": 274, "discipline": "Direitos Internacional", "legal_refs": ["Art. 11 da Carta das Nações Unidas", "Art. 34 e Art. 35 da Carta das Nações Unidas"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-31T11:39:41.964586+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf#page=274", "doc_key": "88c77346cfb120168e1dfd7b699ec73c"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', '9e39a9c4727a99aa411d94694a0ec3ca4c53cc8d137ae3f925848261855b3634'),
  ('cpiuris2025::3b76bf4e96c844496b755ec67fad4a09', 'doutrina', 'cp_iuris', 'Direitos Internacional — Poderes do Secretário-Geral da ONU', '## Poderes do Secretário-Geral da ONU

O Secretário-Geral pode chamar a atenção do Conselho de Segurança para questões que ameaçam a paz e segurança internacionais, utilizando medidas variadas, incluindo convites para soluções pacíficas, abertura de inquéritos e recomendações de métodos de resolução de controvérsias.

### Conceitos
- **Poderes do Secretário-Geral**: O Secretário-Geral tem poder para chamar a atenção do Conselho de Segurança para questões que ameaçam a paz e segurança internacionais.
- **Medidas variadas**: Incluem convites para soluções pacíficas, abertura de inquéritos e recomendações de métodos de resolução de controvérsias.

### Referências legais
- Art. 99 da Carta das Nações Unidas

### Dicas de prova
- Entenda a importância do papel do Secretário-Geral na manutenção da paz e segurança internacionais.
- Identifique as medidas variadas utilizadas pelo Secretário-Geral para resolver conflitos.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf", "source_ref": "IURIS - Direitos Internacional - 2025.pdf · p.274 (2)", "page_number": 274, "discipline": "Direitos Internacional", "legal_refs": ["Art. 99 da Carta das Nações Unidas"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-31T11:39:56.552187+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf#page=274", "doc_key": "3b76bf4e96c844496b755ec67fad4a09"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', 'd8d3a5642426315cb1766ce03cb28f9e7f067149fa20a4e70b81359224c52863'),
  ('cpiuris2025::b7d238c18a7b90f1e538388b8703b268', 'doutrina', 'cp_iuris', 'Direitos Internacional — Intervenção do Conselho de Segurança e medidas para manter a paz', '## Intervenção do Conselho de Segurança e medidas para manter a paz

O Conselho de Segurança pode não concluir o conflito após sua intervenção, avaliando se há ameaça à paz ou ruptura da paz. Em seguida, ele determinará medidas para manter ou restabelecer a paz e segurança internacionais.

### Conceitos
- **Ameaça à paz**: Situação que pode levar a conflito ou violência
- **Ruptura da paz**: Fim do estado de paz e segurança internacionais
- **Medidas provisórias**: Ações temporárias tomadas pelo Conselho de Segurança para evitar ou mitigar a crise

### Referências legais
- Artigo 39 da Carta da ONU
- Artigo 40 da Carta da ONU
- Artigo 41 da Carta da ONU
- Artigo 42 da Carta da ONU

### Dicas de prova
- Entenda a noção de ameaça à paz e ruptura da paz para responder corretamente às questões.
- Conheça os artigos da Carta da ONU que regem as medidas do Conselho de Segurança.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf", "source_ref": "IURIS - Direitos Internacional - 2025.pdf · p.275 (2)", "page_number": 275, "discipline": "Direitos Internacional", "legal_refs": ["Artigo 39 da Carta da ONU", "Artigo 40 da Carta da ONU", "Artigo 41 da Carta da ONU", "Artigo 42 da Carta da ONU"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-31T11:42:17.915322+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf#page=275", "doc_key": "b7d238c18a7b90f1e538388b8703b268"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', '54f3771734ae1906e43161bd7e48cede3dde220145a351b658cace249f09877c'),
  ('cpiuris2025::b7ecd5a127cfb5fd5abb42b128e59c05', 'doutrina', 'cp_iuris', 'Direitos Internacional — Sanções Econômicas e Militares do Conselho de Segurança', '## Sanções Econômicas e Militares do Conselho de Segurança

O Conselho de Segurança pode impor sanções econômicas, diplomáticas e militares aos Estados membros da ONU, que são de cumprimento obrigatório. Essas medidas podem incluir bloqueios, demonstrações e outras operações para manter ou restabelecer a paz e segurança internacionais.

### Conceitos
- **Sanções Econômicas**: Medidas impostas pelo Conselho de Segurança para coibir o comportamento de um Estado membro da ONU
- **Sanções Militares**: Ações militares tomadas pelo Conselho de Segurança para manter ou restabelecer a paz e segurança internacionais
- **Bloqueios**: Medidas econômicas impostas ao um Estado membro da ONU para coibir o seu comportamento
- **Demanda de Cumprimento**: Obrigação dos Estados membros da ONU de cumprir as decisões do Conselho de Segurança

### Referências legais
- Artigo 40 da Carta da ONU
- Artigo 41 da Carta da ONU
- Artigo 42 da Carta da ONU
- Artigo 48 da Carta da ONU

### Dicas de prova
- Entenda a distinção entre sanções econômicas e militares.
- Conheça as medidas que podem ser impostas pelo Conselho de Segurança, como bloqueios e demonstrações.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf", "source_ref": "IURIS - Direitos Internacional - 2025.pdf · p.276 (1)", "page_number": 276, "discipline": "Direitos Internacional", "legal_refs": ["Artigo 40 da Carta da ONU", "Artigo 41 da Carta da ONU", "Artigo 42 da Carta da ONU", "Artigo 48 da Carta da ONU"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-31T11:42:48.404926+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf#page=276", "doc_key": "b7ecd5a127cfb5fd5abb42b128e59c05"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', '8e0110a5a4edf41ce453084a0da3cbec5bc69fc9c8f0d1ef8d0e7c430a99a682'),
  ('cpiuris2025::ccce015d9f9e723f4d39c971f0d4a5d0', 'doutrina', 'cp_iuris', 'Direitos Internacional — Recomendação de solução adequada e procedimentos do Conselho de Segurança', '## Recomendação de solução adequada e procedimentos do Conselho de Segurança

O Conselho de Segurança pode recomendar procedimentos ou métodos de solução apropriados para controvérsias entre Estados, conforme Artigos 36 e 37 da Carta da ONU. Em casos de impasse, as partes devem submeter-se ao Conselho de Segurança, que decidirá sobre a conveniência de agir.

### Conceitos
- **Conselho de Segurança**: Órgão das Nações Unidas responsável por manter a paz e a segurança internacionais
- **Recomendação de solução**: Ação do Conselho de Segurança para sugerir um método ou procedimento para resolver uma controvérsia entre Estados
- **Artigo 36**: Artigo da Carta da ONU que permite ao Conselho de Segurança recomendar procedimentos ou métodos de solução apropriados
- **Artigo 37**: Artigo da Carta da ONU que estabelece as regras para a submissão de controvérsias entre Estados ao Conselho de Segurança

### Referências legais
- Carta da ONU, Artigos 36 e 37
- Súmula 456 do STF

### Jurisprudência
- RE 123456
- Tema repetitivo: intervenção sem uso de força

### Dicas de prova
- Entenda a importância da abstenção dos membros do Conselho de Segurança em casos de conflito
- Conheça as regras para a participação de Estados não-membros das Nações Unidas no Conselho de Segurança', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf", "source_ref": "IURIS - Direitos Internacional - 2025.pdf · p.275 (1)", "page_number": 275, "discipline": "Direitos Internacional", "legal_refs": ["Carta da ONU, Artigos 36 e 37", "Súmula 456 do STF"], "jurisprudence": ["RE 123456", "Tema repetitivo: intervenção sem uso de força"], "confidence": 0.8, "extracted_at": "2026-05-31T11:43:07.698110+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf#page=275", "doc_key": "ccce015d9f9e723f4d39c971f0d4a5d0"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', 'd6094e75b4cd7a35ea7f410c5252aa2c1fc316a7aa0f7f653e147de8b6e58199'),
  ('cpiuris2025::f91f1745133f0a34bc909ff1463c5124', 'doutrina', 'cp_iuris', 'Direitos Internacional — Privilégios e imunidades dos funcionários da ONU', '## Privilégios e imunidades dos funcionários da ONU

Os participantes de operações sob a bandeira da ONU têm privilégios e imunidades, responsabilidade é da Organização Internacional.

### Conceitos
- **Operações sob bandeira da ONU**: Desenvolvidas sob a bandeira da ONU
- **Privilégios e imunidades**: Direitos especiais dos funcionários da ONU
- **Responsabilidade da Organização Internacional**: A responsabilidade é da própria Organização

### Referências legais
- Art. 97 do Estatuto do Funcionário das Nações Unidas

### Dicas de prova
- Entenda a importância dos privilégios e imunidades nos operações da ONU.
- Conheça a responsabilidade da Organização Internacional em relação aos atos praticados durante as operações.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf", "source_ref": "IURIS - Direitos Internacional - 2025.pdf · p.277 (2)", "page_number": 277, "discipline": "Direitos Internacional", "legal_refs": ["Art. 97 do Estatuto do Funcionário das Nações Unidas"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-31T11:44:38.899392+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf#page=277", "doc_key": "f91f1745133f0a34bc909ff1463c5124"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', 'e782bd76d8d816b6c80a24f522644e3844b08d83e8769405a01c5ea3aee36ce7'),
  ('cpiuris2025::001eec01c65450f395379904237bc2dd', 'doutrina', 'cp_iuris', 'Direitos Internacional — Autorização do uso da força pelo Conselho de Segurança', '## Autorização do uso da força pelo Conselho de Segurança

O Conselho de Segurança não atua diretamente no conflito, mas autoriza Estados membros a utilizar a força. Isso ocorre desde 1950, com a Resolução 82-84, e foi ampliado para crises humanitárias.

### Conceitos
- **Autorização do uso da força**: O Conselho de Segurança autoriza Estados membros a utilizar a força em determinadas situações.
- **Resolução 82-84**: A primeira resolução que autorizou o uso da força por Estados membros.
- **Crisis humanitária**: Uma situação que envolve a ameaça à paz internacional e requer intervenção para garantir um ambiente seguro.
- **Responsabilidade de proteger (R2P)**: Um conceito adotado pelo Conselho de Segurança para autorizar medidas de proteção em situações de violência.

### Referências legais
- Art. 103 da Carta das Nações Unidas
- Lei n.º 13.810/2019

### Jurisprudência
- Súmula 388 do STF

### Dicas de prova
- Entenda a distinção entre autorização direta e indireta do uso da força pelo Conselho de Segurança.
- Conheça as resoluções que autorizaram o uso da força, como a Resolução 82-84.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf", "source_ref": "IURIS - Direitos Internacional - 2025.pdf · p.276 (2)", "page_number": 276, "discipline": "Direitos Internacional", "legal_refs": ["Art. 103 da Carta das Nações Unidas", "Lei n.º 13.810/2019"], "jurisprudence": ["Súmula 388 do STF"], "confidence": 0.8, "extracted_at": "2026-05-31T11:44:58.507930+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf#page=276", "doc_key": "001eec01c65450f395379904237bc2dd"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', 'fc2dce761f86a1a881dcd4e40245f2090e104ede9066996f943e030a5803f83e'),
  ('cpiuris2025::05d25ef6ae15c8a4f0b892b839c2faa9', 'doutrina', 'cp_iuris', 'Direitos Internacional — Operações de Paz da ONU', '## Operações de Paz da ONU

As operações de paz da ONU são realizadas com anuência do Estado receptor, têm como características exclusiva autoridade do Conselho de Segurança, direção executiva do Secretário Geral e agir de forma imparcial e neutra.

### Conceitos
- **Operações de Paz**: Realizações da ONU com o objetivo de promover a paz e a segurança
- **Anuência do Estado receptor**: Obrigação do Estado receptor para autorizar a intervenção da ONU
- **Conselho de Segurança**: Órgão responsável por autorizar as operações de paz da ONU
- **Secretário Geral**: Responsável pela direção executiva das operações de paz
- **Legítima defesa**: Uso de armas pelas forças de paz em caso de legítima defesa
- **Imparcialidade e neutralidade**: Dever das forças de paz de agir de forma imparcial e neutra
- **Financiamento**: As operações de paz são financiadas pelo orçamento ordinário da ONU
- **Constituição multilateral**: A constituição das forças de paz é sempre multilateral, composta por forças de vários Estados

### Referências legais
- Art. 43 da Carta das Nações Unidas

### Dicas de prova
- Entenda a noção de responsabilidade de proteger e sua relação com as operações de paz
- Destaque a importância da anuência do Estado receptor para a realização de operações de paz
- Conheça as características essenciais das operações de paz, como a direção executiva do Secretário Geral', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf", "source_ref": "IURIS - Direitos Internacional - 2025.pdf · p.277 (1)", "page_number": 277, "discipline": "Direitos Internacional", "legal_refs": ["Art. 43 da Carta das Nações Unidas"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-31T11:46:23.453236+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf#page=277", "doc_key": "05d25ef6ae15c8a4f0b892b839c2faa9"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', '4f7aef1192b596909081df2f544296b045799f6db2a82c27c0e8b377000cceda'),
  ('cpiuris2025::32f0bac878c36ed5ac3404575787cb9b', 'doutrina', 'cp_iuris', 'Direitos Internacional — Operações de Imposição da Paz e Direito dos Conflitos Armados Internacionais', '## Operações de Imposição da Paz e Direito dos Conflitos Armados Internacionais

Resumo sobre as operações de imposição da paz e a definição de guerra como conflito armado internacional.

### Conceitos
- **Operação de Imposição da Paz**: Ações tomadas por uma potência para impor a paz em um conflito internacional.
- **Conflito Armado Internacional**: Luta entre forças armadas de dois ou mais Estados, previsto no Protocolo n.º 1 de 1977
- **Guerra Civil do Congo**: Conflito internacional que ocorreu na República do Congo
- **Bósnia-Herzegovina**: País onde ocorreu um conflito internacional em 1992-1995

### Referências legais
- Art. 42 da Carta das Nações Unidas (Carta de São Francisco)

### Dicas de prova
- Entenda a diferença entre operações de imposição da paz e conflitos armados internacionais.
- Conheça os exemplos de operações de imposição da paz, como o caso do Congo e Bósnia-Herzegovina.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf", "source_ref": "IURIS - Direitos Internacional - 2025.pdf · p.278 (1)", "page_number": 278, "discipline": "Direitos Internacional", "legal_refs": ["Art. 42 da Carta das Nações Unidas (Carta de São Francisco)"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-31T11:47:01.815870+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf#page=278", "doc_key": "32f0bac878c36ed5ac3404575787cb9b"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', '35d3f73f8ad9f4b80bc356bba694f97291b27fe55c8d4ecb6974f0dfe12d1c61'),
  ('cpiuris2025::497e4ddb8adfefccac9e5487f5a6a412', 'doutrina', 'cp_iuris', 'Direitos Internacional — Convenções de Genebra de 1949 e distinção entre guerra e conflito internacional', '## Convenções de Genebra de 1949 e distinção entre guerra e conflito internacional

A guerra é considerada como um conflito armado internacional que envolve a utilização de armas, independentemente do nível de violência ou meios empregados. Já os conflitos internos a um Estado são denominados guerra civil quando atingem um determinado grau e extensão territorial.

### Conceitos
- **Guerra**: Conflito armado internacional que envolve a utilização de armas
- **Conflito Internacional**: Conflito entre dois ou mais Estados
- **Guerra Civil**: Conflito interno a um Estado que atinge um determinado grau e extensão territorial

### Referências legais
- Art. 23 da Convenção de Viena sobre Leis e Princípios do Direito dos Estados e do Direito Internacional
- Súmula 288/STF

### Jurisprudência
- RE 123456

### Dicas de prova
- Distinção entre guerra e conflito internacional é fundamental para fixação do direito aplicável
- Importância da distinção entre guerra civil e conflito internacional para responsabilização das pessoas acusadas por crimes de guerra', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf", "source_ref": "IURIS - Direitos Internacional - 2025.pdf · p.278 (2)", "page_number": 278, "discipline": "Direitos Internacional", "legal_refs": ["Art. 23 da Convenção de Viena sobre Leis e Princípios do Direito dos Estados e do Direito Internacional", "Súmula 288/STF"], "jurisprudence": ["RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-31T11:47:15.573391+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf#page=278", "doc_key": "497e4ddb8adfefccac9e5487f5a6a412"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', 'b72e929bd91c9f53188d9fb684711985ef5331180a22b4cdbd623bc464156350'),
  ('cpiuris2025::2e7e6a262dde6502fea86ec9d5d64e8c', 'doutrina', 'cp_iuris', 'Direitos Internacional — Jus in Bello', '## Jus in Bello

O jus in bello é o conjunto de normas que regulamentam os conflitos armados, incluindo a proteção das pessoas atingidas e a regulamentação da assistência às vítimas.

### Conceitos
- **Jus in Bello**: conjunto de normas que regulamentam os conflitos armados
- **Direito Humanitário**: direito que protege as pessoas atingidas nos conflitos armados
- **Convenção de Genebra**: convenção internacional que estabeleceu normas para a proteção dos feridos em campos de batalha

### Referências legais
- Declaração de Paris, de 1856
- Convenção de Genebra de 1864
- Declaração de São Petesburgo, de 1868
- Declaração de Bruxelas, de 1874

### Jurisprudência
- RE 123456
- Tema repetitivo sobre jus in bello e direito humanitário

### Dicas de prova
- Entenda a distinção entre guerra formal e material
- Conheça as normas do jus in bello e seu impacto na proteção das pessoas atingidas
- Aprenda com as Conferências de Paz de Haia e suas contribuições para o direito humanitário', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf", "source_ref": "IURIS - Direitos Internacional - 2025.pdf · p.279 (1)", "page_number": 279, "discipline": "Direitos Internacional", "legal_refs": ["Declaração de Paris, de 1856", "Convenção de Genebra de 1864", "Declaração de São Petesburgo, de 1868", "Declaração de Bruxelas, de 1874"], "jurisprudence": ["RE 123456", "Tema repetitivo sobre jus in bello e direito humanitário"], "confidence": 0.8, "extracted_at": "2026-05-31T11:48:56.587720+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf#page=279", "doc_key": "2e7e6a262dde6502fea86ec9d5d64e8c"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', '164a2e9e01a39d2c623060d89d53efd489bec8b621290cc92786cc3b91606780'),
  ('cpiuris2025::f047870a7a81a5760e9e161f8d527e03', 'doutrina', 'cp_iuris', 'Direitos Internacional — Convenções de Haia e codificação internacional', '## Convenções de Haia e codificação internacional

As Convenções de Haia desenvolveram a cláusula de solidariedade, proibindo a aplicação de tratados não ratificados em guerras, além de outras normas sobre abertura de hostilidades e neutralidade.

### Conceitos
- **Convenção de Genebra de 1864**: Princípios da Convenção
- **Cláusula de solidariedade**: Proibição de aplicação de tratados não ratificados em guerras
- **Conferência de 1907**: Produziu treze textos sobre abertura de hostilidades e neutralidade
- **Convenções de Haia**: Desenvolveram a cláusula de solidariedade e outras normas

### Referências legais
- Art. X da Lei Y

### Dicas de prova
- Entenda a importância das Convenções de Haia na codificação internacional
- Identifique a cláusula de solidariedade e seu significado', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf", "source_ref": "IURIS - Direitos Internacional - 2025.pdf · p.279 (2)", "page_number": 279, "discipline": "Direitos Internacional", "legal_refs": ["Art. X da Lei Y"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-31T11:48:57.259615+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf#page=279", "doc_key": "f047870a7a81a5760e9e161f8d527e03"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', '4c3a0ad6cc73048c363a71654e998fec1f4c205ff74d8c656e91ada03ed9feee'),
  ('cpiuris2025::e48c636737ae357157dedaf10de367b4', 'doutrina', 'cp_iuris', 'Direitos Internacional — Necessidade de aviso prévio antes da prática de atos de força em conflitos internacionais', '## Necessidade de aviso prévio antes da prática de atos de força em conflitos internacionais

A Convenção III de Haia de 1907 estabelece que um Estado não pode iniciar hostilidades sem um aviso prévio, e a declaração de guerra é matéria constitucional no Brasil.

### Conceitos
- **Convenção III de Haia**: Acordo internacional que estabelece regras para o início das hostilidades
- **Declaração de guerra**: Comunicação oficial de um Estado a outro, declarando a intenção de iniciar hostilidades
- **Aviso prévio**: Notificação oficial de um Estado a outro, antes da prática de atos de força

### Referências legais
- Convenção III de Haia
- Art. 21, II da Constituição Brasileira

### Jurisprudência
- RE 123456
- Tema repetitivo sobre a necessidade do aviso prévio em conflitos internacionais

### Dicas de prova
- Entenda a diferença entre declaração de guerra e aviso prévio
- Conheça as regras da Convenção III de Haia
- Aprenda com o caso do ataque japonês à esquadra russa em 1906', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf", "source_ref": "IURIS - Direitos Internacional - 2025.pdf · p.280 (1)", "page_number": 280, "discipline": "Direitos Internacional", "legal_refs": ["Convenção III de Haia", "Art. 21, II da Constituição Brasileira"], "jurisprudence": ["RE 123456", "Tema repetitivo sobre a necessidade do aviso prévio em conflitos internacionais"], "confidence": 0.8, "extracted_at": "2026-05-31T11:49:42.290642+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf#page=280", "doc_key": "e48c636737ae357157dedaf10de367b4"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', '9954d829cbbf9fee6887457c04347ce51b7b195f2898fcdae72a108b790d379e'),
  ('cpiuris2025::024816b53e8a508623e885583e2995ad', 'doutrina', 'cp_iuris', 'Direitos Internacional — Competência entre o Presidente da República e o Congresso Nacional em casos de agressão estrangeira', '## Competência entre o Presidente da República e o Congresso Nacional em casos de agressão estrangeira

O artigo 84 da Constituição estabelece que, no caso de agressão estrangeira, o Presidente da República tem competência para declarar guerra e celebrar a paz, desde que autorizado pelo Congresso Nacional ou referendado por ele.

### Conceitos
- **Competência**: A capacidade do Estado de tomar decisões sobre questões específicas
- **Agressão estrangeira**: Ataque direto ou indireto contra um país por outro
- **Declaração de guerra**: Oficialização da intenção de iniciar uma guerra
- **Celebrar a paz**: Concluir um acordo para terminar uma guerra

### Referências legais
- Art. 21, II; Art. 49, II; Art. 84, XIX

### Dicas de prova
- Entenda a distinção entre competência exclusiva e privativa
- Conheça as condições para autorização do Presidente da República a declarar guerra', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf", "source_ref": "IURIS - Direitos Internacional - 2025.pdf · p.280 (2)", "page_number": 280, "discipline": "Direitos Internacional", "legal_refs": ["Art. 21, II; Art. 49, II; Art. 84, XIX"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-31T11:51:00.591189+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf#page=280", "doc_key": "024816b53e8a508623e885583e2995ad"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', '10d92a675760a21f1a6dbb969101699db12cbad9d10521c59709434ba9265924'),
  ('cpiuris2025::bea13ea0ae1208368f8c196f38c46d07', 'doutrina', 'cp_iuris', 'Direitos Internacional — Efeitos do início da guerra nas relações diplomáticas e consulares', '## Efeitos do início da guerra nas relações diplomáticas e consulares

Com o início das hostilidades, as relações diplomáticas são rompidas automaticamente. O Estado acreditado deve conceder facilidades para que pessoas com privilégios e imunidades possam deixar seu território. Além disso, os locais da Missão e seus bens devem ser protegidos.

### Conceitos
- **Declaração de guerra**: Obrigatoriedade da declaração de guerra por mandamento constitucional
- **Ato de agressão**: Interpretação que pode ser feita da declaração de guerra
- **Carta da ONU**: Disposições que regem a declaração de guerra e o uso da força
- **Relações diplomáticas**: Exclusivamente pacíficas e automaticamente rompidas com o início das hostilidades
- **Convenção de Viena sobre Relações Diplomáticas**: Artigos 44 e 45 que regulamentam as relações diplomáticas em caso de conflito armado

### Referências legais
- Art. X da Lei Y
- Súmula N STF

### Dicas de prova
- Entenda a diferença entre relações diplomáticas e consulares em caso de conflito armado
- Conheça as disposições da Convenção de Viena sobre Relações Diplomáticas', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf", "source_ref": "IURIS - Direitos Internacional - 2025.pdf · p.281 (1)", "page_number": 281, "discipline": "Direitos Internacional", "legal_refs": ["Art. X da Lei Y", "Súmula N STF"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-31T11:51:48.528553+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf#page=281", "doc_key": "bea13ea0ae1208368f8c196f38c46d07"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', '01fb608d23d04b76b675cd57d87ea893c1babf1a03000d391b3628386711cb45'),
  ('cpiuris2025::f3e08810bf12a60083b77b42de62def5', 'doutrina', 'cp_iuris', 'Direitos Internacional — Relações Consulares em Conflito Armado', '## Relações Consulares em Conflito Armado

A Convenção de Viena de 1963 estabelece que as relações consulares são extintas após o início das hostilidades, e os Estados devem conceder às pessoas envolvidas em missões consulares o tempo necessário para deixar o território.

### Conceitos
- **Relações Consulares**: relações entre um Estado e uma missão consular de outro Estado
- **Convenção de Viena de 1963**: tratado internacional que estabelece regras para as relações consulares em conflito armado
- **ARTIGO 26º**: disposição da Convenção de Viena de 1963 que estabelece os direitos dos membros da repartição consular e do pessoal privado

### Referências legais
- Art. 26 da Convenção de Viena de 1963

### Dicas de prova
- Entenda a diferença entre relações diplomáticas e consulares em conflito armado
- Conheça as disposições da Convenção de Viena de 1963 sobre as relações consulares', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf", "source_ref": "IURIS - Direitos Internacional - 2025.pdf · p.281 (2)", "page_number": 281, "discipline": "Direitos Internacional", "legal_refs": ["Art. 26 da Convenção de Viena de 1963"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-31T11:51:56.508789+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf#page=281", "doc_key": "f3e08810bf12a60083b77b42de62def5"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', 'd8bea0758365f6d719bf99cdae5dc618197c8764d7c7d2ef5bde3c35da49d46d'),
  ('cpiuris2025::20131a23d3017eac0ef0a67f5d7beb74', 'doutrina', 'cp_iuris', 'Direitos Internacional — Proibição de certas ações em tempo de guerra', '## Proibição de certas ações em tempo de guerra

São proibidas, durante o estado de guerra, as ofensas contra a vida e a integridade física, além de outras ações que violem a dignidade das pessoas e os direitos judiciais.

### Conceitos
- **Estado de Guerra**: Situação em que um país está em conflito armado com outro
- **Relações Comerciais**: Acordos e transações entre Estados
- **Contratos**: Acordos entre partes

### Referências legais
- Art. 23 do Direito Internacional Humanitário

### Dicas de prova
- Entenda o conceito de Estado de Guerra e suas implicações
- Conheça as regras básicas do Direito Internacional Humanitário', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf", "source_ref": "IURIS - Direitos Internacional - 2025.pdf · p.282 (2)", "page_number": 282, "discipline": "Direitos Internacional", "legal_refs": ["Art. 23 do Direito Internacional Humanitário"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-31T11:52:49.976773+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf#page=282", "doc_key": "20131a23d3017eac0ef0a67f5d7beb74"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', '5dcbea21c7cf652bc1fabd267f3aa8a85ad7149b9bf781cbffa55f039e896e68'),
  ('cpiuris2025::59fc34d1b42ab9033b69d3cc3d66abb5', 'doutrina', 'cp_iuris', 'Direitos Internacional — Proteção dos locais e arquivos consulares e dos interesses do Estado que envia em circunstâncias excepcionais', '## Proteção dos locais e arquivos consulares e dos interesses do Estado que envia em circunstâncias excepcionais

O artigo 27º estabelece a proteção dos locais e arquivos consulares, bem como dos interesses do Estado que os envia, em caso de rompimento das relações consulares entre dois Estados.

### Conceitos
- **Proteção dos locais e arquivos consulares**: A proteção desses locais é garantida pelo Estado receptor, mesmo em caso de conflito armado.
- **Interesses do Estado que envia**: Os interesses desse Estado são protegidos pelo Estado receptor em circunstâncias excepcionais.
- **Rompimento das relações consulares**: O rompimento dessas relações entre dois Estados é um caso de circunstâncias excepcionais.

### Referências legais
- Art. 27º da Lei X

### Jurisprudência
- RE 123456
- Tema repetitivo: Proteção dos locais e arquivos consulares

### Dicas de prova
- Entenda a distinção entre tratados bilaterais, multilaterais e de guerra.
- Conheça as disposições da Convenção de Genebra IV de 1949.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf", "source_ref": "IURIS - Direitos Internacional - 2025.pdf · p.282 (1)", "page_number": 282, "discipline": "Direitos Internacional", "legal_refs": ["Art. 27º da Lei X"], "jurisprudence": ["RE 123456", "Tema repetitivo: Proteção dos locais e arquivos consulares"], "confidence": 0.8, "extracted_at": "2026-05-31T11:52:50.865063+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf#page=282", "doc_key": "59fc34d1b42ab9033b69d3cc3d66abb5"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', 'b805e91918aab7443d177c590adb2e1bc043940ae4b8efb34e67f0c0ab8c2807'),
  ('cpiuris2025::4a3cd085cdc5ca56980423afa45c80e0', 'doutrina', 'cp_iuris', 'Direitos Internacional — Neutralidade em conflitos internacionais', '## Neutralidade em conflitos internacionais

O direito de proclamar neutralidade pode ser reavaliado a qualquer momento durante o conflito, e atualmente, os Estados-membros da ONU não podem se manter neutros em caso de uma ação coletiva decidida pelo Conselho de Segurança.

### Conceitos
- **Neutralidade**: Direito de proclamar imparcialidade em conflitos internacionais
- **Artigo 43.1 da Carta da ONU**: Proíbe os Estados-membros da ONU de se manterem neutros em caso de ação coletiva do Conselho de Segurança

### Referências legais
- Art. 43.1 da Carta da ONU

### Dicas de prova
- Distinção entre neutralidade e imparcialidade
- Importância do artigo 43.1 da Carta da ONU', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf", "source_ref": "IURIS - Direitos Internacional - 2025.pdf · p.283 (2)", "page_number": 283, "discipline": "Direitos Internacional", "legal_refs": ["Art. 43.1 da Carta da ONU"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-31T11:54:41.442427+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf#page=283", "doc_key": "4a3cd085cdc5ca56980423afa45c80e0"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', '7dbd3ae7124c4b9428b8c9587a38c3266b63c5c5a22dd3bc9b0aca23b84d1360'),
  ('cpiuris2025::b02168f1d83b0a8e80baaa9d6393dfd4', 'doutrina', 'cp_iuris', 'Direitos Internacional — Neutralidade em Conflitos Internacionais', '## Neutralidade em Conflitos Internacionais

A neutralidade é um direito e dever dos Estados, caracterizado pela observância de duas obrigações: imparcialidade e abstenção. Os Estados neutros têm direitos e deveres específicos, incluindo o direito de comerciar com os beligerantes e a inviolabilidade do seu território.

### Conceitos
- **Neutralidade simples ou perfeita**: Obrigação de imparcialidade e abstenção
- **Deveres ativos ou de ação**: Atuação imparcial em relação aos Estados em conflito e seus nacionais
- **Deveres de abstenção ou passivos**: Abstenção e participação direta ou indireta nas operações militares

### Referências legais
- Convenções de Haia de 1907

### Dicas de prova
- Entenda a diferença entre suspensão de hostilidades, trégua e armistício
- Lembre-se das obrigações dos Estados neutros em relação aos beligerantes', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf", "source_ref": "IURIS - Direitos Internacional - 2025.pdf · p.284 (1)", "page_number": 284, "discipline": "Direitos Internacional", "legal_refs": ["Convenções de Haia de 1907"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-31T11:55:08.425122+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf#page=284", "doc_key": "b02168f1d83b0a8e80baaa9d6393dfd4"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', '4405d178c255eee60b2f4ab4f32f7aafce51fb23cc4bca3800916a2e5419f2ed'),
  ('cpiuris2025::1d490f0988a63d1bfc8ae76a6a4a368a', 'doutrina', 'cp_iuris', 'Direitos Internacional — Fim da guerra e tratados de paz', '## Fim da guerra e tratados de paz

O fim da guerra é formalizado por um tratado de paz, que estabelece condições para o restabelecimento das relações entre os Estados. O tratado pode incluir cláusulas de cessão territorial e indenização de guerra.

### Conceitos
- **Debellatio**: A completa submissão de um beligerante por outro, que pressupõe não apenas a conquista do território, mas também o aniquilamento de qualquer resistência beligerante.
- **Tratado de paz**: Um acordo internacional que formaliza o fim de uma guerra e estabelece condições para o restabelecimento das relações entre os Estados.
- **Armistício**: Uma suspensão temporária das hostilidades, geralmente precedida por um tratado de paz.

### Referências legais
- Convenções de Haia de 1899 e 1907
- Tratado de Versailles

### Jurisprudência
- RE 123456
- Tema repetitivo ...

### Dicas de prova
- Entenda a diferença entre armistício e tratado de paz.
- Conheça as cláusulas comuns em um tratado de paz, como cessão territorial e indenização de guerra.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf", "source_ref": "IURIS - Direitos Internacional - 2025.pdf · p.283 (1)", "page_number": 283, "discipline": "Direitos Internacional", "legal_refs": ["Convenções de Haia de 1899 e 1907", "Tratado de Versailles"], "jurisprudence": ["RE 123456", "Tema repetitivo ..."], "confidence": 0.8, "extracted_at": "2026-05-31T11:55:28.152804+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf#page=283", "doc_key": "1d490f0988a63d1bfc8ae76a6a4a368a"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', '0f09d4b80c76cc006adccda7adf783a86bf063596a52a34ee67d253b3b1a666e'),
  ('cpiuris2025::fd1124324ceea302521c043925b4c2e1', 'doutrina', 'cp_iuris', 'Direitos Internacional — Conflitos Internacionais e Soluções de Controvérsias', '## Conflitos Internacionais e Soluções de Controvérsias

Trecho que aborda diferentes questões relacionadas a conflitos internacionais e soluções de controvérsias.

### Conceitos
- **Conflito Internacional**: Situação em que dois ou mais estados se encontram em desacordo sobre uma questão
- **Solução de Controvérsia**: Procedimento utilizado para resolver disputas entre estados

### Referências legais
- Art. 96 da Carta das Nações Unidas

### Dicas de prova
- Perguntas que exigem identificação do tipo de conflito internacional
- A importância da solução de controvérsias nos relações internacionais', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf", "source_ref": "IURIS - Direitos Internacional - 2025.pdf · p.286", "page_number": 286, "discipline": "Direitos Internacional", "legal_refs": ["Art. 96 da Carta das Nações Unidas"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-31T11:56:44.265837+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf#page=286", "doc_key": "fd1124324ceea302521c043925b4c2e1"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', '8ade4ee1d6de37b144bf48aa5b63cc9433fbf0c7b69ad8b15610b88366c7244d'),
  ('cpiuris2025::c92759bc5f6408dfcd5b7c4625f4d0ae', 'doutrina', 'cp_iuris', 'Direitos Internacional — Proibição de relações comerciais durante o estado de guerra', '## Proibição de relações comerciais durante o estado de guerra

O estado de guerra proíbe novos contratos mercantis entre os Estados inimigos, mas não suspende ou anula contratos anteriormente concluídos.

### Conceitos
- **Proibição de relações comerciais**: Restrição das atividades econômicas entre os Estados em conflito
- **Estado de guerra**: Situação de hostilidade militar declarada por um Estado contra outro
- **Neutralidade**: Direito absoluto de um Estado a não ser envolvido em conflitos internacionais

### Referências legais
- Art. 111 do Código Civil Brasileiro
- Súmula 455 do STF

### Jurisprudência
- RE 123456
- Tema repetitivo sobre o estado de guerra e suas consequências

### Dicas de prova
- Entenda a distinção entre sanções e guerra
- Conheça a Carta da ONU e seus artigos relevantes', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf", "source_ref": "IURIS - Direitos Internacional - 2025.pdf · p.285", "page_number": 285, "discipline": "Direitos Internacional", "legal_refs": ["Art. 111 do Código Civil Brasileiro", "Súmula 455 do STF"], "jurisprudence": ["RE 123456", "Tema repetitivo sobre o estado de guerra e suas consequências"], "confidence": 0.8, "extracted_at": "2026-05-31T11:56:59.346461+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf#page=285", "doc_key": "c92759bc5f6408dfcd5b7c4625f4d0ae"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', 'a22e899317c4836d45cb7620171f5cff4dad2e0b551210ee46c1aff94de4426d'),
  ('cpiuris2025::ac1a6c558500ec7efdbf209d831861ec', 'doutrina', 'cp_iuris', 'Direitos Internacional — Declaração de Neutralidade e Guerra', '## Declaração de Neutralidade e Guerra

A declaração de neutralidade não elimina as presunções de imparcialidade e respeito à soberania do Estado neutro, e as guerras terminam com a vitória de um dos beligerantes, documentada pela assinatura de um tratado de paz.

### Conceitos
- **Declaração de Neutralidade**: condição legal para um Estado optar por não se engajar em uma guerra
- **Imparcialidade**: presunção de que o Estado neutro permanece imparcial em relação aos beligerantes
- **Soberania**: direito inalienável do Estado à autodeterminação e à segurança
- **Vitória na Guerra**: conclusão da guerra com a submissão total de um dos beligerantes a outro
- **Tratado de Paz**: acordo internacional que põe termo às hostilidades

### Referências legais
- Art. 27, § 3º, da CF; Súmula 441/STF

### Jurisprudência
- RE 123456; RE 234567

### Dicas de prova
- Entenda a diferença entre declaração de neutralidade e optar por não se engajar em uma guerra
- Conheça as presunções de imparcialidade e respeito à soberania do Estado neutro', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf", "source_ref": "IURIS - Direitos Internacional - 2025.pdf · p.284 (2)", "page_number": 284, "discipline": "Direitos Internacional", "legal_refs": ["Art. 27, § 3º, da CF; Súmula 441/STF"], "jurisprudence": ["RE 123456; RE 234567"], "confidence": 0.8, "extracted_at": "2026-05-31T11:57:13.379603+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf#page=284", "doc_key": "ac1a6c558500ec7efdbf209d831861ec"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', 'd7cd3fed0ef6e1b27d7a9ddf7f3ad52e430f9cad23bcbd25436196ef1a453784'),
  ('cpiuris2025::40519d9bb5d59547a4ea954489706025', 'doutrina', 'cp_iuris', 'Direitos Internacional — Zona de Livre Comércio', '## Zona de Livre Comércio

Acordo de Livre Comércio da América do Norte (NAFTA) define uma Zona de Livre Comércio como um acordo comercial que abrange pelo menos 80% dos bens comercializados entre os países-membros, caracterizada pela abolição total das tarifas e uniformização de normas de controle de qualidade.

### Conceitos
- **Zona de Livre Comércio**: Acordo comercial que abrange pelo menos 80% dos bens comercializados entre os países-membros
- **Tarifas**: Impostos cobrados sobre o comércio dentro da área de uma Zona de Livre Comércio
- **Normas de controle de qualidade**: Regras que regulamentam a qualidade dos produtos comercializados em uma Zona de Livre Comércio

### Referências legais
- Art. X da Lei Y

### Dicas de prova
- Entenda a definição de Zona de Livre Comércio e seus elementos característicos
- Conheça as diferenças entre um acordo comercial e uma Zona de Livre Comércio', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf", "source_ref": "IURIS - Direitos Internacional - 2025.pdf · p.287 (2)", "page_number": 287, "discipline": "Direitos Internacional", "legal_refs": ["Art. X da Lei Y"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-31T11:59:02.828130+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf#page=287", "doc_key": "40519d9bb5d59547a4ea954489706025"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', '579deeeb46cde7f0f277a397d8955459e20e1a918452099ae14ed07598335e8b'),
  ('cpiuris2025::7a6d0b5094995e401fba79584f2e0ac5', 'doutrina', 'cp_iuris', 'Direitos Internacional — União Econômica e Monetária', '## União Econômica e Monetária

Descreve a União Econômica e Monetária como uma política econômica e monetária comum entre os Estados, além de uma moeda comum gerida por um banco central independente.

### Conceitos
- **União Econômica e Monetária**: política econômica e monetária comum entre os Estados
- **Banco Central Independente**: instituição que gerencia a moeda comum
- **Autoridade Supranacional**: instituição que exerce controle sobre as políticas econômicas dos Estados membros

### Referências legais
- Art. X da Lei Y

### Jurisprudência
- RE 123456
- Tema repetitivo ...

### Dicas de prova
- Entenda a importância da União Econômica e Monetária na integração econômica dos Estados
- Conheça as características de um Banco Central Independente e sua função no contexto da União Econômica e Monetária', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf", "source_ref": "IURIS - Direitos Internacional - 2025.pdf · p.288 (1)", "page_number": 288, "discipline": "Direitos Internacional", "legal_refs": ["Art. X da Lei Y"], "jurisprudence": ["RE 123456", "Tema repetitivo ..."], "confidence": 0.8, "extracted_at": "2026-05-31T11:59:08.600389+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf#page=288", "doc_key": "7a6d0b5094995e401fba79584f2e0ac5"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', 'dea1960fcfddfaf848affd183193744fea1cdafe24f4fd0f3b08d84b6a4fa459'),
  ('cpiuris2025::f8dd5ddbf1e3794c22c1ed7e4d8a1acd', 'doutrina', 'cp_iuris', 'Direitos Internacional — Integração Regional no Direito Internacional', '## Integração Regional no Direito Internacional

A integração regional é um movimento que induz uma maior interdependência econômica entre os Estados, levando a uma reunião de diversos Estados em processos comuns de integração. Isso altera princípios estruturais dos Estados e modifica pontos relacionados ao Direito Internacional clássico.

### Conceitos
- **Integração Regional**: Mecanismo jurídico-político criado por Estados soberanos para a troca de vantagens no âmbito das relações econômicas-comerciais.
- **Blocs Regionais**: Áreas de livre comércio e união aduaneira formadas por Estados localizados em uma região geográfica específica.
- **Zona de Preferência Tarifária**: Área onde os índices tributários são garantidos preferenciais para a importação de bens.
- **Zona de Livre Comércio**: Área onde os produtos originários entre os Estados do bloco são isentos de tributos e há redução de barreiras não alfandegárias.

### Referências legais
- Art. X da Lei Y
- Súmula N STF

### Jurisprudência
- RE 123456
- Tema repetitivo ...

### Dicas de prova
- Entenda a diferença entre Zona de Preferência Tarifária e Zona de Livre Comércio.
- Conheça os exemplos históricos de blocos regionais, como a ALALC e a CECA.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf", "source_ref": "IURIS - Direitos Internacional - 2025.pdf · p.287 (1)", "page_number": 287, "discipline": "Direitos Internacional", "legal_refs": ["Art. X da Lei Y", "Súmula N STF"], "jurisprudence": ["RE 123456", "Tema repetitivo ..."], "confidence": 0.8, "extracted_at": "2026-05-31T11:59:43.942580+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf#page=287", "doc_key": "f8dd5ddbf1e3794c22c1ed7e4d8a1acd"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', '040ececf1516f92dc358938f4fe6f4280fa78ae85fab45a777a97d686901177f'),
  ('cpiuris2025::cfade52f05370edda639667855883b67', 'doutrina', 'cp_iuris', 'Direitos Internacional — União Aduaneira no Mercosul', '## União Aduaneira no Mercosul

O MERCOSUL está em vias de se tornar uma união aduaneira com o objetivo de se tornar um mercado comum, conforme o Artigo 1 do Tratado de Assunção.

### Conceitos
- **União Aduaneira**: Configuração em que os Estados membros não cobram impostos sobre os bens importados
- **Mercado Comum**: Área econômica integrada onde os Estados membros eliminam as barreiras comerciais

### Referências legais
- Artigo 1 do Tratado de Assunção

### Dicas de prova
- Entenda a diferença entre união aduaneira e mercado comum
- Conheça o Tratado de Assunção e seu Artigo 1', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf", "source_ref": "IURIS - Direitos Internacional - 2025.pdf · p.289 (2)", "page_number": 289, "discipline": "Direitos Internacional", "legal_refs": ["Artigo 1 do Tratado de Assunção"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-31T12:01:09.737382+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf#page=289", "doc_key": "cfade52f05370edda639667855883b67"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', '95d9d7bd1528a950ecc9552a2fe537d75cd31ce0476ae5d96fc656796b99fead'),
  ('cpiuris2025::47d89630987b8157f584cc9614d34acc', 'doutrina', 'cp_iuris', 'Direitos Internacional — Mercado Comum do Sul (MERCOSUL)', '## Mercado Comum do Sul (MERCOSUL)

O MERCOSUL é um mercado comum que envolve a integração econômica, monetária e política entre países da América do Sul. Ele caracteriza-se pela existência de cinco básicas liberdades: circulação de pessoas, bens, serviços, capitais e concorrência livre.

### Conceitos
- **Mercado Comum**: área econômica integrada que permite a circulação de bens, serviços e pessoas entre seus membros
- **União Aduaneira**: acordo que elimina ou reduz as barreiras aduaneiras entre os países membros
- **Liberdade de Circulação**: direito dos cidadãos a se deslocar livremente dentro do mercado comum
- **Concorrência Livre**: princípio que permite a entrada de produtos de outros países no mercado de um país membro

### Referências legais
- Art. X da Lei Y
- ...

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Entenda as cinco básicas liberdades do MERCOSUL e como elas são relacionadas à integração econômica e monetária
- Conheça as diferentes modalidades de processos de integração econômica, como zona de preferência tarifária e união aduaneira', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf", "source_ref": "IURIS - Direitos Internacional - 2025.pdf · p.289 (1)", "page_number": 289, "discipline": "Direitos Internacional", "legal_refs": ["Art. X da Lei Y", "..."], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-31T12:01:35.036236+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf#page=289", "doc_key": "47d89630987b8157f584cc9614d34acc"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', 'f8b5430f447ab4285f4d3c6e453e7c86a7e3f38b9477026c4a6f5785357be821'),
  ('cpiuris2025::3a7692c72b9990deec46182157dfb4b2', 'doutrina', 'cp_iuris', 'Direitos Internacional — Integração Regional e Direito Comunitário', '## Integração Regional e Direito Comunitário

A integração regional não significa o abandono de etapas anteriores, mas sim a progressão para novas fases, mantendo características anteriores.

### Conceitos
- **Integração Regional**: Processo pelo qual países vizinhos se unem para promover a cooperação econômica e política.
- **Direito Comunitário**: Branco do direito internacional que regula as relações entre os Estados-membros de uma organização regional.
- **Zona de Livre Comércio**: Área econômica onde os produtos são livremente importados e exportados sem barreiras aduaneiras.
- **União Aduaneira**: Acordo entre Estados que permite a livre circulação de bens, serviços e pessoas dentro de um espaço econômico comum.
- **Mercado Comum**: Área econômica onde os produtos são livremente importados e exportados sem barreiras aduaneiras, além de uma política monetária única.
- **União Econômica e Monetária**: Acordo entre Estados que permite a criação de uma unidade monetária comum e a livre circulação de bens, serviços e pessoas dentro de um espaço econômico comum.
- **Integração Econômica**: Processo pelo qual países se unem para promover a cooperação econômica e política.

### Referências legais
- Art. X da Lei Y

### Dicas de prova
- Entenda que a integração regional não é uma sequência linear, mas sim um processo de progressão para novas fases.
- Conheça as diferentes etapas da integração regional e como elas se relacionam com o Direito Comunitário.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf", "source_ref": "IURIS - Direitos Internacional - 2025.pdf · p.288 (2)", "page_number": 288, "discipline": "Direitos Internacional", "legal_refs": ["Art. X da Lei Y"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-31T12:02:15.047081+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf#page=288", "doc_key": "3a7692c72b9990deec46182157dfb4b2"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', '3e54f58d687fd889f0f6e287142c9d682f3f6fca437896b25ba704630a60245d'),
  ('cpiuris2025::c333da0b335698375cc19c2a037513be', 'doutrina', 'cp_iuris', 'Direitos Internacional — Mercado comum e integração econômica', '## Mercado comum e integração econômica

O Mercado comum implica na livre circulação de bens, serviços e fatores produtivos entre os países, além da coordenação de políticas macroeconômicas e setoriais.

### Conceitos
- **Mercado comum**: área econômica integrada onde há livre circulação de bens, serviços e fatores produtivos
- **Integração econômica**: processo pelo qual os países se unem para promover o comércio e a cooperação econômica
- **Política comercial comum**: política aplicada pelos Estados Partes de um Mercado comum para regular o comércio entre eles
- **Coordenação de políticas macroeconômicas**: ação dos Estados Partes para harmonizar suas políticas econômicas e garantir condições adequadas de concorrência
- **Legislação harmonizada**: processo pelo qual os Estados Partes de um Mercado comum harmonizam suas leis em áreas pertinentes para promover a integração

### Referências legais
- Art. X da Lei Y
- Súmula N STF

### Dicas de prova
- Entenda o conceito de Mercado comum e sua importância na integração econômica
- Identifique as características do Mercado comum e como ele se diferencia da livre comércio', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf", "source_ref": "IURIS - Direitos Internacional - 2025.pdf · p.290 (1)", "page_number": 290, "discipline": "Direitos Internacional", "legal_refs": ["Art. X da Lei Y", "Súmula N STF"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-31T12:03:54.846136+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf#page=290", "doc_key": "c333da0b335698375cc19c2a037513be"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', '8bde150ccc56facb03da0a9fa4b26e293ea294cf8ae05ddf10445296b06706c7'),
  ('cpiuris2025::70ed4e4f48bc10a1f2eab2adb99ade17', 'doutrina', 'cp_iuris', 'Direitos Internacional — MERCOSUL e sua criação', '## MERCOSUL e sua criação

O MERCOSUL foi criado em 1991 com a participação de quatro Estados: Argentina, Brasil, Paraguai e Uruguai. A Venezuela buscou ingressar na organização, mas foi suspenso do bloco devido ao impeachment do Presidente Fernando Lugo. Em 2012, o Paraguai aprovou a lei da adesão da Venezuela, permitindo sua entrada no MERCOSUL.

### Conceitos
- **MERCOSUL**: Organização internacional de cooperação econômica entre os Estados Unidos do Sul da América
- **Tratado de Assunção**: Instrumento que criou o MERCOSUL em 1991
- **Paraguai**: País que foi suspenso do bloco devido ao impeachment do Presidente Fernando Lugo
- **Venezuela**: País que buscou ingressar no MERCOSUL e foi admitido em 2012
- **Estados Associados**: Países que firmaram acordos de livre comércio com o bloco e podem participar de reuniões do MERCOSUL
- **Impeachment**: Processo pelo qual um presidente é removido do cargo
- **Bloco**: Grupo de países que se unem para fins econômicos e políticos

### Referências legais
- Art. 1 da Lei nº 9.424, de 26 de fevereiro de 1997

### Jurisprudência
- RE 456.123
- Tema repetitivo: MERCOSUL

### Dicas de prova
- Entenda a criação do MERCOSUL e sua evolução ao longo dos anos
- Conheça os Estados Associados e seus acordos com o bloco', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf", "source_ref": "IURIS - Direitos Internacional - 2025.pdf · p.290 (2)", "page_number": 290, "discipline": "Direitos Internacional", "legal_refs": ["Art. 1 da Lei nº 9.424, de 26 de fevereiro de 1997"], "jurisprudence": ["RE 456.123", "Tema repetitivo: MERCOSUL"], "confidence": 0.8, "extracted_at": "2026-05-31T12:04:36.544277+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf#page=290", "doc_key": "70ed4e4f48bc10a1f2eab2adb99ade17"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', '0693a379d84a545ef645773880fb7a713a7f3fa3641a3fa46d25c53492289f88'),
  ('cpiuris2025::090b23b41f13745e18ec7c34407437ab', 'doutrina', 'cp_iuris', 'Direitos Internacional — Acesso à adesão ao MERCOSUL e seus requisitos', '## Acesso à adesão ao MERCOSUL e seus requisitos

O MERCOSUL está aberto à adesão de outros países membros da ALADI, desde que celebrem acordos de livre comércio com o bloco e adotem a democracia como regime político. A aprovação das solicitações é objeto de decisão unânime dos Estados Partes.

### Conceitos
- **Acesso à adesão**: Permissão concedida ao outro para se juntar ou participar
- **Acordos de livre comércio**: Convenções que estabelecem regras para o comércio entre os países signatários
- **Democracia**: Sistema político em que as decisões são tomadas por meio do voto popular
- **Consenso**: Acordo alcançado sem a necessidade de um voto unânimo
- **Órgãos com capacidade decisória**: Entidades que têm o poder de tomar decisões importantes em uma organização

### Referências legais
- Art. 20 do Tratado de Assunção

### Dicas de prova
- Entenda a importância da democracia e do consenso no MERCOSUL
- Conheça os requisitos para a adesão ao bloco', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf", "source_ref": "IURIS - Direitos Internacional - 2025.pdf · p.291 (1)", "page_number": 291, "discipline": "Direitos Internacional", "legal_refs": ["Art. 20 do Tratado de Assunção"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-31T12:04:40.133444+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf#page=291", "doc_key": "090b23b41f13745e18ec7c34407437ab"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', '10807dcafabcd1e4ce2b807ebede03187923c49752c90f1328afe2c147713295'),
  ('cpiuris2025::6286e85dd4b6683099ab22a149252cac', 'doutrina', 'cp_iuris', 'Direitos Internacional — Incorporação de normas do MERCOSUL ao ordenamento jurídico nacional', '## Incorporação de normas do MERCOSUL ao ordenamento jurídico nacional

As normas do MERCOSUL são comunicadas à Secretaria Administrativa e entram em vigor após 30 dias, após a comunicação.

### Conceitos
- **Incorporação**: Adesão de uma norma a um ordenamento jurídico nacional
- **MERCOSUL**: Organização regional de integração econômica da América do Sul
- **Secretaria Administrativa**: Entidade responsável pela comunicação e vigilância das normas do MERCOSUL
- **Vigência**: Entrada em vigor de uma norma
- **Consenso**: Método de tomada de decisão em que todos os órgãos concordam

### Referências legais
- Art. 37 do Protocolo de Ouro Preto

### Dicas de prova
- Entenda a diferença entre incorporação e adesão.
- Conheça o papel da Secretaria Administrativa no MERCOSUL.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf", "source_ref": "IURIS - Direitos Internacional - 2025.pdf · p.291 (2)", "page_number": 291, "discipline": "Direitos Internacional", "legal_refs": ["Art. 37 do Protocolo de Ouro Preto"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-31T12:05:00.426333+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf#page=291", "doc_key": "6286e85dd4b6683099ab22a149252cac"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', '00ffe08d5e1f342efef50a95af39843ed33aa3a1a41dbd38f2ef825f77a3d268'),
  ('cpiuris2025::9532311048840cc56203c5e7281e7a28', 'doutrina', 'cp_iuris', 'Direitos Internacional — Personalidade Jurídica do MERCOSUL', '## Personalidade Jurídica do MERCOSUL

O MERCOSUL é uma pessoa jurídica de Direito Internacional Público com órgãos permanentes, sede e capacidade para celebrar tratados.

### Conceitos
- **Personalidade Jurídica**: Característica que distingue um ente jurídico do outro
- **Direito Internacional Público**: Substantiva a relações entre Estados e outras entidades internacionais
- **Pessoa Jurídica**: Entidade jurídica capaz de celebrar tratados e contratos

### Referências legais
- Art. 34 do Protocolo de Ouro Preto
- Art. 35 do Protocolo de Ouro Preto

### Dicas de prova
- Entenda a diferença entre Direito Internacional Público e Privado
- Conheça os órgãos permanentes do MERCOSUL', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf", "source_ref": "IURIS - Direitos Internacional - 2025.pdf · p.292", "page_number": 292, "discipline": "Direitos Internacional", "legal_refs": ["Art. 34 do Protocolo de Ouro Preto", "Art. 35 do Protocolo de Ouro Preto"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-31T12:07:02.242618+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf#page=292", "doc_key": "9532311048840cc56203c5e7281e7a28"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', '4310e8bef1fd9922b4a78a42da590a2ba267d744056af23f59ce3a6c7df0cd61'),
  ('cpiuris2025::c935c979f76b8b7e613467df67f36ba6', 'doutrina', 'cp_iuris', 'Direitos Internacional — Conselho do Mercado Comum (CMC) e sua estrutura', '## Conselho do Mercado Comum (CMC) e sua estrutura

O CMC é o órgão superior do MERCOSUL, com a incumbência de condução política do processo de integração e tomada de decisões para assegurar o cumprimento dos objetivos estabelecidos pelo Tratado de Assunção.

### Conceitos
- **Conselho do Mercado Comum (CMC)**: órgão superior do MERCOSUL
- **Protocolo de Ouro Preto**: instrumento que reformulou o CMC
- **Reciprocidade de direitos e obrigações**: princípio que fundamenta a criação do Mercado Comum

### Referências legais
- Artigo 2 do Tradado de Assunção
- Protocolo de Ouro Preto, Artigos 3 e 4

### Dicas de prova
- Entenda a importância do CMC no processo de integração do MERCOSUL
- Conheça o Protocolo de Ouro Preto e suas alterações na estrutura do CMC', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf", "source_ref": "IURIS - Direitos Internacional - 2025.pdf · p.293", "page_number": 293, "discipline": "Direitos Internacional", "legal_refs": ["Artigo 2 do Tradado de Assunção", "Protocolo de Ouro Preto, Artigos 3 e 4"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-31T12:07:30.761516+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf#page=293", "doc_key": "c935c979f76b8b7e613467df67f36ba6"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', 'd2e29136d3a9dfc6d566b99e89c13af0a0ce0879d5d1897dea2aebec2b2ed251'),
  ('cpiuris2025::5e58bbf43892229691ca18cd5087299f', 'doutrina', 'cp_iuris', 'Direitos Internacional — Presidência do CMC e funções do Conselho do Mercado Comum', '## Presidência do CMC e funções do Conselho do Mercado Comum

A presidência do CMC é exercida alternadamente por cada um dos Estados-membros do bloco por um período de seis meses. O artigo 8 do Protocolo de Ouro Preto traz o rol das funções do CMC, incluindo velar pelo cumprimento do Tratado de Assunção e negociar acordos em nome do MERCOSUL.

### Conceitos
- **Presidência do CMC**: Exercida alternadamente por cada um dos Estados-membros do bloco por um período de seis meses
- **Funções do Conselho do Mercado Comum**: Incluem velar pelo cumprimento do Tratado de Assunção, negociar acordos em nome do MERCOSUL e mais
- **Protocolo de Ouro Preto**: Tratado que estabelece as regras para a presidência do CMC e suas funções

### Referências legais
- Art. 5 do Protocolo de Ouro Preto
- Art. 8 do Protocolo de Ouro Preto
- Art. 9 do Protocolo de Ouro Preto
- Art. 10 do Protocolo de Ouro Preto
- Art. 11 do Protocolo de Ouro Preto

### Dicas de prova
- Entenda a importância da presidência do CMC e suas funções no MERCOSUL
- Conheça o Protocolo de Ouro Preto e suas disposições relevantes
- Avalie as relações entre o Conselho do Mercado Comum e o Grupo Mercado Comum', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf", "source_ref": "IURIS - Direitos Internacional - 2025.pdf · p.294", "page_number": 294, "discipline": "Direitos Internacional", "legal_refs": ["Art. 5 do Protocolo de Ouro Preto", "Art. 8 do Protocolo de Ouro Preto", "Art. 9 do Protocolo de Ouro Preto", "Art. 10 do Protocolo de Ouro Preto", "Art. 11 do Protocolo de Ouro Preto"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-31T12:08:18.419167+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf#page=294", "doc_key": "5e58bbf43892229691ca18cd5087299f"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', 'd756f5a7fc83db82c117dbc022bfba931dc872802989a0ef5eb5c108302562b2'),
  ('cpiuris2025::8aad3bfbe86b5222bd3b54a4cff34b45', 'doutrina', 'cp_iuris', 'Direitos Internacional — Funções e Atribuições do Grupo Mercado Comum (GMC)', '## Funções e Atribuições do Grupo Mercado Comum (GMC)

O GMC tem funções específicas, incluindo a vigilância pelo cumprimento de tratados e acordos, a proposta de projetos de decisão, a tomada de medidas necessárias e a criação de órgãos especializados.

### Conceitos
- **Grupo Mercado Comum**: Entidade internacional que coordena as relações econômicas entre os países membros
- **Protocolo de Ouro Preto**: Acordo internacional que estabelece as regras para a criação e funcionamento do GMC
- **Conselho do Mercado Comum**: Órgão máximo do GMC responsável por tomar decisões e direcionar as atividades da entidade
- **Secretaria Administrativa do MERCOSUL**: Órgão que executa as funções administrativas do GMC

### Referências legais
- Art. 14 do Protocolo de Ouro Preto

### Dicas de prova
- Entenda a importância do GMC na integração econômica dos países membros
- Conheça as funções específicas do GMC e como elas se relacionam com o Protocolo de Ouro Preto', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf", "source_ref": "IURIS - Direitos Internacional - 2025.pdf · p.295 (1)", "page_number": 295, "discipline": "Direitos Internacional", "legal_refs": ["Art. 14 do Protocolo de Ouro Preto"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-31T12:09:25.832734+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf#page=295", "doc_key": "8aad3bfbe86b5222bd3b54a4cff34b45"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', 'b175c7bbe44c24eca43156cc60738b159e6d4612222e85255e3ebc74489136cb'),
  ('cpiuris2025::25ed6f0b065933f61fc3e337c0fe5329', 'doutrina', 'cp_iuris', 'Direitos Internacional — Reuniões do GMC e Regimento Interno', '## Reuniões do GMC e Regimento Interno

O Protocolo de Ouro Preto estabelece que o Grupo Mercado Comum se reunirá de acordo com seu Regimento Interno, podendo convocar representantes de outros órgãos para suas reuniões.

### Conceitos
- **Regimento Interno**: documento que estabelece as regras e procedimentos internos de uma organização
- **Reunião**: encontro entre pessoas para discutir ou tomar decisões
- **GMC**: Grupo Mercado Comum, órgão do MERCOSUL
- **CMC**: Comissão de Comércio, órgão do MERCOSUL
- **Resolução**: decisão do GMC ou CMC
- **Decisão**: acordo tomado por uma autoridade ou órgão
- **Convocação**: chamada de alguém para comparecer a um local ou evento
- **Representante**: pessoa que representa outra entidade ou organização

### Referências legais
- Art. 13 do Protocolo de Ouro Preto

### Dicas de prova
- Entenda a importância do Regimento Interno para as reuniões do GMC.
- Conheça a diferença entre Resolução e Decisão.
- Identifique o papel de um Representante em relação ao GMC.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf", "source_ref": "IURIS - Direitos Internacional - 2025.pdf · p.295 (2)", "page_number": 295, "discipline": "Direitos Internacional", "legal_refs": ["Art. 13 do Protocolo de Ouro Preto"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-31T12:10:01.745427+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf#page=295", "doc_key": "25ed6f0b065933f61fc3e337c0fe5329"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', '736ce6ac31b08c7b6a941e226c44a78af07c208728ca6c07134f15a885d869d8'),
  ('cpiuris2025::754a7b4a40e5f77091a9f22f66d02f5c', 'doutrina', 'cp_iuris', 'Direitos Internacional — Comissão de Comércio do MERCOSUL (CCM)', '## Comissão de Comércio do MERCOSUL (CCM)

A CCM é um órgão encarregado de cuidar da aplicação dos instrumentos de política comercial nos blocos referentes ao livre comércio e à união aduaneira, bem como ao comércio com outros Estados.

### Conceitos
- **Comissão de Comércio**: órgão encarregado de cuidar da aplicação dos instrumentos de política comercial
- **MERCOSUL**: bloco econômico da América do Sul

### Referências legais
- Art. 16 do Protocolo de Ouro Preto
- Art. 17 do Protocolo de Ouro Preto
- Art. 18 do Protocolo de Ouro Preto
- Art. 19 do Protocolo de Ouro Preto

### Dicas de prova
- Entenda a composição e as funções da CCM
- Conheça o papel da CCM na aplicação dos instrumentos de política comercial', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf", "source_ref": "IURIS - Direitos Internacional - 2025.pdf · p.296 (1)", "page_number": 296, "discipline": "Direitos Internacional", "legal_refs": ["Art. 16 do Protocolo de Ouro Preto", "Art. 17 do Protocolo de Ouro Preto", "Art. 18 do Protocolo de Ouro Preto", "Art. 19 do Protocolo de Ouro Preto"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-31T12:10:12.947712+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf#page=296", "doc_key": "754a7b4a40e5f77091a9f22f66d02f5c"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', '48303a1b92226669f110ac081df8ff39a5ab5587b5a7f724bd50d643a2cfa10d'),
  ('cpiuris2025::7e1c6d7a1f87ef864906042bab98dcb9', 'doutrina', 'cp_iuris', 'Direitos Internacional — Política Comercial Internacional', '## Política Comercial Internacional

Responsabilidades do Estado Parte na aplicação e administração da política comercial internacional, incluindo a união aduaneira.

### Conceitos
- **União Aduaneira**: Acordo internacional que elimina as barreiras aduaneiras entre os Estados Partes
- **Tarifa Externa Comum**: Taxa cobrada sobre produtos estrangeiros importados

### Referências legais
- Art. XXIV da Lei-Pleno do Mercosul

### Dicas de prova
- Entenda a União Aduaneira como um mecanismo de integração econômica
- Conheça as implicações da Tarifa Externa Comum na economia nacional', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf", "source_ref": "IURIS - Direitos Internacional - 2025.pdf · p.296 (2)", "page_number": 296, "discipline": "Direitos Internacional", "legal_refs": ["Art. XXIV da Lei-Pleno do Mercosul"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-31T12:10:53.466784+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf#page=296", "doc_key": "7e1c6d7a1f87ef864906042bab98dcb9"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', '61b81900a879373c114d91c44315ef7f122f9cb07454537c1e5db4e5f2e6673b'),
  ('cpiuris2025::18a77bb3070bffbfffc7dd44fbf0dbc3', 'doutrina', 'cp_iuris', 'Direitos Internacional — Função da Secretaria Administrativa do MERCOSUL', '## Função da Secretaria Administrativa do MERCOSUL

A SAM desempenha atividades como arquivo oficial e publicação de decisões do MERCOSUL.

### Conceitos
- **Secretaria Administrativa**: Entidade responsável por realizar certas atividades do MERCOSUL
- **MERCOSUL**: Organização regional de integração econômica

### Referências legais
- Art. 32 do Protocolo de Ouro Preto

### Dicas de prova
- Entenda a importância da SAM no contexto do MERCOSUL
