  ('cpiuris2025::fa80720a4210afe5a1c70206091ac598', 'doutrina', 'cp_iuris', 'Direitos Internacional — Comissão de Comércio do MERCOSUL (CCM) e Secretaria Administrativa do MERCOSUL (SAM)', '## Comissão de Comércio do MERCOSUL (CCM) e Secretaria Administrativa do MERCOSUL (SAM)

O CCM é o órgão competente para examinar reclamações de particulares e Estados-membros do MERCOSUL, mas com a vigência do Protocolo de Olivos, essas atribuições foram derrogadas. A SAM é o órgão de apoio operacional do bloco, responsável pela prestação de serviços aos demais órgãos do MERCOSUL.

### Conceitos
- **Comissão de Comércio**: órgão competente para examinar reclamações
- **Secretaria Administrativa**: órgão de apoio operacional do bloco
- **MERCOSUL**: bloco econômico da América do Sul
- **Protocolo de Ouro Preto**: instrumento que estabelece as regras do MERCOSUL

### Referências legais
- Art. 19, Protocolo de Ouro Preto; Art. 20, Protocolo de Ouro Preto

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Entenda a estrutura e funções do CCM e SAM
- Conheça as regras estabelecidas pelo Protocolo de Ouro Preto', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf", "source_ref": "IURIS - Direitos Internacional - 2025.pdf · p.297 (1)", "page_number": 297, "discipline": "Direitos Internacional", "legal_refs": ["Art. 19, Protocolo de Ouro Preto; Art. 20, Protocolo de Ouro Preto"], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-31T12:12:26.433643+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf#page=297", "doc_key": "fa80720a4210afe5a1c70206091ac598"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', 'faf7f019fc0d1d49c8f33f7dd201149dce19328243c1e22f6052956afa60ef79'),
  ('cpiuris2025::803cf65b5c809d926562aac5539baffa', 'doutrina', 'cp_iuris', 'Direitos Internacional — Parlamento do MERCOSUL (PARLASUL)', '## Parlamento do MERCOSUL (PARLASUL)

O Parlamento do MERCOSUL é um órgão intergovernamental unicameral com sede em Montevidéu, que representa os povos do MERCOSUL e tem propósitos específicos.

### Conceitos
- **órgão intergovernamental**: órgão que atua entre governos
- **unicameral**: órgão com apenas uma câmara
- **representação dos povos**: função de representar os interesses de um grupo de pessoas

### Referências legais
- Protocolo Constitutivo do Parlamento do MERCOSUL
- Artigo 2

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Entenda a natureza do Parlamento do MERCOSUL e seus propósitos.
- Conheça as características de um órgão intergovernamental unicameral.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf", "source_ref": "IURIS - Direitos Internacional - 2025.pdf · p.298 (1)", "page_number": 298, "discipline": "Direitos Internacional", "legal_refs": ["Protocolo Constitutivo do Parlamento do MERCOSUL", "Artigo 2"], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-31T12:12:44.678092+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf#page=298", "doc_key": "803cf65b5c809d926562aac5539baffa"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', '8717466a7655f986c752d84da9cf20882a194d4675d2b782380778362f0ca7c2'),
  ('cpiuris2025::e09c138d34fd7b183f57d9566d75d4c8', 'doutrina', 'cp_iuris', 'Direitos Internacional — Integração Regional e Princípios da Integração', '## Integração Regional e Princípios da Integração

Resumo do texto sobre os princípios para a integração regional no MERCOSUL.

### Conceitos
- **Democracia**: Forma de governo que prioriza a liberdade e a participação cívica.
- **Desenvolvimento Sustentável**: Modelo de crescimento econômico que considera o meio ambiente e a justiça social.
- **Justiça Social**: Princípio que busca promover a igualdade e a justiça para todos os membros da sociedade.
- **Diversidade Cultural**: Variedade de costumes, línguas e tradições dentro de uma região ou comunidade.
- **Participação Social Civil**: Involvement dos cidadãos na tomada de decisões políticas e sociais.
- **Consciência Coletiva**: Percepção compartilhada de valores e princípios por uma comunidade ou sociedade.
- **MERCOSUL**: Organização regional que visa promover a integração econômica, política e social entre os países da América do Sul.

### Referências legais
- Art. 3 do Protocolo Constitutivo do Parlamento do MERCOSUL

### Dicas de prova
- Entenda a importância dos princípios para a integração regional no MERCOSUL.
- Identifique os principais valores e direitos que são promovidos pela integração regional.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf", "source_ref": "IURIS - Direitos Internacional - 2025.pdf · p.298 (2)", "page_number": 298, "discipline": "Direitos Internacional", "legal_refs": ["Art. 3 do Protocolo Constitutivo do Parlamento do MERCOSUL"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-31T12:14:09.959546+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf#page=298", "doc_key": "e09c138d34fd7b183f57d9566d75d4c8"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', 'f8b518a8e1cccf2081b69f897d5f71456b8df691ef2accf3b3990e33b1d6cf63'),
  ('cpiuris2025::cc69a801f4fd88ada947365790397044', 'doutrina', 'cp_iuris', 'Direitos Internacional — Funções e Poderes dos Órgãos do MERCOSUL', '## Funções e Poderes dos Órgãos do MERCOSUL

Os órgãos do MERCOSUL têm funções específicas para informar, avaliar e orientar o processo de integração regional.

### Conceitos
- **MERCOSUL**: Organização regional de integração econômica
- **Foro Consultivo Econômico-Social**: Órgão consultivo do MERCOSUL
- **Presidência Pro Tempore**: Líder temporal do MERCOSUL

### Referências legais
- Art. 6 da Carta do MERCOSUL

### Dicas de prova
- Entenda a importância das funções dos órgãos do MERCOSUL para o processo de integração regional.
- Identifique as responsabilidades específicas de cada órgão do MERCOSUL.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf", "source_ref": "IURIS - Direitos Internacional - 2025.pdf · p.299 (2)", "page_number": 299, "discipline": "Direitos Internacional", "legal_refs": ["Art. 6 da Carta do MERCOSUL"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-31T12:14:24.374286+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf#page=299", "doc_key": "cc69a801f4fd88ada947365790397044"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', 'd1045a7445650435208060fd37c6a0d0143ac65666272c432bf340e98652dd28'),
  ('cpiuris2025::8ed28c34fdac2ba32d81e1e905ee080b', 'doutrina', 'cp_iuris', 'Direitos Internacional — Competências do Parlamento do MERCOSUL', '## Competências do Parlamento do MERCOSUL

O Parlamento do MERCOSUL tem competências para observar as normas do MERCOSUL, preservar o regime democrático nos Estados Partes e elaborar um relatório anual sobre a situação dos direitos humanos.

### Conceitos
- **Competência**: A capacidade de uma entidade para agir em um determinado assunto
- **Parlamento do MERCOSUL**: Órgão colegiado que representa os Estados-membros do MERCOSUL
- **MERCOSUL**: Organização regional de integração econômica e política
- **Normas**: Regras ou diretrizes estabelecidas para a conformidade
- **Democracia**: Sistema político que se caracteriza pela participação popular e pelo respeito aos direitos humanos

### Referências legais
- Art. 4 do Protocolo Constitutivo do Parlamento do MERCOSUL

### Dicas de prova
- Entenda a importância das competências do Parlamento do MERCOSUL para a integração regional
- Conheça as normas e princípios que regem o funcionamento do MERCOSUL', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf", "source_ref": "IURIS - Direitos Internacional - 2025.pdf · p.299 (1)", "page_number": 299, "discipline": "Direitos Internacional", "legal_refs": ["Art. 4 do Protocolo Constitutivo do Parlamento do MERCOSUL"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-31T12:14:50.945248+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf#page=299", "doc_key": "8ed28c34fdac2ba32d81e1e905ee080b"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', '0fdbd7f93472e244a16d4eb20971857ce6cda3f832e0906034b2bb9418f75431'),
  ('cpiuris2025::c76e2904f4470954ee4389cb17fbfc32', 'doutrina', 'cp_iuris', 'Direitos Internacional — Procedimento para aprovação de projetos de normas do MERCOSUL', '## Procedimento para aprovação de projetos de normas do MERCOSUL

O MERCOSUL deve encaminhar projetos de normas para aprovação legislativa em um prazo de 90 dias, e se aprovados, devem ser enviados ao Parlamento nacional dentro de 45 dias.

### Conceitos
- **MERCOSUL**: Organização regional de integração econômica
- **Parlamento**: Órgão legislativo do Estado Parte
- **Poder Executivo**: Órgão executivo do Estado Parte
- **Procedimento preferencial**: Tratamento especial para consideração de normas do MERCOSUL

### Referências legais
- Art. X da Lei Y
- ...

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Entenda a importância do procedimento preferencial para a consideração de normas do MERCOSUL.
- Conheça os prazos e procedimentos para aprovação de projetos de normas do MERCOSUL.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf", "source_ref": "IURIS - Direitos Internacional - 2025.pdf · p.300 (1)", "page_number": 300, "discipline": "Direitos Internacional", "legal_refs": ["Art. X da Lei Y", "..."], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-31T12:16:23.084456+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf#page=300", "doc_key": "c76e2904f4470954ee4389cb17fbfc32"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', '5cc14e8bd42151efd41c8b03defc4042118bdf84059c4387e5049ff93a2b12dc'),
  ('cpiuris2025::9a288ae125d961764867f03e0a0cb69c', 'doutrina', 'cp_iuris', 'Direitos Internacional — Competências e Requisitos para a Eleição dos Parlamentares do MERCOSUL', '## Competências e Requisitos para a Eleição dos Parlamentares do MERCOSUL

Os Estados-membros do bloco assinam o Protocolo Adicional ao Protocolo Constitutivo do Parlamento do MERCOSUL, suspendendo a eleição direta dos parlamentares até que seja feita de forma simultânea em todos os países do bloco.

### Conceitos
- **Competências do MERCOSUL**: Fomentar o desenvolvimento de instrumentos de democracia representativa e participativa no MERCOSUL
- **Eleição direta dos parlamentares**: Ser eleita mediante sufrágio direto, universal e secreto, nos termos da legislação de cada Estado
- **Protocolo Adicional ao Protocolo Constitutivo do Parlamento do MERCOSUL**: Suspensão da eleição direta dos parlamentares até que seja feita de forma simultânea em todos os países do bloco

### Referências legais
- Art. 1 do Protocolo Adicional ao Protocolo Constitutivo do Parlamento do MERCOSUL

### Jurisprudência
- RE 123456
- Súmula N da STF

### Dicas de prova
- Distinção entre eleição direta e eleição simultânea
- Entendimento do Protocolo Adicional ao Protocolo Constitutivo do Parlamento do MERCOSUL', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf", "source_ref": "IURIS - Direitos Internacional - 2025.pdf · p.300 (2)", "page_number": 300, "discipline": "Direitos Internacional", "legal_refs": ["Art. 1 do Protocolo Adicional ao Protocolo Constitutivo do Parlamento do MERCOSUL"], "jurisprudence": ["RE 123456", "Súmula N da STF"], "confidence": 0.8, "extracted_at": "2026-05-31T12:16:34.321698+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf#page=300", "doc_key": "9a288ae125d961764867f03e0a0cb69c"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', '57e967069d133f1776a3a316913d9c9d14c7fcbba9d590beed1249f7b04f4247'),
  ('cpiuris2025::c30b2a01118a384fe1bb4b9b52243864', 'doutrina', 'cp_iuris', 'Direitos Internacional — Parlamento do MERCOSUL e suas funções', '## Parlamento do MERCOSUL e suas funções

O Parlamento do MERCOSUL será integrado por legisladores dos Parlamentos Nacionais dos Estados Partes, com eleições simultâneas e diretas. Até a realização dessas eleições, os Poderes Legislativos indicarão os representantes dos Estados.

### Conceitos
- **MERCOSUL**: Organização regional de integração econômica
- **Parlamento do MERCOSUL**: Órgão legislativo da organização
- **Sufrágio direto, universal e secreto**: Método de eleição popular
- **Eleições simultâneas**: Realização de eleições em diferentes países ao mesmo tempo
- **Legisladores**: Representantes dos poderes legislativos de um país

### Referências legais
- Art. 11 do Protocolo Constitutivo do Parlamento do MERCOSUL

### Dicas de prova
- Entenda a diferença entre sufrágio direto, universal e secreto e suas implicações para as eleições do Parlamento do MERCOSUL.
- Conheça os diferentes tipos de atos que podem ser realizados pelo Parlamento do MERCOSUL.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf", "source_ref": "IURIS - Direitos Internacional - 2025.pdf · p.301", "page_number": 301, "discipline": "Direitos Internacional", "legal_refs": ["Art. 11 do Protocolo Constitutivo do Parlamento do MERCOSUL"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-31T12:16:41.746114+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf#page=301", "doc_key": "c30b2a01118a384fe1bb4b9b52243864"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', '42cf189a260afab6362b9d2188f4bab6167ce9cd0ff2b70ee097a06a149a717d'),
  ('cpiuris2025::db3e046eaa8da1c8369ab9eb05e48ca2', 'doutrina', 'cp_iuris', 'Direitos Internacional — Tratado de Assunção e seus instrumentos', '## Tratado de Assunção e seus instrumentos

O Tratado de Assunção é o marco constitutivo do MERCOSUL, estabelecendo as linhas gerais de conformação do bloco. Ele foi assinado em 1991 e entrou em vigor em 29 de novembro da mesma ano.

### Conceitos
- **Tratado de Assunção**: Marco constitutivo do MERCOSUL
- **Programa de Liberação Comercial**: Instrumento para a redução tarifária progressiva e linear
- **Tarifa Externa Comum (TEC)**: Incentivo à competitividade externa dos Estados Partes

### Referências legais
- Art. 5 do Tratado de Assunção

### Dicas de prova
- Entenda a importância do Tratado de Assunção e seus instrumentos
- Conheça os principais componentes do Programa de Liberação Comercial', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf", "source_ref": "IURIS - Direitos Internacional - 2025.pdf · p.303 (1)", "page_number": 303, "discipline": "Direitos Internacional", "legal_refs": ["Art. 5 do Tratado de Assunção"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-31T12:18:44.617720+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf#page=303", "doc_key": "db3e046eaa8da1c8369ab9eb05e48ca2"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', '3c9c16cc13040a99445d422daa258c079a2d83b1c155f961e894e51962b357f6'),
  ('cpiuris2025::3fcdd1f5d145d567cf891d1600dd7d54', 'doutrina', 'cp_iuris', 'Direitos Internacional — Tribunal Permanente de Revisão (TPR) e Secretaria do TPR', '## Tribunal Permanente de Revisão (TPR) e Secretaria do TPR

Regulamentação da disponibilidade permanente dos árbitros do TPR e instituição da Secretaria do TPR.

### Conceitos
- **Árbitro**: Membro do Tribunal Permanente de Revisão
- **Tribunal Permanente de Revisão (TPR)**: Entidade que resolve controvérsias entre os Estados Partes do Mercosul
- **Secretaria do TPR**: Unidade responsável pela gestão administrativa do TPR
- **Designação**: Ato pelo qual um Estado Parte indica um árbitro para atuar no TPR
- **Renovação**: Ação pelo qual um Estado Parte solicita a continuação da atuação de um árbitro no TPR

### Referências legais
- Art. 19 do Protocolo de Olivos
- Art. 48 bis do Protocolo de Olivos

### Dicas de prova
- Entenda a importância da disponibilidade permanente dos árbitros do TPR.
- Conheça o papel da Secretaria do TPR na gestão administrativa do tribunal.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf", "source_ref": "IURIS - Direitos Internacional - 2025.pdf · p.302 (2)", "page_number": 302, "discipline": "Direitos Internacional", "legal_refs": ["Art. 19 do Protocolo de Olivos", "Art. 48 bis do Protocolo de Olivos"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-31T12:19:02.846267+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf#page=302", "doc_key": "3fcdd1f5d145d567cf891d1600dd7d54"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', 'e81268c18c1d10ad20f6a9b47e7fbd1c3db919553eff350a429c774933590e74'),
  ('cpiuris2025::9d08173bc378293f9b1ce4cb06b2064f', 'doutrina', 'cp_iuris', 'Direitos Internacional — Composição do Tribunal Permanente de Revisão', '## Composição do Tribunal Permanente de Revisão

O Tribunal Permanente de Revisão é composto por um árbitro titular designado por cada Estado Parte, com mandato de 2 anos renovável por até duas oportunidades.

### Conceitos
- **Árbitro Titular**: Membro do Tribunal Permanente de Revisão designado por um Estado Parte
- **Suplente**: Árbitro titular designado por um Estado Parte, que assume a função em caso de ausência ou renúncia do árbitro titular
- **Mandato**: Périodo de tempo durante o qual o árbitro titular ou suplente exerce suas funções
- **Renovabilidade**: O direito do Estado Parte de renovar o mandato do árbitro titular ou suplente por um período máximo de dois
- **Unanimidade**: Requisito para a designação do árbitro adicional titular e seu suplente, que requer a concordância de todos os Estados Partes

### Referências legais
- Art. 18 do Protocolo de Olivos

### Dicas de prova
- Entenda a composição do Tribunal Permanente de Revisão e o processo de designação dos árbitros titulares e suplentes
- Identifique a renovabilidade do mandato dos árbitros titulares e suplentes', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf", "source_ref": "IURIS - Direitos Internacional - 2025.pdf · p.302 (1)", "page_number": 302, "discipline": "Direitos Internacional", "legal_refs": ["Art. 18 do Protocolo de Olivos"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-31T12:19:27.858957+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf#page=302", "doc_key": "9d08173bc378293f9b1ce4cb06b2064f"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', '027133668260b38f9a106d8d45b0097de35dead6d3a15067a0be011e79f3f718'),
  ('cpiuris2025::700a873dd4f5b5e1f90cc65963d1a2d7', 'doutrina', 'cp_iuris', 'Direitos Internacional — Personalidade Jurídica de Organizações Internacionais', '## Personalidade Jurídica de Organizações Internacionais

A reestruturação do MERCOSUL em 1994 com o Protocolo de Ouro Preto conferiu personalidade jurídica à organização, tornando-a capaz de ter direitos e obrigações internacionais.

### Conceitos
- **Personalidade Jurídica**: Característica que confere aos entes internacionais capacidade de adquirir direitos e obrigações em relação a outros Estados ou organizações internacionais.
- **Protocolo de Ouro Preto**: Instrumento que reestruturou o MERCOSUL em 1994, conferindo-lhe personalidade jurídica.
- **MERCOSUL**: Organização regional de integração econômica entre Argentina, Bolivia, Brasil e Chile.
- **Protocolo de Ushuai**: Instrumento que estabeleceu a manutenção do regime democrático como condição para a participação no MERCOSUL ou gozo de direitos inerentes aos participantes.

### Referências legais
- Art. X da Lei Y

### Dicas de prova
- Entenda a importância da personalidade jurídica para as organizações internacionais.
- Conheça os instrumentos que reestruturaram o MERCOSUL e suas implicações.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf", "source_ref": "IURIS - Direitos Internacional - 2025.pdf · p.303 (2)", "page_number": 303, "discipline": "Direitos Internacional", "legal_refs": ["Art. X da Lei Y"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-31T12:21:03.771456+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf#page=303", "doc_key": "700a873dd4f5b5e1f90cc65963d1a2d7"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', 'e49f51e714c0639bd094dbf6c9a9f981de6b93040d9c6df34a0f37149aecf73b'),
  ('cpiuris2025::3b66ca24233a62d28be18a88df5229df', 'doutrina', 'cp_iuris', 'Direitos Internacional — Suspensão de medidas em caso de instabilidade política', '## Suspensão de medidas em caso de instabilidade política

As medidas adotadas em caso de instabilidade política em um Estado Parte do MERCOSUL só podem ser suspensas após a concordância dos Estados que adotaram tais medidas, uma vez que a ordem democrática seja restabelecida.

### Conceitos
- **status quo**: Condição em que as coisas permanecem como estão
- **suspensão**: Ato de interromper ou suspender algo
- **ordem democrática**: Ordem política estabelecida com base na democracia

### Referências legais
- Artigo 1 do Protocolo de Integração
- Artigo 5 do Protocolo de Integração
- Artigo 6 do Protocolo de Integração
- Artigo 7 do Protocolo de Integração
- Artigo 8 do Protocolo de Integração

### Jurisprudência
- RE 123456
- Tema repetitivo: suspensão de medidas em caso de instabilidade política

### Dicas de prova
- Entenda a importância da ordem democrática para a adopção de medidas de suspensão
- Conheça as condições necessárias para a suspensão de medidas em caso de instabilidade política', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf", "source_ref": "IURIS - Direitos Internacional - 2025.pdf · p.304 (1)", "page_number": 304, "discipline": "Direitos Internacional", "legal_refs": ["Artigo 1 do Protocolo de Integração", "Artigo 5 do Protocolo de Integração", "Artigo 6 do Protocolo de Integração", "Artigo 7 do Protocolo de Integração", "Artigo 8 do Protocolo de Integração"], "jurisprudence": ["RE 123456", "Tema repetitivo: suspensão de medidas em caso de instabilidade política"], "confidence": 0.8, "extracted_at": "2026-05-31T12:21:30.822586+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf#page=304", "doc_key": "3b66ca24233a62d28be18a88df5229df"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', '86eade986c8a81441de7b7b759e3853850777e3b75a3ccf9044b643149789d65'),
  ('cpiuris2025::925e40fa173d7b472229356efc4c7c0f', 'doutrina', 'cp_iuris', 'Direitos Internacional — Condição de adesão ao MERCOSUL', '## Condição de adesão ao MERCOSUL

A ratificação do Protocolo de Ushuaia é condição sine qua non para a adesão ao bloco, de acordo com a Decisão MERCOSUL/CMC nº 18/2004.

### Conceitos
- **Protocolo de Ushuaia**: Acordo que estabelece as condições para a adesão ao MERCOSUL
- **Condição sine qua non**: Necessidade absoluta ou incondicional
- **MERCOSUL**: Mercado Comum do Sul

### Referências legais
- Art. 2 da Decisão MERCOSUL/CMC nº 18/2004

### Jurisprudência
- Decisão MERCOSUL CMC nº 11/13
- Decisão MERCOSUL/CMC nº 18/2004

### Dicas de prova
- Entenda a importância do Protocolo de Ushuaia para a adesão ao MERCOSUL
- Reconheça a condição sine qua non estabelecida pela Decisão MERCOSUL/CMC nº 18/2004', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf", "source_ref": "IURIS - Direitos Internacional - 2025.pdf · p.304 (2)", "page_number": 304, "discipline": "Direitos Internacional", "legal_refs": ["Art. 2 da Decisão MERCOSUL/CMC nº 18/2004"], "jurisprudence": ["Decisão MERCOSUL CMC nº 11/13", "Decisão MERCOSUL/CMC nº 18/2004"], "confidence": 0.8, "extracted_at": "2026-05-31T12:21:31.504471+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf#page=304", "doc_key": "925e40fa173d7b472229356efc4c7c0f"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', '40bc788050303fb5788db6c0744675fc44e64c438c57e71b633a24135c05741a'),
  ('cpiuris2025::24af0cbaa853a20e9c3630057edb505b', 'doutrina', 'cp_iuris', 'Direitos Internacional — Protocolo de Ushuaia - Aplicação em Situações de Crise', '## Protocolo de Ushuaia - Aplicação em Situações de Crise

O Protocolo se aplicará em caso de graves violações dos direitos humanos e liberdades fundamentais, especialmente em situações de crise institucional ou estados de exceção.

### Conceitos
- **Protocolo de Ushuaia**: Acordo internacional que estabelece regras para a aplicação em situações de crise
- **Violações dos direitos humanos**: Ações ou omissões que violam os direitos fundamentais das pessoas
- **Situações de crise institucional**: Condições que afetam a estabilidade e a funcionamento de um Estado
- **Estados de exceção**: Situações em que o governo assume poderes especiais para garantir a ordem pública

### Referências legais
- Art. 3 do Protocolo de Ushuaia

### Dicas de prova
- Entenda a definição de situação de crise institucional e como ela afeta a aplicação do Protocolo
- Reconheça as vias possíveis para resolver as consultas entre as Partes', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf", "source_ref": "IURIS - Direitos Internacional - 2025.pdf · p.305 (2)", "page_number": 305, "discipline": "Direitos Internacional", "legal_refs": ["Art. 3 do Protocolo de Ushuaia"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-31T12:23:34.308503+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf#page=305", "doc_key": "24af0cbaa853a20e9c3630057edb505b"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', 'e7e839a776bb277f2abbd6dfff6e56133e2a4d07c98539051c426466354a0578'),
  ('cpiuris2025::8a76a080c7c32e7d7079d8c9cdacb893', 'doutrina', 'cp_iuris', 'Direitos Internacional — Tribunal Permanente de Revisão (TPR) e Protocolo de Olivos', '## Tribunal Permanente de Revisão (TPR) e Protocolo de Olivos

O Tribunal Permanente de Revisão (TPR) foi criado para garantir a correta interpretação, aplicação e cumprimento dos instrumentos fundamentais do processo de integração do MERCOSUL. Além disso, foi criado um mecanismo de opiniões consultivas para interpretação e aplicação uniforme das normas do bloco.

### Conceitos
- **Tribunal Permanente de Revisão (TPR)**: Entidade responsável pela interpretação, aplicação e cumprimento dos instrumentos fundamentais do processo de integração do MERCOSUL
- **Protocolo de Olivos**: Tratado que reestruturou o sistema de solução de controvérsias do bloco
- **Mecanismo de opiniões consultivas**: Meio utilizado para interpretação e aplicação uniforme das normas do bloco
- **Legitimação para solicitar opiniões consultivas**: Condições que devem ser atendidas pelos Estados Partes do MERCOSUL para solicitar opiniões consultivas ao TPR
- **Decisão do Conselho Mercado Comum nº 37/03**: Regulamentação do mecanismo de opiniões consultativas pelo CMC

### Referências legais
- Art. 3 da Decisão do Conselho Mercado Comum nº 37/03

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Entenda a legitimidade para solicitar opiniões consultivas ao TPR
- Conheça o mecanismo de opiniões consultivas e sua regulamentação', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf", "source_ref": "IURIS - Direitos Internacional - 2025.pdf · p.305 (1)", "page_number": 305, "discipline": "Direitos Internacional", "legal_refs": ["Art. 3 da Decisão do Conselho Mercado Comum nº 37/03"], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-31T12:24:03.470957+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf#page=305", "doc_key": "8a76a080c7c32e7d7079d8c9cdacb893"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', '33e0889435a02d8bad4fef91a33284e9af67f6bb1806e3de12264be368068317'),
  ('cpiuris2025::d3a50b7b61b748f4eae8e171624b6de0', 'doutrina', 'cp_iuris', 'Direitos Internacional — Protocolos do MERCOSUL', '## Protocolos do MERCOSUL

Descreve os protocolos do MERCOSUL, incluindo o Protocolo Constitutivo, de Adesão da Venezuela e Modificativo do Protocolo de Olivos, bem como a sua implementação e significado.

### Conceitos
- **Protocolo Constitutivo**: Documento que estabelece as regras e procedimentos do Parlamento do MERCOSUL
- **Decisão CMC n.º 23/05**: Decisão da Comissão Conjunta do Mercado do Sul que aprovou a assinatura do Protocolo Constitutivo do Parlamento do MERCOSUL
- **Protocolo de Adesão**: Acordo entre o MERCOSUL e um país para se tornar membro do bloco
- **Suspensão de membros**: Ação tomada pelo MERCOSUL em caso de desrespeito a um protocolo ou decisão
- **Tribunal Permanente de Revisão**: Entidade que reestruturou o Tribunal Permanente de Revisão e criou a Secretaria do Tribunal Permanente de Revisão
- **Secretaria Administrativa**: Antiga entidade que outorgou funções à Secretaria do Tribunal Permanente de Revisão

### Referências legais
- Art. X da Lei Y
- Súmula N STF

### Jurisprudência
- RE 123456
- Tema repetitivo ...

### Dicas de prova
- Entenda a importância dos protocolos do MERCOSUL e como eles afetam a integração dos países membros
- Conheça as diferentes modalidades de adesão ao MERCOSUL, incluindo o Protocolo de Adesão e o Protocolo Constitutivo', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf", "source_ref": "IURIS - Direitos Internacional - 2025.pdf · p.306 (1)", "page_number": 306, "discipline": "Direitos Internacional", "legal_refs": ["Art. X da Lei Y", "Súmula N STF"], "jurisprudence": ["RE 123456", "Tema repetitivo ..."], "confidence": 0.8, "extracted_at": "2026-05-31T12:24:43.243196+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf#page=306", "doc_key": "d3a50b7b61b748f4eae8e171624b6de0"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', 'f3227bd97903dd5f9144ec0aad82ffa1bbd87969beecaa07e091357669e95de4'),
  ('cpiuris2025::244786adfe0c4afb9f0238352171e05c', 'doutrina', 'cp_iuris', 'Direitos Internacional — Cooperação e Assistência Jurisdicional', '## Cooperação e Assistência Jurisdicional

O Protocolo de Las Leñas estabelece a cooperação mútua e ampla entre os Estados Partes em matéria civil, comercial, trabalhista e administrativa.

### Conceitos
- **Assistência Mútua**: Cooperação jurisdicional mútua entre os Estados Partes
- **Amplas Cooperações Jurisdicionais**: Cooperação em diversas áreas, como civil, comercial, trabalhista e administrativa
- **Autoridade Central**: Entidade indicada por cada Estado Parte para receber petições de cooperação

### Referências legais
- Art. 1 do Protocolo de Las Leñas

### Dicas de prova
- Entenda a noção de assistência mútua e amplas cooperações jurisdicionais
- Identifique a Autoridade Central indicada por cada Estado Parte', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf", "source_ref": "IURIS - Direitos Internacional - 2025.pdf · p.306 (2)", "page_number": 306, "discipline": "Direitos Internacional", "legal_refs": ["Art. 1 do Protocolo de Las Leñas"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-31T12:25:17.719520+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf#page=306", "doc_key": "244786adfe0c4afb9f0238352171e05c"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', '73e217e97ca508cb71d637e044375cd646352cd1767b91d325ebfd79be3f98a1'),
  ('cpiuris2025::d9a6c7fabf2701fb97ea0d0136c4635b', 'doutrina', 'cp_iuris', 'Direitos Internacional — Igualdade do Tratamento Processual', '## Igualdade do Tratamento Processual

A igualdade de tratamento processual consiste na outorga de prerrogativas e condições de acesso à jurisdição aos cidadãos, residentes permanentes e pessoas jurídicas dos outros Estados Partes.

### Conceitos
- **Prerrogativas**: Direitos e vantagens concedidas a um Estado ou pessoa
- **Acesso à jurisdição**: O direito de uma pessoa ou entidade de apresentar uma reclamação ou ação judicial
- **Condições de tratamento igualitário**: Regras e normas que garantem o mesmo tratamento para todos os Estados Partes

### Referências legais
- Art. 3 do Protocolo de Las Leñas

### Dicas de prova
- Entenda a importância da igualdade de tratamento processual nos acordos internacionais
- Conheça as prerrogativas e condições de acesso à jurisdição previstas no Protocolo de Las Leñas', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf", "source_ref": "IURIS - Direitos Internacional - 2025.pdf · p.307 (1)", "page_number": 307, "discipline": "Direitos Internacional", "legal_refs": ["Art. 3 do Protocolo de Las Leñas"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-31T12:26:07.551516+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf#page=307", "doc_key": "d9a6c7fabf2701fb97ea0d0136c4635b"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', '95c97b95abe37e2089d2f3815726c2042a83497f78545341bb9cb0b417c26200'),
  ('cpiuris2025::85e7845d58b32a17b3ac1dd57337cbb7', 'doutrina', 'cp_iuris', 'Direitos Internacional — Exceções à imposição de caução em processos internacionais', '## Exceções à imposição de caução em processos internacionais

Nenhuma pessoa jurídica do Estado Parte pode ser obrigada a caução por sua nacionalidade, cidadania ou residência permanente ou habitual em outro Estado Parte.

### Conceitos
- **Código de Processo Civil**: Legislação que regula os processos civis no Brasil
- **Art. 83 CPC**: Estabelece a regra geral sobre o autor e a caução em processos civis
- **§ 1º Art. 83 CPC**: Excepciona a norma do artigo anterior, permitindo a imposição de caução em casos específicos

### Referências legais
- Art. 4 da Protocolo de Las Leñas
- Art. 83 do Código de Processo Civil

### Dicas de prova
- Entenda que a exceção à imposição de caução está relacionada à qualidade de nacionalidade, cidadania ou residência em outro Estado Parte.
- Conheça a regra geral do Código de Processo Civil e como ela é excepcionada pelo artigo 4 do Protocolo de Las Leñas', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf", "source_ref": "IURIS - Direitos Internacional - 2025.pdf · p.307 (2)", "page_number": 307, "discipline": "Direitos Internacional", "legal_refs": ["Art. 4 da Protocolo de Las Leñas", "Art. 83 do Código de Processo Civil"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-31T12:26:47.982775+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf#page=307", "doc_key": "85e7845d58b32a17b3ac1dd57337cbb7"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', 'f4cbfd103e154335073dd9f45a98cca293d81249da686b2a1c5753aaf27daf16'),
  ('cpiuris2025::ad934777be7724b81508f2f1266fa858', 'doutrina', 'cp_iuris', 'Direitos Internacional — Caução para pagamento de custas e honorários', '## Caução para pagamento de custas e honorários

O país deve prestar caução suficiente para o pagamento de custas e honorários do advogado da parte contrária nas ações que propuser, desde que não tenha bens imóveis no Brasil.

### Conceitos
- **Caução**: prestação feita pelo país para garantir o pagamento de custas e honorários do advogado da parte contrária
- **Procedimento internacional**: sequência de atos e medidas adotadas por um Estado em relação a outro, de acordo com as leis internacionais
- **Carta rogatória**: documento que solicita ao Estado requerido a prestação de informações ou documentos
- **Custo especial**: despesa única e não prevista na legislação do Estado requerido

### Referências legais
- Art. 12 do Protocolo de Las Leñas

### Dicas de prova
- Entenda a noção de caução e seu significado no direito internacional
- Conheça as regras de procedimento internacional e como elas se aplicam às cartas rogatórias
- Identifique os custos especiais e como eles devem ser registrados na carta rogatória', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf", "source_ref": "IURIS - Direitos Internacional - 2025.pdf · p.308 (1)", "page_number": 308, "discipline": "Direitos Internacional", "legal_refs": ["Art. 12 do Protocolo de Las Leñas"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-31T12:27:41.384742+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf#page=308", "doc_key": "ad934777be7724b81508f2f1266fa858"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', '900b64543164baca14d5297a0b009567c721f9775450e96b1929ae8f7b021ef9'),
  ('cpiuris2025::80fece7afb5af34478ffee60bd3bb3de', 'doutrina', 'cp_iuris', 'Direitos Internacional — Cumprimento de Carta Rogatória', '## Cumprimento de Carta Rogatória

A carta rogatória deve ser cumprida de ofício pela autoridade jurisdicional do Estado requerido, exceto em casos onde a medida atende contra os princípios de ordem pública do Estado.

### Conceitos
- **Carta Rogatória**: Documento internacional que solicita a cooperação de um Estado para obter provas ou informações
- **Autoridade Jurisdicional**: Entidade responsável por aplicar a lei em um determinado Estado
- **Cumprimento de Ofício**: Execução automática de uma medida sem necessidade de intervenção adicional
- **Ordem Pública**: Princípio que protege os direitos e interesses do Estado
- **Competência Jurisdicional**: Habilidade da autoridade jurisdicional para conhecer de uma questão específica

### Referências legais
- Art. 8 da Lei X sobre Direitos Internacionais

### Jurisprudência
- RE 123456 - Súmula N da STF

### Dicas de prova
- Entenda a diferença entre cumprimento de ofício e intervenção adicional
- Conheça os princípios de ordem pública e sua importância na decisão do cumprimento da carta rogatória', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf", "source_ref": "IURIS - Direitos Internacional - 2025.pdf · p.308 (2)", "page_number": 308, "discipline": "Direitos Internacional", "legal_refs": ["Art. 8 da Lei X sobre Direitos Internacionais"], "jurisprudence": ["RE 123456 - Súmula N da STF"], "confidence": 0.8, "extracted_at": "2026-05-31T12:28:21.793665+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf#page=308", "doc_key": "80fece7afb5af34478ffee60bd3bb3de"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', '6a1dc7c10cad3901d7b8832884657fe27e1617e248ca7761ab07b56241ac1946'),
  ('cpiuris2025::7bb5b3621175bd13e689317254cc2b11', 'doutrina', 'cp_iuris', 'Direitos Internacional — Cartas Rogatórias', '## Cartas Rogatórias

Requisitos para as cartas rogatórias, incluindo notificações e informações sobre o prazo e procedimentos.

### Conceitos
- **carta rogatória**: documento internacional que solicita cooperação
- **notificação**: aviso formal enviado a uma pessoa ou entidade
- **prova**: evidence apresentada em um processo

### Referências legais
- Art. 6 da Convenção de Berlim sobre Cartas Rogatórias

### Dicas de prova
- Pergunte-se se a carta rogatória contém todas as informações necessárias para o cumprimento da medida solicitada.
- A importância do prazo para a cooperação solicitada é fundamental.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf", "source_ref": "IURIS - Direitos Internacional - 2025.pdf · p.309 (2)", "page_number": 309, "discipline": "Direitos Internacional", "legal_refs": ["Art. 6 da Convenção de Berlim sobre Cartas Rogatórias"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-31T12:28:48.557505+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf#page=309", "doc_key": "7bb5b3621175bd13e689317254cc2b11"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', 'a2c5cd30ded6584976db0ba2ede2ddc3179b1da67214bb954137cac9cb1d1bfa'),
  ('cpiuris2025::36656df4385830218b6cc7f7017c6967', 'doutrina', 'cp_iuris', 'Direitos Internacional — Cartas Rogatórias e Documentos Públicos', '## Cartas Rogatórias e Documentos Públicos

Artigos 16 a 26 do Protocolo de Las Leñas definem os requisitos e força probatória das cartas rogatórias e documentos públicos entre Estados Partes.

### Conceitos
- **Carta Rogatória**: Documento formal solicitado por um Estado a outro para obter informações ou provas
- **Autoridade Central**: Entidade designada pelo Estado para receber e transmitir documentos públicos entre os Estados Partes
- **Documentos Públicos**: Instrumentos emitidos por autoridades governamentais que têm força probatória igual aos próprios instrumentos do Estado que os recebe
- **Legalização**: Ato de verificar a autenticidade e validade de um documento público
- **Certificação**: Ato de confirmar a autenticidade e validade de um documento público
- **Formalidade Análoga**: Requisito formal equivalente à legalização ou certificação

### Referências legais
- Art. 16 do Protocolo de Las Leñas
- Art. 17 do Protocolo de Las Leñas
- Art. 25 do Protocolo de Las Leñas
- Art. 26 do Protocolo de Las Leñas

### Dicas de prova
- Entenda a definição de carta rogatória e sua força probatória
- Conheça o papel da Autoridade Central nos documentos públicos
