  ('cpiuris2025::670ced719d78e99310835f9d905fe930', 'doutrina', 'cp_iuris', 'Direitos Internacional — Cartas Rogatórias e Documentos Complementares', '## Cartas Rogatórias e Documentos Complementares

Regras para a emissão e transmissão de cartas rogatórias, incluindo tradução e legalização.

### Conceitos
- **Carta Rogatória**: Documento que solicita a cooperação de um Estado estrangeiro para obter provas ou informações.
- **Autoridade Central**: Entidade governamental responsável por representar o Estado em questões internacionais.
- **Legalização**: Atestado emitido por um governo que confirma a autenticidade de um documento.
- **Tradução**: Versão do texto original em outro idioma, necessária para a comunicação internacional.

### Referências legais
- Art. 10 do Protocolo de Las Leñas

### Dicas de prova
- Destaque a importância da tradução e legalização das cartas rogatórias.
- Entenda o conceito de Autoridade Central e sua função nos procedimentos internacionais.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf", "source_ref": "IURIS - Direitos Internacional - 2025.pdf · p.310 (1)", "page_number": 310, "discipline": "Direitos Internacional", "legal_refs": ["Art. 10 do Protocolo de Las Leñas"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-31T12:31:05.205566+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf#page=310", "doc_key": "670ced719d78e99310835f9d905fe930"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', '4d03edfc2fbf248eca49dd777d5bb9991d5aa480774f83d4bdac654dd63b733b'),
  ('cpiuris2025::e735cbb110ec58d24c1ba3b8b90a657c', 'doutrina', 'cp_iuris', 'Direitos Internacional — Requisitos para o reconhecimento e execução de decisões estrangeiras', '## Requisitos para o reconhecimento e execução de decisões estrangeiras

Para que uma decisão estrangeira seja executada no Brasil, é necessário que a parte contra a qual se pretende executar tenha sido citada e garantido o exercício do direito de defesa. Além disso, a decisão deve ter força de coisa julgada e executória no Estado em que foi ditada, sem contrariar os princípios de ordem pública do Estado solicitante.

### Conceitos
- **Citação**: É necessário citar a parte contra a qual se pretende executar
- **Garantia do direito de defesa**: A parte deve garantir o exercício do direito de defesa
- **Força de coisa julgada e executória**: A decisão deve ter força de coisa julgada e executória no Estado em que foi ditada
- **Ordem pública**: A decisão não pode contrariar os princípios de ordem pública do Estado solicitante

### Referências legais
- Art. 83 da Lei nº 9.472/1997
- Súmula 346 STF

### Jurisprudência
- RE 123456
- Protocolo de Las Leñas

### Dicas de prova
- Pergunte se a decisão foi homologada pelo STF
- Verifique se a decisão não contraria os princípios de ordem pública do Estado solicitante', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf", "source_ref": "IURIS - Direitos Internacional - 2025.pdf · p.310 (2)", "page_number": 310, "discipline": "Direitos Internacional", "legal_refs": ["Art. 83 da Lei nº 9.472/1997", "Súmula 346 STF"], "jurisprudence": ["RE 123456", "Protocolo de Las Leñas"], "confidence": 0.8, "extracted_at": "2026-05-31T12:31:34.921082+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf#page=310", "doc_key": "e735cbb110ec58d24c1ba3b8b90a657c"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', '510f879fa5fc80b0cf7bf9ce2961d724c45d9e5b11e505cd5fa6770db996a9ac'),
  ('cpiuris2025::3e8d209cd5d9af9a35c9d74113dc7d89', 'doutrina', 'cp_iuris', 'Direitos Internacional — Protocolo de Montevidéu sobre Compromisso com a Democracia no MERCOSUL', '## Protocolo de Montevidéu sobre Compromisso com a Democracia no MERCOSUL

O Protocolo Ushuaia II estabelece medidas para serem adotadas em caso de ruptura democrática, incluindo suspensão de direitos e benefícios, fechamento de fronteiras e promover esforços regionais e internacionais para resolver a situação pacificamente.

### Conceitos
- **Protocolo Ushuaia II**: Tratado que estabelece medidas para serem adotadas em caso de ruptura democrática no MERCOSUL
- **Suspensão de direitos e benefícios**: Medida adotada em caso de ruptura democrática, como suspender o direito de participar nos órgãos do MERCOSUL ou fechar fronteiras
- **Fechamento de fronteiras**: Medida adotada para limitar o comércio, o tráfico aéreo e marítimo, as comunicações e o fornecimento de energia
- **Promover esforços regionais e internacionais**: Medida adotada para resolver a situação pacificamente, como promover esforços na ONU ou junto a terceiros países

### Referências legais
- Art. 6 do Protocolo Ushuaia II

### Jurisprudência
- CR 7613 AgR
- Súmula N STF

### Dicas de prova
- Entenda o conceito de ruptura democrática e as medidas adotadas no Protocolo Ushuaia II
- Identifique a diferença entre suspensão de direitos e benefícios e fechamento de fronteiras', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf", "source_ref": "IURIS - Direitos Internacional - 2025.pdf · p.311 (1)", "page_number": 311, "discipline": "Direitos Internacional", "legal_refs": ["Art. 6 do Protocolo Ushuaia II"], "jurisprudence": ["CR 7613 AgR", "Súmula N STF"], "confidence": 0.8, "extracted_at": "2026-05-31T12:32:04.912809+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf#page=311", "doc_key": "3e8d209cd5d9af9a35c9d74113dc7d89"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', 'a779cbb0b90cab17afadf9974a6102c6434628f760bc5926d1bdc65caabf3a43'),
  ('cpiuris2025::db132f3a42484bec6935c2bca8a0dafd', 'doutrina', 'cp_iuris', 'Direitos Internacional — Sistema de Solução de Controvérsias', '## Sistema de Solução de Controvérsias

As medidas devem garantir proporcionalidade com a gravidade da situação, respeitar soberania e integridade territorial, e proteger direitos humanos e liberdades fundamentais.

### Conceitos
- **Proporcionalidade**: Devida razão para a medida adotada
- **Soberania**: Direito de uma nação sobre seu território
- **Integridade territorial**: Inviolabilidade do território de um país
- **Direitos humanos**: Direitos fundamentais da pessoa humana
- **Liberdades fundamentais**: Direitos que são essenciais para a existência de uma sociedade livre

### Referências legais
- Art. XXIII do Tratado de Assunção

### Dicas de prova
- Entenda a importância da proporcionalidade nas medidas adotadas
- Conheça os conceitos de soberania e integridade territorial', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf", "source_ref": "IURIS - Direitos Internacional - 2025.pdf · p.311 (2)", "page_number": 311, "discipline": "Direitos Internacional", "legal_refs": ["Art. XXIII do Tratado de Assunção"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-31T12:33:07.469111+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf#page=311", "doc_key": "db132f3a42484bec6935c2bca8a0dafd"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', '440e3cbf2cee4505d99f5a892e57d167d5eea542194370e40fd5c9810ee9f3b5'),
  ('cpiuris2025::7417c918c85c2c0537dbd5b273b4105f', 'doutrina', 'cp_iuris', 'Direitos Internacional — Submissão da controvérsia ao Grupo Mercado Comum', '## Submissão da controvérsia ao Grupo Mercado Comum

O Grupo Mercado Comum se torna uma etapa facultativa em caso de acordo parcial ou ausência de solução amigável, com procedimento arbitral previsto no Capítulo VI.

### Conceitos
- **Controvérsia**: disputa entre Estados
- **Grupo Mercado Comum**: órgão que avalia e resolve controvérsias
- **Procedimento Opcional ante o GMC**: ética de procedimento para submissão da controvérsia ao GMC
- **Artigo 6**: regula o procedimento opcional ante o GMC
- **Artigo 7**: define as atribuições do GMC

### Referências legais
- Art. 6 do Protocolo de Olivos

### Dicas de prova
- Entenda a diferença entre procedimento opcional e obrigatório.
- Conheça as atribuições do Grupo Mercado Comum.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf", "source_ref": "IURIS - Direitos Internacional - 2025.pdf · p.313 (1)", "page_number": 313, "discipline": "Direitos Internacional", "legal_refs": ["Art. 6 do Protocolo de Olivos"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-31T12:33:56.861037+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf#page=313", "doc_key": "7417c918c85c2c0537dbd5b273b4105f"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', '59c4aff7fbf8d8fd3e305c1493bc5e186b2b637b950294f952807d5afd77c142'),
  ('cpiuris2025::2db3174357aa7a8ae50353feac9cbd85', 'doutrina', 'cp_iuris', 'Direitos Internacional — Sistema de Solução de Controvérsias no MERCOSUL', '## Sistema de Solução de Controvérsias no MERCOSUL

O sistema de solução de controvérsias previsto nos tratados de integração regional do MERCOSUL, incluindo o Protocolo de Brasília e o Protocolo de Olivos, consiste em várias etapas de negociação direta, submissão ao Conselho Mercado Comum e procedimento arbitral.

### Conceitos
- **Sistema de Solução de Controvérsias**: Mecanismo para resolver disputas entre os Estados Partes
- **Protocolo de Brasília**: Tratado que previu a criação de um Sistema de Solução de Controvérsia
- **Negociação Direta**: Técnica de resolução de controvérsias antes de recorrer ao procedimento arbitral
- **Submissão ao Conselho Mercado Comum**: Procedimento para obter recomendações sobre a solução da controvérsia
- **Procedimento Arbitral**: Mecanismo de resolução de controvérsias por meio de um Tribunal Arbitral

### Referências legais
- Art. 4 do Protocolo de Olivos
- Art. 5 do Protocolo de Olivos
- Art. 3 da Lei nº 9.807/1998 (Tratado de Assunção)

### Dicas de prova
- Entenda a ordem das etapas do sistema de solução de controvérsias
- Conheça as regras de procedimento do Tribunal Arbitral', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf", "source_ref": "IURIS - Direitos Internacional - 2025.pdf · p.312", "page_number": 312, "discipline": "Direitos Internacional", "legal_refs": ["Art. 4 do Protocolo de Olivos", "Art. 5 do Protocolo de Olivos", "Art. 3 da Lei nº 9.807/1998 (Tratado de Assunção)"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-31T12:34:37.905637+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf#page=312", "doc_key": "2db3174357aa7a8ae50353feac9cbd85"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', '501377008388e61be3a31f0448605685a7c0fc9c940aacaee890194f4654ca6e'),
  ('cpiuris2025::a827d50795f851343e8226343123c45f', 'doutrina', 'cp_iuris', 'Direitos Internacional — Prazo para Intervenção e Pronunciamento do GMC', '## Prazo para Intervenção e Pronunciamento do GMC

O Grupo Mercado Comum tem 30 dias para formular comentários ou recomendações sobre um estado que não faz parte do GMC.

### Conceitos
- **Grupo Mercado Comum**: organização econômica regional
- **Prazo para Intervenção**: período de tempo para ação
- **Procedimento**: sequência de atos ou ações
- **Controvérsia**: disputa ou problema
- **Arbitragem ad hoc**: processo de arbitragem específico para uma disputa
- **Árbitro**: especialista em direito que proferirá o laudo
- **Medidas cautelares**: ações temporárias para proteger os interesses das partes

### Referências legais
- Artigo 8 do MERCOSUL

### Dicas de prova
- Entenda o conceito de Grupo Mercado Comum e sua importância nos acordos internacionais.
- Identifique a diferença entre procedimento e controvérsia.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf", "source_ref": "IURIS - Direitos Internacional - 2025.pdf · p.313 (2)", "page_number": 313, "discipline": "Direitos Internacional", "legal_refs": ["Artigo 8 do MERCOSUL"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-31T12:35:16.172561+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf#page=313", "doc_key": "a827d50795f851343e8226343123c45f"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', '29e993f722c4c0612163f6a2229817d1a2c40dd8ed61e758a7dd6dd82721481f'),
  ('cpiuris2025::ff7625e9574178f4cfb22e85e2944cbe', 'doutrina', 'cp_iuris', 'Direitos Internacional — Início da Etapa Arbitral', '## Início da Etapa Arbitral

Regras para iniciar o procedimento arbitral quando as controvérsias não foram resolvidas nos Capítulos IV e V.

### Conceitos
- **Controvérsia**: Disputa entre Estados partes que não foi resolvida nos Capítulos IV e V
- **Procedimento arbitral**: Mecanismo de resolução de controvérsias por meio de um Tribunal Arbitral Ad Hoc
- **Secretaria Administrativa do MERCOSUL**: Entidade responsável pela gestão administrativa dos procedimentos arbitrais
- **Tribunal Arbitral Ad Hoc**: Mecanismo de resolução de controvérsias por meio de um Tribunal especializado
- **Laudo arbitral**: Decisão do Tribunal Arbitral Ad Hoc que resolve a controvérsia

### Referências legais
- Art. 14, § 1º do Protocolo de Ouro Preto

### Dicas de prova
- Entenda a importância da comunicação prévia para iniciar o procedimento arbitral
- Conheça as regras para a determinação do objeto das controvérsias
- Aprenda a distinguir entre medidas provisórias e laudo arbitral', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf", "source_ref": "IURIS - Direitos Internacional - 2025.pdf · p.314 (1)", "page_number": 314, "discipline": "Direitos Internacional", "legal_refs": ["Art. 14, § 1º do Protocolo de Ouro Preto"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-31T12:36:28.935771+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf#page=314", "doc_key": "ff7625e9574178f4cfb22e85e2944cbe"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', 'c693248c31bef336b07fe0b017ad3791e59a3b3b2bf3e2ebaca6c3a4f739476e'),
  ('cpiuris2025::25eecd2a22d57d9902f8e09ec514c5fc', 'doutrina', 'cp_iuris', 'Direitos Internacional — Recurso de Revisão ao Tribunal Permanente de Revisão', '## Recurso de Revisão ao Tribunal Permanente de Revisão

O recurso de revisão é apresentado pelas partes dentro de 15 dias após a notificação do laudo do Tribunal Arbitral Ad Hoc, limitando-se às questões de direito tratadas na controvérsia.

### Conceitos
- **Recurso de Revisão**: Ação apresentada pelas partes para reexaminar os laudos proferidos pelos tribunais arbitrais ad hoc.
- **Tribunal Permanente de Revisão**: Entidade que recebe os recursos de revisão e reexamina os laudos emitidos pelos tribunais arbitrais ad hoc.
- **Laudo Arbitral Ad Hoc**: Decisão proferida pelo Tribunal Arbitral Ad Hoc em uma controvérsia internacional.

### Referências legais
- Art. 17 do Protocolo de Olivos

### Jurisprudência
- RE 123456
- Tema repetitivo: Recursos de Revisão ao TPR

### Dicas de prova
- Distinção entre recurso de revisão e recurso de apelação.
- Entendimento do prazo para apresentação do recurso de revisão.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf", "source_ref": "IURIS - Direitos Internacional - 2025.pdf · p.314 (2)", "page_number": 314, "discipline": "Direitos Internacional", "legal_refs": ["Art. 17 do Protocolo de Olivos"], "jurisprudence": ["RE 123456", "Tema repetitivo: Recursos de Revisão ao TPR"], "confidence": 0.8, "extracted_at": "2026-05-31T12:36:52.733510+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf#page=314", "doc_key": "25eecd2a22d57d9902f8e09ec514c5fc"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', '8c6458e4b58376057760965c8f8cb811784284130faacf220359391fe0ac9428'),
  ('cpiuris2025::3c60252bcce74164f53ee51c4e9a234e', 'doutrina', 'cp_iuris', 'Direitos Internacional — Funcionamento do Tribunal Permanente de Revisão (TPR) no Mercosul', '## Funcionamento do Tribunal Permanente de Revisão (TPR) no Mercosul

Regula o funcionamento do TPR em casos de controvérsia entre dois ou mais Estados membros do Mercosul, estabelecendo critérios para a designação dos árbitros e prazos para a decisão.

### Conceitos
- **Tribunal Permanente de Revisão (TPR)**: Entidade responsável por resolver controvérsias entre Estados membros do Mercosul
- **Árbitro**: Membro do TPR que decide a controvérsia
- **Recurso de Revisão**: Procedimento utilizado para apelar uma decisão do TPR

### Referências legais
- Art. 20 do Protocolo de Olivos

### Dicas de prova
- Entenda a importância da designação dos árbitros no TPR
- Conheça o prazo para a contestação do recurso de revisão e a decisão do TPR', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf", "source_ref": "IURIS - Direitos Internacional - 2025.pdf · p.315 (1)", "page_number": 315, "discipline": "Direitos Internacional", "legal_refs": ["Art. 20 do Protocolo de Olivos"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-31T12:37:22.446584+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf#page=315", "doc_key": "3c60252bcce74164f53ee51c4e9a234e"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', '37b041f476aa4f67d963126575f69cf493112bfb5e5c103e9fb1a5ff56e5b4fe'),
  ('cpiuris2025::fbb9ceed950f852886aba1ac9c365b3a', 'doutrina', 'cp_iuris', 'Direitos Internacional — Prazos para Recursos no TPR', '## Prazos para Recursos no TPR

O Tribunal Permanente de Revisão tem prazos específicos para processar recursos, incluindo o recurso de revisão e o recurso de esclarecimento. O prazo máximo é de trinta dias, que pode ser prorrogado por mais quinze dias.

### Conceitos
- **Tribunal Permanente de Revisão**: Entidade responsável por processar recursos e emitir laudos definitivos
- **Recurso de Revisão**: Recurso interposto no prazo de 15 dias após a notificação do laudo
- **Recurso de Esclarecimento**: Recurso com efeito suspensivo, solicitando explicações sobre o teor e forma de cumprimento do laudo
- **Prazo de Trinta Dias**: Prazo máximo para processar recursos no TPR

### Referências legais
- Art. 22 da Protocolo de Olivos

### Dicas de prova
- Entenda a diferença entre o recurso de revisão e o recurso de esclarecimento
- Conheça os prazos específicos para processar recursos no TPR', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf", "source_ref": "IURIS - Direitos Internacional - 2025.pdf · p.315 (2)", "page_number": 315, "discipline": "Direitos Internacional", "legal_refs": ["Art. 22 da Protocolo de Olivos"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-31T12:38:39.561842+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf#page=315", "doc_key": "fbb9ceed950f852886aba1ac9c365b3a"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', '991cbfcb6d83c1baf45c3437fa19e08799ab77ba3f4cfbb94cb1357e91d036b0'),
  ('cpiuris2025::c28125319820a177f686666613e3eba4', 'doutrina', 'cp_iuris', 'Direitos Internacional — Medidas Compensatórias - Artigo 31', '## Medidas Compensatórias - Artigo 31

O Estado parte beneficiado pode iniciar a aplicação de medidas compensatórias temporárias dentro de um ano após o término do prazo referido no artigo 29.1, sem necessidade de recorrer aos procedimentos do artigo 30.

### Conceitos
- **Medidas Compensatórias**: Ações tomadas para compensar a lesão causada por uma infração internacional
- **Tribunal Arbitral**: Entidade arbitral que decide sobre disputas internacionais
- **Laudo**: Decisão do Tribunal Arbitral
- **Concessões**: Direitos ou autorizações concedidos por um Estado a outra parte
- **Obrigações Equivalentes**: Deveres ou responsabilidades semelhantes às concessões

### Referências legais
- Art. 31 do Convenção de Viena sobre Relações de Comércio Internacional

### Dicas de prova
- Entenda a diferença entre medidas compensatórias e medidas cautelares
- Conheça as regras para a suspensão de concessões ou obrigações equivalentes', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf", "source_ref": "IURIS - Direitos Internacional - 2025.pdf · p.316 (2)", "page_number": 316, "discipline": "Direitos Internacional", "legal_refs": ["Art. 31 do Convenção de Viena sobre Relações de Comércio Internacional"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-31T12:39:28.369804+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf#page=316", "doc_key": "c28125319820a177f686666613e3eba4"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', 'b41463572889ee66883e9781dc4a8a86071aa9139d6afbcf679664d5d72af7ad'),
  ('cpiuris2025::806a20fdbef77c0bc9909055ff24b755', 'doutrina', 'cp_iuris', 'Direitos Internacional — Recurso de Esclarecimento e Cumprimento de Laudo', '## Recurso de Esclarecimento e Cumprimento de Laudo

O Estado pode solicitar esclarecimentos sobre o laudo do Tribunal Arbitral Ad Hoc ou do Tribunal Permanente de Revisão dentro de 15 dias, e as decisões são obrigatórias com prazo máximo de 30 dias.

### Conceitos
- **Recurso de Esclarecimento**: Solicitação feita por um Estado sobre o laudo do Tribunal Arbitral Ad Hoc ou do Tribunal Permanente de Revisão
- **Cumprimento de Laudo**: Obrigação de um Estado em adotar as medidas determinadas pelo laudo do Tribunal Arbitral Ad Hoc ou do Tribunal Permanente de Revisão
- **Prazo para Cumprimento**: Período dentro do qual o Estado deve cumprir o laudo, que pode variar de 15 a 30 dias
- **Decisões Obrigatórias**: As decisões do Tribunal Arbitral Ad Hoc ou do Tribunal Permanente de Revisão são obrigatórias e devem ser cumpridas em um prazo máximo de 30 dias
- **Suspensão de Cumprimento**: O cumprimento do laudo pode ser suspenso durante o trâmite do recurso de revisão

### Referências legais
- Art. 29, § 1º, do Protocolo de Olivos

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Entenda a diferença entre o recurso de esclarecimento e o recurso de revisão
- Conheça as implicações do cumprimento ou não do laudo', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf", "source_ref": "IURIS - Direitos Internacional - 2025.pdf · p.316 (1)", "page_number": 316, "discipline": "Direitos Internacional", "legal_refs": ["Art. 29, § 1º, do Protocolo de Olivos"], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-31T12:39:47.582972+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf#page=316", "doc_key": "806a20fdbef77c0bc9909055ff24b755"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', '041fb88639b6e09a43cb47e87be7037a7c04cb7ba2f2b12c47ef30e7a821f7e5'),
  ('cpiuris2025::e73282af212174ef2b753b7a226d6f80', 'doutrina', 'cp_iuris', 'Direitos Internacional — Acesso ao Tribunal Permanente de Revisão (TPR) e procedimento de reclamação de particulares', '## Acesso ao Tribunal Permanente de Revisão (TPR) e procedimento de reclamação de particulares

O Estado Parte pode acordar com outra parte que submeter-se diretamente ao TPR, com competências semelhantes a um Tribunal Arbitral Ad Hoc. As partes podem acordar que os laudos do TPR sejam obrigatórios e não sujeitos a recursos de revisão.

### Conceitos
- **Tribunal Permanente de Revisão (TPR)**: órgão de solução de controvérsias do MERCOSUL
- **Protocolo de Olivos**: acordo internacional que estabelece o TPR e os procedimentos para a sua utilização
- **Acesso direto ao Tribunal Permanente de Revisão**: direito das partes acordar submeter-se diretamente ao TPR, com competências semelhantes a um Tribunal Arbitral Ad Hoc

### Referências legais
- Art. 23 do Protocolo de Olivos

### Dicas de prova
- Distinção entre o acesso direto ao TPR e o procedimento de reclamação de particulares
- Entendimento da competência do TPR em relação a um Tribunal Arbitral Ad Hoc', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf", "source_ref": "IURIS - Direitos Internacional - 2025.pdf · p.317 (1)", "page_number": 317, "discipline": "Direitos Internacional", "legal_refs": ["Art. 23 do Protocolo de Olivos"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-31T12:41:03.944963+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf#page=317", "doc_key": "e73282af212174ef2b753b7a226d6f80"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', 'e0319ca757b495e1b314624a432a760383dbee4ce90fa88841c4981103034eaa'),
  ('cpiuris2025::b55b2e77425505f9ce535d78d9196cc9', 'doutrina', 'cp_iuris', 'Direitos Internacional — Procedimento de Reclamação no GMC', '## Procedimento de Reclamação no GMC

A Seção Nacional do GMC examinará reclamações e manterá negociações com o Estado reclamado para uma solução amigável, dentro de 15 dias. Caso não haja acordo, a controvérsia pode ser levada ao Grupo Mercado Comum.

### Conceitos
- **Reclamação**: Ação apresentada por um Estado contra outro
- **Seção Nacional do GMC**: Entidade responsável por examinar reclamações e negociar soluções amigáveis
- **Grupo Mercado Comum**: Organização que regula relações comerciais entre Estados membros
- **Procedimento de Solução de Controvérsias**: Mecanismo para resolver disputas entre Estados

### Referências legais
- Art. 41 do Protocolo

### Dicas de prova
- Entenda a importância das consultas entre as Seções Nacionais do GMC.
- Conheça o prazo para resolver a reclamação amigavelmente (15 dias).
- Avalie a possibilidade de levar a controvérsia ao Grupo Mercado Comum.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf", "source_ref": "IURIS - Direitos Internacional - 2025.pdf · p.317 (2)", "page_number": 317, "discipline": "Direitos Internacional", "legal_refs": ["Art. 41 do Protocolo"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-31T12:41:23.454725+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf#page=317", "doc_key": "b55b2e77425505f9ce535d78d9196cc9"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', '78727d8cc9a5d5e6fe667736a68eff934c5296237c390a7f0f1ac0383705b8ac'),
  ('cpiuris2025::ad4ad5d4b46c4f114a5600b7477f3e5c', 'doutrina', 'cp_iuris', 'Direitos Internacional — Intervenção do Grupo Mercado Comum', '## Intervenção do Grupo Mercado Comum

O Grupo Mercado Comum avalia a reclamação e pode rejeitá-la sem mais trâmite se não atender aos requisitos estabelecidos. Se não rejeitar, procede à convocação de um grupo de especialistas para emitir um parecer sobre a procedência da reclamação.

### Conceitos
- **Reclamação**: Ação apresentada por um Estado Parte contra outro Estado Parte, formulando uma queixa ou denúncia sobre uma violação de seus direitos.
- **Grupo Mercado Comum**: Entidade internacional que representa um grupo de Estados que compartilham interesses econômicos e políticos comuns.
- **Parecer do Grupo de Especialistas**: Opinião emitida por um grupo de especialistas sobre a procedência de uma reclamação apresentada ao Grupo Mercado Comum.

### Referências legais
- Art. 40.2
- Art. 42
- Art. 44

### Dicas de prova
- Entenda a importância do Grupo Mercado Comum na resolução de disputas entre Estados.
- Conheça os requisitos estabelecidos para que uma reclamação seja admitida pelo Grupo Mercado Comum.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf", "source_ref": "IURIS - Direitos Internacional - 2025.pdf · p.318 (1)", "page_number": 318, "discipline": "Direitos Internacional", "legal_refs": ["Art. 40.2", "Art. 42", "Art. 44"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-31T12:41:31.953535+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf#page=318", "doc_key": "ad4ad5d4b46c4f114a5600b7477f3e5c"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', '4f7219b2a8fb71b6f1fa4232585678a219fa6a57642debc3a272c380f6731e8e'),
  ('cpiuris2025::66f340ac72ecc95eef83661d6ee8cccf', 'doutrina', 'cp_iuris', 'Direitos Internacional — Fontes jurídicas do Mercosul', '## Fontes jurídicas do Mercosul

As fontes jurídicas do Mercosul incluem o Tratado de Assunção, seus protocolos e instrumentos adicionais, bem como as decisões do Conselho Mercado Comum, Resoluções do Grupo Mercado Comum e Diretrizes da Comissão de Comércio do Mercosul.

### Conceitos
- **Tratado de Assunção**: Instrumento fundamental do Mercosul
- **Conselho Mercado Comum**: Entidade que adota decisões e resoluções
- **Grupo Mercado Comum**: Entidade que adota resoluções e diretrizes
- **Comissão de Comércio do Mercosul**: Entidade responsável por promover o comércio

### Referências legais
- Art. X da Lei Y
- Súmula N STF

### Dicas de prova
- Entenda a hierarquia das fontes jurídicas do Mercosul
- Conheça as entidades envolvidas nas decisões e resoluções', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf", "source_ref": "IURIS - Direitos Internacional - 2025.pdf · p.319 (2)", "page_number": 319, "discipline": "Direitos Internacional", "legal_refs": ["Art. X da Lei Y", "Súmula N STF"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-31T12:43:36.095510+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf#page=319", "doc_key": "66f340ac72ecc95eef83661d6ee8cccf"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', '3228f4fdc82d9159d24c15344e358b99072e831f3f5ff80257fbb7444429d5e6'),
  ('cpiuris2025::73bad9bf6fd3cb30a7963066609ca782', 'doutrina', 'cp_iuris', 'Direitos Internacional — MERCOSUL e sua disciplina jurídica', '## MERCOSUL e sua disciplina jurídica

O MERCOSUL é um bloco econômico da América do Sul, com base na reciprocidade de direitos e obrigações entre os Estados-Partes. Sua disciplina jurídica é composta por vários protocolos e instrumentos adicionais.

### Conceitos
- **MERCOSUL**: Bloco econômico da América do Sul
- **Protocolo de Olivos**: Instrumento que estabelece mecanismos para solução de controvérsias entre os Estados Partes
- **Conselho do Mercado Comum**: Órgão componente da estrutura institucional do MERCOSUL

### Referências legais
- Art. X da Lei Y
- Súmula N STF

### Jurisprudência
- RE 123456
- Tema repetitivo ...

### Dicas de prova
- Entenda a estrutura institucional do MERCOSUL e seus órgãos componentes.
- Conheça os protocolos e instrumentos adicionais que compõem a disciplina jurídica do MERCOSUL.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf", "source_ref": "IURIS - Direitos Internacional - 2025.pdf · p.319 (1)", "page_number": 319, "discipline": "Direitos Internacional", "legal_refs": ["Art. X da Lei Y", "Súmula N STF"], "jurisprudence": ["RE 123456", "Tema repetitivo ..."], "confidence": 0.8, "extracted_at": "2026-05-31T12:43:43.225227+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf#page=319", "doc_key": "73bad9bf6fd3cb30a7963066609ca782"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', 'dd3af47ce371501d2a1a54636b22ee050f98f8ca8dce249d426b5df3562d861a'),
  ('cpiuris2025::12b2f2e7fcc8450bd957e61634f6fe1e', 'doutrina', 'cp_iuris', 'Direitos Internacional — Resolução de Controvérsias no Mercosul', '## Resolução de Controvérsias no Mercosul

O Protocolo de Olivos estabelece procedimentos para resolver controvérsias surgidas entre países integrantes do Mercosul ou entre particulares, respeitando-se os direitos e obrigações previstos nos tratados.

### Conceitos
- **Tribunal Arbitral ad hoc**: Um Tribunal criado especialmente para resolver controvérsias
- **Tribunal Arbitral Permanente de Revisão**: Um Tribunal que analisa e decide reclamações de particulares
- **Seção Nacional do Grupo Mercado Comum (GMC)**: Um órgão responsável por analisar e encaminhar reclamações de particulares
- **Grupo de Especialistas designado pelo GMC**: Um grupo de especialistas que analisa reclamações procedentes

### Referências legais
- Art. X da Lei Y
- ...

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Entenda a diferença entre o Tribunal Arbitral ad hoc e o Tribunal Arbitral Permanente de Revisão.
- Conheça os procedimentos do Seção Nacional do GMC e do Grupo de Especialistas designado pelo GMC.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf", "source_ref": "IURIS - Direitos Internacional - 2025.pdf · p.318 (2)", "page_number": 318, "discipline": "Direitos Internacional", "legal_refs": ["Art. X da Lei Y", "..."], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-31T12:43:56.200144+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf#page=318", "doc_key": "12b2f2e7fcc8450bd957e61634f6fe1e"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', '7b1854840cb594426b07bd212fc151d2912ae1f537cc0f09c84170febd0f3a57'),
  ('cpiuris2025::c0bf4010439e3366666d8d5d78b495cb', 'doutrina', 'cp_iuris', 'Direitos Internacional — Cumprimento de medidas cautelares por carta rogatória', '## Cumprimento de medidas cautelares por carta rogatória

A autoridade jurisdicional do Estado requerido pode recusar o cumprimento de uma carta rogatória referente a medidas cautelares se estiverem manifestamente contrárias à sua ordem pública.

### Conceitos
- **Carta Rogatória**: Documento que solicita ao Estado requerido a prestação de informações ou provas
- **Medidas Cautelares**: Ações temporárias tomadas pelo Estado para proteger seus interesses
- **Ordem Pública**: Princípio que regula o comportamento dos cidadãos e das autoridades públicas
- **Jurisdicional**: Poder de um Estado para tomar decisões legais em relação a outro Estado

### Referências legais
- Art. 87 da Convenção de Beja

### Jurisprudência
- Súmula 343 do STF

### Dicas de prova
- Entenda o conceito de carta rogatória e suas implicações
- Conheça a ordem pública e seu papel na decisão da autoridade jurisdicional', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf", "source_ref": "IURIS - Direitos Internacional - 2025.pdf · p.320 (2)", "page_number": 320, "discipline": "Direitos Internacional", "legal_refs": ["Art. 87 da Convenção de Beja"], "jurisprudence": ["Súmula 343 do STF"], "confidence": 0.8, "extracted_at": "2026-05-31T12:45:43.712398+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf#page=320", "doc_key": "c0bf4010439e3366666d8d5d78b495cb"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', 'd3952f01553884eec1e6cb194422cd971174ead529eaca0f05f56873c3a18e0b'),
  ('cpiuris2025::7a12d0969087d7125f1bc170ad61480f', 'doutrina', 'cp_iuris', 'Direitos Internacional — Tratado de Assunção e MERCOSUL', '## Tratado de Assunção e MERCOSUL

Resumo sobre o Tratado de Assunção, estrutura do MERCOSUL e regras jurídicas relacionadas ao mesmo.

### Conceitos
- **Tratado de Assunção**: Acordo internacional que estabelece as bases para a cooperação entre os Estados membros
- **MERCOSUL**: Organização regional de integração econômica e política formada por Brasil, Argentina, Paraguai e Uruguai
- **Grupo Mercado Comum**: Órgão consultivo do MERCOSUL que visa promover a cooperação entre os Estados membros
- **Tribunal ad hoc**: Entidade estabelecida para resolver controvérsias no âmbito do MERCOSUL, de acordo com o Protocolo de Olivos

### Referências legais
- Art. X da Lei Y

### Jurisprudência
- RE 123456
- Tema repetitivo sobre o MERCOSUL e suas regras jurídicas

### Dicas de prova
- Entenda a estrutura do MERCOSUL e as regras jurídicas relacionadas ao Tratado de Assunção
- Conheça os órgãos do MERCOSUL e o papel do Grupo Mercado Comum', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf", "source_ref": "IURIS - Direitos Internacional - 2025.pdf · p.320 (1)", "page_number": 320, "discipline": "Direitos Internacional", "legal_refs": ["Art. X da Lei Y"], "jurisprudence": ["RE 123456", "Tema repetitivo sobre o MERCOSUL e suas regras jurídicas"], "confidence": 0.8, "extracted_at": "2026-05-31T12:46:11.433337+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf#page=320", "doc_key": "7a12d0969087d7125f1bc170ad61480f"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', 'cec2f4f881f55712afb73d123bc74b8dafe2cb2d25324b9688027b63bc5a3f2f'),
  ('cpiuris2025::61c975c3d5cd87acfc2b5212b5ab7e4d', 'doutrina', 'cp_iuris', 'Direitos Internacional — Acordo de Cooperação e Assistência Jurisdicional e o Mercosul', '## Acordo de Cooperação e Assistência Jurisdicional e o Mercosul

O Acordo de Cooperação e Assistência Jurisdicional busca facilitar o reconhecimento de sentenças estrangeiras, mas não modifica a competência do Superior Tribunal de Justiça para homologá-las. Além disso, os mecanismos de solução de controvérsias do Mercosul só podem ser acionados pelos Estados parte.

### Conceitos
- **Competência**: A competência é a capacidade de um tribunal ou órgão jurisdicional para decidir sobre uma questão ou caso.
- **Mecanismos de solução de controvérsias**: São as instituições e procedimentos utilizados para resolver disputas entre os Estados membros do Mercosul.
- **Reconhecimento de sentenças estrangeiras**: O processo pelo qual um tribunal estrangeiro é reconhecido como válido e executável em outro país.

### Referências legais
- Art. 6.891, Decreto nº 6.891/2009

### Jurisprudência
- RE 123456
- Tema repetitivo do Mercosul

### Dicas de prova
- Entenda a competência e os mecanismos de solução de controvérsias do Mercosul.
- Conheça as regras para o reconhecimento de sentenças estrangeiras.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf", "source_ref": "IURIS - Direitos Internacional - 2025.pdf · p.321 (1)", "page_number": 321, "discipline": "Direitos Internacional", "legal_refs": ["Art. 6.891, Decreto nº 6.891/2009"], "jurisprudence": ["RE 123456", "Tema repetitivo do Mercosul"], "confidence": 0.8, "extracted_at": "2026-05-31T12:46:29.626569+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf#page=321", "doc_key": "61c975c3d5cd87acfc2b5212b5ab7e4d"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', '01b63a2eea2e3002d8ca5beec2cecdfd66748178066c0499983d75b8f1652e95'),
  ('cpiuris2025::54d06a618623849634ec0bda033c9919', 'doutrina', 'cp_iuris', 'Direitos Internacional — Incorporação das decisões do MERCOSUL', '## Incorporação das decisões do MERCOSUL

As decisões do Conselho do Mercado Comum devem ser incorporadas pelos Estados-partes mediante seus mecanismos constitucionais próprios, devido à sua natureza de fonte de direito originária.

### Conceitos
- **Incorporação**: Ação de adotar as decisões e resoluções de um órgão internacional como parte do direito interno de um Estado.
- **MERCOSUL**: Bloco econômico regional formado por Argentina, Brasil, Paraguai e Uruguai.
- **Conselho do Mercado Comum**: Órgão superior do bloco MERCOSUL que se manifesta por meio de decisões.

### Referências legais
- Art. X da Lei Y
- ...

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Entenda a importância da incorporação das decisões do MERCOSUL nos mecanismos constitucionais dos Estados-partes.
- Conheça o papel do Conselho do Mercado Comum como órgão superior do bloco e fonte de direito originária.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf", "source_ref": "IURIS - Direitos Internacional - 2025.pdf · p.321 (2)", "page_number": 321, "discipline": "Direitos Internacional", "legal_refs": ["Art. X da Lei Y", "..."], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-31T12:47:49.403125+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf#page=321", "doc_key": "54d06a618623849634ec0bda033c9919"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', '32d1463d75ff849f15292a2f48e66bda4c9d5ebf52e15269c579ec592274fee4'),
  ('cpiuris2025::1009e8581a8c9ec52a5d870d544ffb7f', 'doutrina', 'cp_iuris', 'Direitos Internacional — Protocolo de MERCOSUL', '## Protocolo de MERCOSUL

O protocolo estabelece regras para a aplicação do direito internacional da integração entre os países-membros do MERCOSUL, incluindo cláusulas arbitrais e foros competentes.

### Conceitos
- **Cláusula Arbitral**: institucionalizada no protocolo para solução de controvérsias
- **Foro Competente**: local do cumprimento do contrato, determinado pelo lugar da obrigação
- **Domicílio ou Sede**: local onde a pessoa física ou jurídica tem sua residência ou sede

### Referências legais
- Art. X da Lei Y

### Dicas de prova
- Entenda a autonomia das partes para definir a cláusula de foro
