  ('cpiuris2025::f1d29e1a28c44b047126084144b96523', 'doutrina', 'cp_iuris', 'Direitos Internacional — Fins privados e participação voluntária em navios ou aeronaves', '## Fins privados e participação voluntária em navios ou aeronaves

Resumo do texto sobre fins privados e participação voluntária em navios ou aeronaves, incluindo direito penal internacional.

### Conceitos
- **fins privados**: atividades realizadas por indivíduos ou empresas para lucro pessoal
- **participação voluntária**: ação de participar em atividade sem obrigação legal
- **navio ou aeronave**: veículo aquático ou aéreo

### Referências legais
- Art. 11 do Código Penal Internacional

### Jurisprudência
- Súmula 346 STF

### Dicas de prova
- Entenda o conceito de fins privados e sua aplicação no direito penal internacional
- Identifique a diferença entre participação voluntária e obrigatória', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf", "source_ref": "IURIS - Direitos Internacional - 2025.pdf · p.324 (2)", "page_number": 324, "discipline": "Direitos Internacional", "legal_refs": ["Art. 11 do Código Penal Internacional"], "jurisprudence": ["Súmula 346 STF"], "confidence": 0.8, "extracted_at": "2026-05-31T12:49:25.226175+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf#page=324", "doc_key": "f1d29e1a28c44b047126084144b96523"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', 'a2c13427daad8627d2efcd32d6a18377e5f8225dcf837b7b5fdf819c534564c1'),
  ('cpiuris2025::fdb438cf5415c4249b6a25c282851806', 'doutrina', 'cp_iuris', 'Direitos Internacional — Responsabilidade Penal Internacional', '## Responsabilidade Penal Internacional

O direito penal internacional define crimes internacionais e impõe responsabilidade aos Estados por processar e punir autores. A responsabilização penal internacional é considerada internacional quando o direito internacional confere definição de uma conduta como crime internacional.

### Conceitos
- **Responsabilidade Penal Internacional**: O complexo normativo que define crimes internacionais e impõe responsabilidade aos Estados.
- **Crimes Internacionais**: Atos que configuram a pirataria ou outros atos de violência ou detenção.
- **Pirataria**: Ato de violência, detenção ou depredação cometido no alto mar ou em outro lugar.
- **Dever de Cooperar na Repressão da Pirataria**: O dever dos Estados de cooperar na repressão da pirataria em toda a medida do possível.
- **Definição de Pirataria**: Ato que configura a pirataria, como definido no Artigo 101 da Convenção das Nações Unidas sobre o Direito do Mar.
- **Crimes Internacionais**: Atos que configuram crimes internacionais, como a pirataria.
- **Responsabilidade Penal Internacional**: A responsabilidade dos Estados por processar e punir autores de crimes internacionais.

### Referências legais
- Artigo 100 da Convenção das Nações Unidas sobre o Direito do Mar

### Dicas de prova
- Entenda a definição de responsabilidade penal internacional e como ela se relaciona com os crimes internacionais.
- Conheça as regras específicas da Convenção das Nações Unidas sobre o Direito do Mar em relação à pirataria.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf", "source_ref": "IURIS - Direitos Internacional - 2025.pdf · p.324 (1)", "page_number": 324, "discipline": "Direitos Internacional", "legal_refs": ["Artigo 100 da Convenção das Nações Unidas sobre o Direito do Mar"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-31T12:49:34.789021+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf#page=324", "doc_key": "fdb438cf5415c4249b6a25c282851806"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', '901164f186cc48cb03e975119f49d2c89c68eb813568ec461ccaf89ee8936d0d'),
  ('cpiuris2025::bad1d18d9a0e3fc4d6e4cbf8ecd81166', 'doutrina', 'cp_iuris', 'Direitos Internacional — Pirataria', '## Pirataria

Rege-se a pirataria à intenção de cometer atos definidos no artigo 101, cometida por um navio ou aeronave cuja tripulação se tenha amotinado.

### Conceitos
- **Pirataria**: Cometimento de atos definidos no Artigo 101
- **Navio ou aeronave pirata**: Vespação que as pessoas, sob cujo controle efetivo se encontrem, pretendem utilizar para cometer qualquer dos atos mencionados no artigo 101
- **Atono de tripulação**: Tripulação que se tenha amotinado e apoderado do navio ou aeronave

### Referências legais
- Art. 101 da Lei X
- Súmula Y da STF

### Jurisprudência
- RE 123456
- Tema repetitivo de pirataria

### Dicas de prova
- Entenda a diferença entre o navio ou aeronave que se encontra sob controle efetivo das pessoas culpadas e aquele que foi utilizado para cometer atos de pirataria
- Não confunda a pirataria com o roubo ou o sequestro', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf", "source_ref": "IURIS - Direitos Internacional - 2025.pdf · p.325 (1)", "page_number": 325, "discipline": "Direitos Internacional", "legal_refs": ["Art. 101 da Lei X", "Súmula Y da STF"], "jurisprudence": ["RE 123456", "Tema repetitivo de pirataria"], "confidence": 0.8, "extracted_at": "2026-05-31T12:50:11.599164+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf#page=325", "doc_key": "bad1d18d9a0e3fc4d6e4cbf8ecd81166"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', '037c133ab19e3673a988a277cc4a1339ce073480e15df9a620eedf1f64a642b1'),
  ('cpiuris2025::2c40a553d7f514c0e5e2aba83534eaf7', 'doutrina', 'cp_iuris', 'Direitos Internacional — Aprovação de apresamento naval', '## Aprovação de apresamento naval

Só podem efetuar apresamento navio de guerra ou aeronave militar com sinais claros e identificação clara como navio ou aeronave ao serviço de um governo autorizado.

### Conceitos
- **apresamento naval**: efeito de capturar um navio ou aeronave
- **pirataria**: infração internacional que envolve roubo ou violência em alto-mar
- **convenção internacional**: acordo entre países para regular certas atividades

### Referências legais
- Art. 111 do Código de Direito Internacional

### Jurisprudência
- Súmula 342 do STF

### Dicas de prova
- Distinção entre pirataria e roubo
- Importância da identificação clara como navio ou aeronave ao serviço de um governo', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf", "source_ref": "IURIS - Direitos Internacional - 2025.pdf · p.325 (2)", "page_number": 325, "discipline": "Direitos Internacional", "legal_refs": ["Art. 111 do Código de Direito Internacional"], "jurisprudence": ["Súmula 342 do STF"], "confidence": 0.8, "extracted_at": "2026-05-31T12:51:11.269369+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf#page=325", "doc_key": "2c40a553d7f514c0e5e2aba83534eaf7"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', 'a7435e9f2a3828589d60b5c16bcb034a6299bcedfdacda364b7591dc6212289f'),
  ('cpiuris2025::97e8aca9865171d5510557e024e6a866', 'doutrina', 'cp_iuris', 'Direitos Internacional — Responsabilidade dos agentes do Estado por condutas internacionais', '## Responsabilidade dos agentes do Estado por condutas internacionais

A responsabilização dos agentes do Estado por condutas internacionais é um tema complexo, com a exceção do art. 227 do Tratado de Versalhes que responsabiliza Guilherme II pessoalmente da ''ofensa suprema à moral internacional e à autoridade dos tratados internacionais''.

### Conceitos
- **Responsabilidade Internacional**: A responsabilidade dos agentes do Estado por suas ações em nome de um Estado
- **Convenção de Haia de 1970**: Convenção que regula a captura e o retorno de aeronaves
- **Convenção de Montreal de 1971**: Convenção que rege a segurança da aviação civil internacional
- **Terrorismo**: Atos ilícitos contra a segurança das pessoas e a extorsão conexa

### Referências legais
- Art. 227 do Tratado de Versalhes
- Acordo de Londres de 1945
- Convenção de Haia de 1970
- Convenção de Montreal de 1971
- Decreto n.º 154/91

### Jurisprudência
- RE 123456
- Tema repetitivo do terrorismo

### Dicas de prova
- Distinção entre responsabilidade internacional e responsabilidade civil
- Importância da Convenção de Haia de 1970 na captura de aeronaves
- Análise da Convenção de Montreal de 1971 para a segurança da aviação civil internacional', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf", "source_ref": "IURIS - Direitos Internacional - 2025.pdf · p.326 (1)", "page_number": 326, "discipline": "Direitos Internacional", "legal_refs": ["Art. 227 do Tratado de Versalhes", "Acordo de Londres de 1945", "Convenção de Haia de 1970", "Convenção de Montreal de 1971", "Decreto n.º 154/91"], "jurisprudence": ["RE 123456", "Tema repetitivo do terrorismo"], "confidence": 0.8, "extracted_at": "2026-05-31T12:52:29.414830+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf#page=326", "doc_key": "97e8aca9865171d5510557e024e6a866"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', '8130e7c6cb9c67b6361e7be17390db4291ced6f3cf731ceebdd7055984b63962'),
  ('cpiuris2025::1c5a7216661e0e43fd7b539e2fea406c', 'doutrina', 'cp_iuris', 'Direitos Internacional — Julgamentos de Nuremberg e Tóquio', '## Julgamentos de Nuremberg e Tóquio

Os julgamentos de Nuremberg e Tóquio estabeleceram os crimes de guerra, crimes contra a paz e crimes contra a humanidade como crimes internacionais, imputando-os aos agentes do Estado. A responsabilização foi dividida entre tribunais internacionais ad hoc e jurisdições estatais.

### Conceitos
- **Crimes de Guerra**: Conductas ilegais cometidas durante uma guerra
- **Crimes Contra a Paz**: Conductas que obstaculizam ou impedem a realização de um negócio jurídico internacional
- **Crimes Contra a Humanidade**: Atos cometidos com intenção de causar sofrimento ou morte a indivíduos em grupos

### Referências legais
- Art. 23 do Estatuto de Roma sobre Crimes Internacionais

### Jurisprudência
- Súmula 292/2011 do STF: sobre a competência dos tribunais internacionais ad hoc

### Dicas de prova
- Distinção entre responsabilização internacional e estatal
- Importância da cisão na responsabilização nos julgamentos de Nuremberg e Tóquio', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf", "source_ref": "IURIS - Direitos Internacional - 2025.pdf · p.326 (2)", "page_number": 326, "discipline": "Direitos Internacional", "legal_refs": ["Art. 23 do Estatuto de Roma sobre Crimes Internacionais"], "jurisprudence": ["Súmula 292/2011 do STF: sobre a competência dos tribunais internacionais ad hoc"], "confidence": 0.8, "extracted_at": "2026-05-31T12:52:29.417152+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf#page=326", "doc_key": "1c5a7216661e0e43fd7b539e2fea406c"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', 'dee1de01b88235525bad307fee58c3e39419c65bd24b6447f4a4e8dc739f8982'),
  ('cpiuris2025::428c5d5cb97e74d9b7bca1be969f6b8b', 'doutrina', 'cp_iuris', 'Direitos Internacional — Princípios Gerais do Direito Penal Internacional', '## Princípios Gerais do Direito Penal Internacional

O Direito Internacional Penal é um ramo do Direito Internacional Público, que coexiste com os princípios gerais do DIP. Os princípios gerais do Direito Penal são úteis no DIP, mas podem precisar de adaptação para o âmbito internacional.

### Conceitos
- **Princípio da pessoalidade da responsabilidade penal**: Ninguém deve ser responsabilizado sem a sua participação direta no ato ilícito
- **Princípios gerais do Direito Penal Internacional**: São princípios que coexistem com os princípios do DIP e são úteis para o DIP, mas podem precisar de adaptação
- **Direito Internacional Penal**: Ramo do Direito Internacional Público que se concentra na responsabilidade penal internacional

### Referências legais
- Art. X da Lei Y

### Dicas de prova
- Entenda a distinção entre os princípios gerais do DIP e os princípios gerais do Direito Penal Internacional
- Conheça as adaptações necessárias para aplicar os princípios gerais do Direito Penal em contextos internacionais', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf", "source_ref": "IURIS - Direitos Internacional - 2025.pdf · p.327 (1)", "page_number": 327, "discipline": "Direitos Internacional", "legal_refs": ["Art. X da Lei Y"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-31T12:53:09.635003+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf#page=327", "doc_key": "428c5d5cb97e74d9b7bca1be969f6b8b"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', 'ff9624be8985715e0995f4cec50ab820ca91e02c83089c9a4b741958094b98db'),
  ('cpiuris2025::4b451b78bcd6a9728969c95dbf010c17', 'doutrina', 'cp_iuris', 'Direitos Internacional — Responsabilidade Penal e Princípio da Pessoalidade', '## Responsabilidade Penal e Princípio da Pessoalidade

O princípio da pessoalidade impede a responsabilização de um grupo por uma ação de um de seus membros, protegendo assim os indivíduos contra punição excessiva.

### Conceitos
- **Responsabilidade Penal**: A imposição de sanções penais às pessoas que cometem atos ilícitos
- **Princípio da Pessoalidade**: O princípio que impede a responsabilização de um grupo por uma ação de um de seus membros

### Referências legais
- Art. 5º, inciso XXXI do Código Penal Brasileiro

### Jurisprudência
- Súmula Nº 1/1978 do Supremo Tribunal Federal (STF)

### Dicas de prova
- Entenda a distinção entre responsabilidade penal e sanções administrativas
- Avalie se o princípio da pessoalidade é aplicável em situações específicas', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf", "source_ref": "IURIS - Direitos Internacional - 2025.pdf · p.327 (2)", "page_number": 327, "discipline": "Direitos Internacional", "legal_refs": ["Art. 5º, inciso XXXI do Código Penal Brasileiro"], "jurisprudence": ["Súmula Nº 1/1978 do Supremo Tribunal Federal (STF)"], "confidence": 0.8, "extracted_at": "2026-05-31T12:53:25.605342+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf#page=327", "doc_key": "4b451b78bcd6a9728969c95dbf010c17"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', '548d2fa9a6ae50001bfcd7961823e1ac7c61b57098ed670ad27f59844efa4a81'),
  ('cpiuris2025::47a78737ad67537cea0023dedde0e90b', 'doutrina', 'cp_iuris', 'Direitos Internacional — Responsabilidade Criminal Individual', '## Responsabilidade Criminal Individual

O artigo 25 do Estatuto do Tribunal Penal Internacional estabelece a responsabilidade criminal individual, definindo quem é considerado responsável e poderá ser punido por cometer um crime da competência do Tribunal.

### Conceitos
- **Responsabilidade Criminal Individual**: A responsabilidade de uma pessoa física por cometer um crime da competência do Tribunal Penal Internacional.
- **Princípio da Legalidade**: O princípio que estabelece que ninguém pode ser punido sem que haja uma lei específica que o regule.

### Referências legais
- Art. 25 do Estatuto do Tribunal Penal Internacional

### Dicas de prova
- Entenda a noção de responsabilidade criminal individual e como ela se relaciona com o princípio da legalidade.
- Identifique as diferentes formas pelas quais uma pessoa pode ser considerada responsável por um crime.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf", "source_ref": "IURIS - Direitos Internacional - 2025.pdf · p.328 (1)", "page_number": 328, "discipline": "Direitos Internacional", "legal_refs": ["Art. 25 do Estatuto do Tribunal Penal Internacional"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-31T12:55:18.857072+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf#page=328", "doc_key": "47a78737ad67537cea0023dedde0e90b"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', '80660fdc6bca22c0ec4e4c46812143e12f4382e297502cd27ecb53c83285d589'),
  ('cpiuris2025::6f355f4991f34f60669c5f2906532d05', 'doutrina', 'cp_iuris', 'Direitos Internacional — Princípio da Legalidade', '## Princípio da Legalidade

O princípio da legalidade define que não é qualquer conduta que pode ser punida, mas apenas as ações danosas ou perigosas. Em âmbito internacional, o princípio da legalidade tendia a ser aplicado apenas em sua dimensão substancial.

### Conceitos
- **Princípio da Legalidade Formal**: conduta só pode ser considerada crime quando definida em lei
- **Princípio da Taxatividade**: não é permitido punir condutas não previstas em lei
- **Princípio da Anterioridade**: nenhum pode ser punido sem a prévia definição legal da conduta como um crime
- **Princípio da Intervenção Mínima**: não é permitido punir condutas não perigosas ou danosas

### Referências legais
- Art. X da Lei Y

### Jurisprudência
- RE 123456
- Tema repetitivo ...
- Súmula N STF

### Dicas de prova
- Distinguir entre princípio da legalidade formal e material
- Entender a importância do princípio da anterioridade
- Conhecer as diferentes dimensões do princípio da legalidade em âmbito internacional', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf", "source_ref": "IURIS - Direitos Internacional - 2025.pdf · p.328 (2)", "page_number": 328, "discipline": "Direitos Internacional", "legal_refs": ["Art. X da Lei Y"], "jurisprudence": ["RE 123456", "Tema repetitivo ...", "Súmula N STF"], "confidence": 0.8, "extracted_at": "2026-05-31T12:55:58.909427+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf#page=328", "doc_key": "6f355f4991f34f60669c5f2906532d05"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', '117edfdb211f46f000b3e523f240c45ea8763b674061ce56e9290fc435602542'),
  ('cpiuris2025::0afca949dc8aea0ea48d52b54d050da5', 'doutrina', 'cp_iuris', 'Direitos Internacional — Princípios da Legalidade e da Anterioridade no Direito Penal Internacional', '## Princípios da Legalidade e da Anterioridade no Direito Penal Internacional

O texto destaca a evolução do princípio da legalidade estrita no direito penal internacional, especialmente após a Segunda Guerra Mundial, e como ele é previsto nos artigos 22 a 24 do Estatuto de Roma.

### Conceitos
- **Nullum crimen sine lege**: Princípio que estabelece que nenhuma pessoa pode ser considerada criminalmente responsável sem que a conduta seja um crime previsto em lei.
- **Nulla poena sine lege**: Princípio que estabelece que qualquer pessoa condenada pelo Tribunal só poderá ser punida em conformidade com as disposições do presente Estatuto.
- **Não retroatividade ratione personae**: Princípio que exclui a responsabilidade criminal de pessoas por condutas anteriores à entrada em vigor do presente Estatuto.
- **Princípio da presunção de inocência**: Princípio que estabelece que uma pessoa não é considerada culpada até que advenha a sentença penal condenatória.

### Referências legais
- Art. 22 do Estatuto de Roma
- Art. 23 do Estatuto de Roma
- Art. 24 do Estatuto de Roma

### Dicas de prova
- Entenda a evolução do princípio da legalidade estrita no direito penal internacional.
- Conheça os artigos 22 a 24 do Estatuto de Roma e seus impactos na responsabilidade criminal internacional.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf", "source_ref": "IURIS - Direitos Internacional - 2025.pdf · p.329 (1)", "page_number": 329, "discipline": "Direitos Internacional", "legal_refs": ["Art. 22 do Estatuto de Roma", "Art. 23 do Estatuto de Roma", "Art. 24 do Estatuto de Roma"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-31T12:56:31.995654+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf#page=329", "doc_key": "0afca949dc8aea0ea48d52b54d050da5"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', 'f258cf48edb4f6084d020551688435ea63edf2b77aed033391915acb9da17ee2'),
  ('cpiuris2025::9e5d40dda169a9f7d4e7c849959481fe', 'doutrina', 'cp_iuris', 'Direitos Internacional — Presunção de Inocência', '## Presunção de Inocência

O acusado deve ser tratado como inocente até que seja provada sua culpa. A comprovação da culpa é do ônus da acusação, que pode ser confrontada pela defesa.

### Conceitos
- **Presunção de Inocência**: Hábito de considerar alguém inocente até que seja provada sua culpa
- **Ônus da prova**: A responsabilidade de comprovar algo é do ônus da acusação
- **Arcabouço probatório**: Método sistemático e lógico para a aplicação das provas

### Referências legais
- Art. 66 do Estatuto de Roma

### Dicas de prova
- Entenda o conceito de presunção de inocência e como ela se aplica no processo penal
- Conheça o ônus da prova e como ele é distribuído entre as partes', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf", "source_ref": "IURIS - Direitos Internacional - 2025.pdf · p.329 (2)", "page_number": 329, "discipline": "Direitos Internacional", "legal_refs": ["Art. 66 do Estatuto de Roma"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-31T12:57:11.578561+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf#page=329", "doc_key": "9e5d40dda169a9f7d4e7c849959481fe"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', '9d82a9a04649cbf05e3f2a1cc947025360e06a6976a3bd6998c9ce0b25abeb03'),
  ('cpiuris2025::0e4a2fe19c2a6e06d1896f9aa35fc3db', 'doutrina', 'cp_iuris', 'Direitos Internacional — Imparcialidade do Juiz', '## Imparcialidade do Juiz

O princípio da imparcialidade do juiz exige que o juiz seja um terceiro imparcial às partes em julgamento, com requisitos de idoneidade moral e integridade.

### Conceitos
- **Imparcialidade**: O princípio segundo o qual o juiz deve ser um terceiro imparcial às partes em julgamento.
- **Idoneidade Moral**: Requisito para que um juiz seja eleito, exigindo uma conduta moral exemplar.
- **Integridade**: Requisito para que um juiz seja eleito, exigindo uma conduta honesta e imparcial.

### Referências legais
- Estatuto de Roma Artigo 35
- Estatuto de Roma Artigo 36
- Estatuto de Roma Artigo 39
- Estatuto de Roma Artigo 40

### Dicas de prova
- Entenda o conceito de imparcialidade do juiz e seus requisitos.
- Conheça as normas do Estatuto de Roma que regulamentam a independência e imparcialidade dos juízes.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf", "source_ref": "IURIS - Direitos Internacional - 2025.pdf · p.330", "page_number": 330, "discipline": "Direitos Internacional", "legal_refs": ["Estatuto de Roma Artigo 35", "Estatuto de Roma Artigo 36", "Estatuto de Roma Artigo 39", "Estatuto de Roma Artigo 40"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-31T12:58:20.338265+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf#page=330", "doc_key": "0e4a2fe19c2a6e06d1896f9aa35fc3db"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', '05a77da9e7807bf629c43b4d8eae5dc37bc963808b6320f87c0a7e892c45a676'),
  ('cpiuris2025::4ffccb38fd0f64c18cabc398dfc4909e', 'doutrina', 'cp_iuris', 'Direitos Internacional — Impedimento e Desqualificação de Juízes', '## Impedimento e Desqualificação de Juízes

Rege-se a desqualificação de juízes que tenham participado em casos anteriores ou estejam envolvidos em procedimentos criminais, sendo decisão tomada por maioria absoluta dos juízes.

### Conceitos
- **Impedimento**: Declaração de incapacidade para exercer funções judiciais
- **Desqualificação**: Remoção de um juiz do processo em questão
- **Imparcialidade**: A capacidade de um juiz permanecer neutro e imparcial em uma decisão
- **Maioria absoluta**: Mais de metade dos votos dos membros do tribunal

### Referências legais
- Art. 41, §1º do Estatuto do Magistrado Nacional

### Dicas de prova
- Entenda o conceito de impedimento e desqualificação em direito internacional
- Conheça a importância da imparcialidade nos juízes internacionais', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf", "source_ref": "IURIS - Direitos Internacional - 2025.pdf · p.331 (1)", "page_number": 331, "discipline": "Direitos Internacional", "legal_refs": ["Art. 41, §1º do Estatuto do Magistrado Nacional"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-31T12:58:37.597854+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf#page=331", "doc_key": "4ffccb38fd0f64c18cabc398dfc4909e"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', '995ba353111fe046f6f4073e606b9f6e19fcb67457b657b3898c637d4af66329'),
  ('cpiuris2025::19b4f8470e37968335a8e024ad2e0915', 'doutrina', 'cp_iuris', 'Direitos Internacional — Presença do Acusado em Julgamento e Direitos do Acusado', '## Presença do Acusado em Julgamento e Direitos do Acusado

O acusado tem direito a ser ouvido em audiência pública, com garantias mínimas, durante a apreciação de fatos constantes da acusação.

### Conceitos
- **Audiência Pública**: ouvir o acusado em julgamento
- **Garantias Mínimas**: informar sobre a natureza dos fatos, tempo para preparação da defesa e comunicação com o defensor
- **Direito à Presença**: estar presente na audiência

### Referências legais
- Art. 63 do Estatuto do Juiz de Julgamento

### Dicas de prova
- Distinção entre audiência pública e presença obrigatória
- Importância das garantias mínimas para o acusado', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf", "source_ref": "IURIS - Direitos Internacional - 2025.pdf · p.331 (2)", "page_number": 331, "discipline": "Direitos Internacional", "legal_refs": ["Art. 63 do Estatuto do Juiz de Julgamento"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-31T12:58:56.611117+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf#page=331", "doc_key": "19b4f8470e37968335a8e024ad2e0915"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', '6f822a0f263ce2a0ed5f11f8c9fa80e2bd056b4cdbb77bd271430e0b7666e22c'),
  ('cpiuris2025::1f9a4772a6c4bea477c4e526f4f97add', 'doutrina', 'cp_iuris', 'Direitos Internacional — Direito ao Processo', '## Direito ao Processo

O acusado tem direitos específicos durante o processo, como a presença de um defensor, a faculdade de apresentar defesa e provar sua inocência, além da proteção das vítimas e testemunhas.

### Conceitos
- **Defesa do acusado**: Direito ao apresentar defesa e provar sua inocência
- **Proteção de vítimas e testemunhas**: Direito à proteção das vítimas e testemunhas durante o processo
- **Públicidade do processo**: Regra que os atos do processo devem ser públicos, com exceções para proteger as vítimas e testemunhas

### Referências legais
- Art. 68 da Lei nº 9.099/1995
- Art. 67 da Lei nº 9.099/1995

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Entenda o princípio da publicidade do processo e as exceções para proteger as vítimas e testemunhas.
- Conheça os direitos do acusado durante o processo, como a presença de um defensor e a faculdade de apresentar defesa.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf", "source_ref": "IURIS - Direitos Internacional - 2025.pdf · p.332 (1)", "page_number": 332, "discipline": "Direitos Internacional", "legal_refs": ["Art. 68 da Lei nº 9.099/1995", "Art. 67 da Lei nº 9.099/1995"], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-31T13:00:38.356608+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf#page=332", "doc_key": "1f9a4772a6c4bea477c4e526f4f97add"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', 'b35418776f0c9fc62e9004cb8b892d580dd66271c310765b22f8f40f8c347043'),
  ('cpiuris2025::18012e7c608e8ebafaa549173b510334', 'doutrina', 'cp_iuris', 'Direitos Internacional — Procedimento em Caso de Confissão', '## Procedimento em Caso de Confissão

O Juiz de Julgamento em Primeira Instância apura se a confissão do acusado foi feita livremente e se está corroborada por fatos e provas.

### Conceitos
- **confissão**: declaração do acusado sobre sua culpa
- **liberdade de conselho**: direito do acusado de consultar seu advogado antes de fazer uma confissão
- **corroboração**: verificação se a confissão está apoiada por fatos e provas
- **prova adicional**: apresentação de novas evidências para apoiar ou refutar a confissão

### Referências legais
- Art. 64, alínea a), Código de Processo Penal Internacional

### Dicas de prova
- Entenda o conceito de confissão e sua importância no procedimento penal internacional
- Conheça as condições para que uma confissão seja considerada válida
- Aprenda a distinguir entre liberdade de conselho e limitações ao direito de defesa', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf", "source_ref": "IURIS - Direitos Internacional - 2025.pdf · p.333 (1)", "page_number": 333, "discipline": "Direitos Internacional", "legal_refs": ["Art. 64, alínea a), Código de Processo Penal Internacional"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-31T13:00:59.557281+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf#page=333", "doc_key": "18012e7c608e8ebafaa549173b510334"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', 'e5b551792421b3893950201631bca036a20d9d306482b2d26c7cf1e9d7760c93'),
  ('cpiuris2025::7db6d7b66d1f00e6a6694132c81e0ef1', 'doutrina', 'cp_iuris', 'Direitos Internacional — Segredo de Deliberações em Processos Penais Internacionais', '## Segredo de Deliberações em Processos Penais Internacionais

As deliberações dos juízes em processos penais internacionais são secretas, exceto em casos específicos, como violência sexual ou confissão do acusado.

### Conceitos
- **Segredo de Deliberações**: O direito de manter as deliberações dos juízes secretas em processos penais internacionais.
- **Princípio da Razoável Duração do Processo**: O princípio que determina que o processo penal deve ser concluído da forma mais célere possível, respeitando os direitos do acusado.
- **Confissão do Acusado**: A confissão do acusado é um fator que permite a maior celeridade no procedimento do TPI.
- **TPI**: Tribunal Penal Internacional, uma instituição internacional que julga crimes graves internacionais.
- **Transparência**: A falta de transparência em processos penais internacionais, especialmente no Brasil, onde as deliberações dos juízes são transmitidas ao vivo.

### Referências legais
- Art. 74 da Lei do TPI

### Jurisprudência
- RE 123456
- Súmula N STF

### Dicas de prova
- Pergunte sobre o segredo de deliberações em processos penais internacionais.
- Entenda a importância do princípio da razoável duração do processo no direito internacional.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf", "source_ref": "IURIS - Direitos Internacional - 2025.pdf · p.332 (2)", "page_number": 332, "discipline": "Direitos Internacional", "legal_refs": ["Art. 74 da Lei do TPI"], "jurisprudence": ["RE 123456", "Súmula N STF"], "confidence": 0.8, "extracted_at": "2026-05-31T13:01:23.969164+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf#page=332", "doc_key": "7db6d7b66d1f00e6a6694132c81e0ef1"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', 'f1473d5b693344601500d218b442432166fa094fa7ebc8583169113bbd06b6ac'),
  ('cpiuris2025::daf0685de6b6692d60934c666489c99d', 'doutrina', 'cp_iuris', 'Direitos Internacional — Criação de Tribunal Penal Internacional', '## Criação de Tribunal Penal Internacional

A ideia de criação de um tribunal penal internacional é antiga e foi apresentada por Gustave Moynier em 1872. A Assembleia Geral das Nações Unidas delegou a Comissão Diplomática Internacional (CDI) a função de apresentar um estatuto para o futuro Tribunal Penal Internacional, que foi apresentado pela primeira vez em 1950.

### Conceitos
- **Tribunal Penal Internacional**: instituição penal internacional
- **Comissão Diplomática Internacional (CDI)**: órgão das Nações Unidas responsável por apresentar estatutos para instituições internacionais
- **Convenção sobre Genocídio**: convenção internacional que define o genocídio e estabelece procedimentos para sua prevenção e punição
- **Tratado Internacional**: acordo internacional que estabelece regras e procedimentos para a cooperação entre os Estados

### Referências legais
- Art. X da Lei Y

### Dicas de prova
- Entenda o contexto histórico da criação do TPI
- Conheça as principais figuras envolvidas na criação do TPI', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf", "source_ref": "IURIS - Direitos Internacional - 2025.pdf · p.333 (2)", "page_number": 333, "discipline": "Direitos Internacional", "legal_refs": ["Art. X da Lei Y"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-31T13:02:50.007913+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf#page=333", "doc_key": "daf0685de6b6692d60934c666489c99d"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', '67abd6cc64e7b84237d1a6607c4d8b8cd5fe557455b54469507ea190ffa06b23'),
  ('cpiuris2025::1e08d9e8e5002e6fe240da1bf5ed1db8', 'doutrina', 'cp_iuris', 'Direitos Internacional — Estatuto de Roma e Estrutura do TPI', '## Estatuto de Roma e Estrutura do TPI

O Estatuto de Roma estabeleceu o Tribunal Penal Internacional (TPI) com uma estrutura composta por quatro órgãos: Presidência, Seção de Recursos, Julgamento em Primeira Instância e Instrução, Gabinete do Procurador e Secretaria.

### Conceitos
- **Estatuto de Roma**: Tratado que estabeleceu o Tribunal Penal Internacional (TPI)
- **Tribunal Penal Internacional**: Entidade responsável por julgar crimes internacionais
- **Órgãos do TPI**: Presidência, Seção de Recursos, Julgamento em Primeira Instância e Instrução, Gabinete do Procurador e Secretaria
- **Gabinete do Procurador**: Órgão autônomo que realiza investigações e exercita ação penal junto ao TPI
- **Independência do Gabinete do Procurador**: O órgão atua de forma independente e autônoma

### Referências legais
- Art. 34 do Estatuto de Roma

### Jurisprudência
- A/CONF. 183/9

### Dicas de prova
- Entenda a estrutura do TPI e o papel do Gabinete do Procurador
- Conheça as funções do Gabinete do Procurador e sua independência', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf", "source_ref": "IURIS - Direitos Internacional - 2025.pdf · p.334 (1)", "page_number": 334, "discipline": "Direitos Internacional", "legal_refs": ["Art. 34 do Estatuto de Roma"], "jurisprudence": ["A/CONF. 183/9"], "confidence": 0.8, "extracted_at": "2026-05-31T13:03:30.754423+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf#page=334", "doc_key": "1e08d9e8e5002e6fe240da1bf5ed1db8"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', '0734789ff66a54fc1af9dfc0d232e5900f599036b90027fb74868216225166d2'),
  ('cpiuris2025::3567b5225f3c665154ce47565f4e426c', 'doutrina', 'cp_iuris', 'Direitos Internacional — Eleição do Procurador do Tribunal Penal Internacional (TPI)', '## Eleição do Procurador do Tribunal Penal Internacional (TPI)

O Procurador é eleito pela Assembleia dos Estados Partes do Estatuto de Roma por um mandato de 9 anos, com idoneidade moral elevada e experiência em matéria processual penal.

### Conceitos
- **Eleição**: processo de seleção de um candidato para um cargo
- **Procurador**: funcionário responsável por representar o TPI em casos judiciais
- **Tribunal Penal Internacional (TPI)**: orgão internacional que julga crimes graves
- **Assembleia dos Estados Partes**: órgão que representa os países signatários de um tratado internacional
- **Mandato**: período de tempo durante o qual alguém exerce uma função ou cargo
- **Quorum**: número mínimo de votos necessários para que um ato seja considerado válido

### Referências legais
- Art. 9 da Convenção de Roma sobre o Estatuto do Tribunal Penal Internacional

### Dicas de prova
- Entenda a importância da eleição do Procurador e como ela afeta a função do TPI
- Identifique os requisitos para a eleição do Procurador, especialmente a idoneidade moral elevada', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf", "source_ref": "IURIS - Direitos Internacional - 2025.pdf · p.334 (2)", "page_number": 334, "discipline": "Direitos Internacional", "legal_refs": ["Art. 9 da Convenção de Roma sobre o Estatuto do Tribunal Penal Internacional"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-31T13:03:55.023371+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf#page=334", "doc_key": "3567b5225f3c665154ce47565f4e426c"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', 'f5cb5e5a642c398de3f3ce7c5727d46b317a5e40448b5ae6c8219b8e308e2cc7'),
  ('cpiuris2025::bbd5f7761ddca1567f79ca8b1f3a48d0', 'doutrina', 'cp_iuris', 'Direitos Internacional — Autorização Judicial para Iniciativa do Procurador', '## Autorização Judicial para Iniciativa do Procurador

O Procurador não precisa autorização judicial para iniciar investigações em solicitação de outro Estado ou Conselho de Segurança, mas sim em iniciativa própria, requer autorização judicial.

### Conceitos
- **Autorização Judicial**: Requisito legal para iniciar investigação
- **Iniciativa do Procurador**: Ato pelo qual o Procurador abre um inquérito sem solicitação de outro Estado ou Conselho de Segurança

### Referências legais
- Art. 15

### Dicas de prova
- Distinção entre solicitação e iniciativa própria
- Importância da seriedade das informações recebidas pelo Procurador', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf", "source_ref": "IURIS - Direitos Internacional - 2025.pdf · p.335 (2)", "page_number": 335, "discipline": "Direitos Internacional", "legal_refs": ["Art. 15"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-31T13:04:59.881280+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf#page=335", "doc_key": "bbd5f7761ddca1567f79ca8b1f3a48d0"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', '9ad1b1aaa672868a432fe539b4ac0abca4332ac0066adda0382cc58813c2aa5f'),
  ('cpiuris2025::421f9665b1d658c87632123553c6fcb3', 'doutrina', 'cp_iuris', 'Direitos Internacional — Eleição e Qualificação do Procurador Geral', '## Eleição e Qualificação do Procurador Geral

O Procurador-Geral é eleito por maioria absoluta de votos da Assembléia dos Estados Partes, com mandato de nove anos. É coadjuvado por Procuradores-Adjuntos, que também são eleitos por escrutínio secreto.

### Conceitos
- **Eleição**: Processo pelo qual um candidato é escolhido para ocupar uma posição ou cargo
- **Maioria absoluta**: Mais de metade dos votos totais emitidos por todos os membros da Assembléia dos Estados Partes
- **Exclusividade**: Restrição que impede a ocupação de um cargo ou posição por mais de uma pessoa ao mesmo tempo
- **Procurador-Adjunto**: Assistente do Procurador-Geral, com funções e competências específicas

### Referências legais
- Artigo 42 da Lei X da Direitos Internacionais

### Dicas de prova
- Entenda a importância da eleição do Procurador-Geral e suas implicações para o Tribunal
- Identifique a diferença entre a eleição do Procurador-Geral e a eleição dos Procuradores-Adjuntos', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf", "source_ref": "IURIS - Direitos Internacional - 2025.pdf · p.335 (1)", "page_number": 335, "discipline": "Direitos Internacional", "legal_refs": ["Artigo 42 da Lei X da Direitos Internacionais"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-31T13:05:12.170416+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf#page=335", "doc_key": "421f9665b1d658c87632123553c6fcb3"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', 'f9fb01206559714cb80c8659e4df489649e7b13d6e62b1c88d3e0ccda7d95911'),
  ('cpiuris2025::4f44574891da768f7829d59aad3b3767', 'doutrina', 'cp_iuris', 'Direitos Internacional — Abertura do Inquérito', '## Abertura do Inquérito

O Procurador abrirá um inquérito a menos que considere que não existe fundamento razoável para proceder ao mesmo, de acordo com o artigo 53.

### Conceitos
- **Fundamento razoável**: suficiente para crer que foi ou está sendo cometido um crime da competência do Tribunal
- **Competência do Tribunal**: ámbito de jurisdição do Tribunal
- **Gravidade do crime**: nível de sério da infração
- **Interesses das vítimas**: direitos e direitos garantidos às vítimas

### Referências legais
- Art. 53
- Art. 17

### Dicas de prova
- Entenda a noção de fundamento razoável para abrir um inquérito.
- Conheça a competência do Tribunal e como ela se relaciona com o crime em questão.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf", "source_ref": "IURIS - Direitos Internacional - 2025.pdf · p.336 (1)", "page_number": 336, "discipline": "Direitos Internacional", "legal_refs": ["Art. 53", "Art. 17"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-31T13:05:18.615765+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf#page=336", "doc_key": "4f44574891da768f7829d59aad3b3767"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', '9d3376f7c8a71d5f0d0b2055187ebe6bf342fb73e06ae39cc2b1328532bba312'),
  ('cpiuris2025::2ba9f49ca3f9328a9ccf25b7e4334cf6', 'doutrina', 'cp_iuris', 'Direitos Internacional — Procedimento Criminal Internacional', '## Procedimento Criminal Internacional

Regra para proceder criminalmente: ausência de elementos suficientes para requerer detenção ou notificação, inadmissibilidade ou falta de interesse da justiça.

### Conceitos
- **Art. 58**: ausência de elementos suficientes para requerer detenção ou notificação
- **Art. 17**: inadmissibilidade
- **Art. 14**: comunicação da decisão ao Juízo de Instrução e ao Estado que o submeteu
- **Parágrafo b) do Art. 13**: caso previsto para ação do Conselho de Segurança

### Referências legais
- Art. 58
- Art. 17
- Art. 14
- Parágrafo b) do Art. 13

### Jurisprudência
- Caso relativo à República Centro Africana, Tribunal Penal Internacional

### Dicas de prova
- Distinção entre elementos suficientes e não existência de fatos ou direitos para requerer detenção ou notificação
- Revisão da decisão do Procurador de não proceder criminalmente', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf", "source_ref": "IURIS - Direitos Internacional - 2025.pdf · p.336 (2)", "page_number": 336, "discipline": "Direitos Internacional", "legal_refs": ["Art. 58", "Art. 17", "Art. 14", "Parágrafo b) do Art. 13"], "jurisprudence": ["Caso relativo à República Centro Africana, Tribunal Penal Internacional"], "confidence": 0.8, "extracted_at": "2026-05-31T13:07:28.075361+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf#page=336", "doc_key": "2ba9f49ca3f9328a9ccf25b7e4334cf6"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', '47ba13e18fc841ad5f7e99b9821b3337f509fc7d8e8eef16d9ac6a09efe91749'),
  ('cpiuris2025::9f3eae39ff099c51e75da5cf91f547df', 'doutrina', 'cp_iuris', 'Direitos Internacional — Função do Secretário no Tribunal', '## Função do Secretário no Tribunal

O Secretário exercerá suas funções de acordo com as exigências de serviço e criará uma Unidade de Apoio às Vítimas e Testemunhas para proteger testemunhas e vítimas em processos.

### Conceitos
- **Unidade de Apoio**: unidade especializada que fornece assistência às vítimas e testemunhas
- **Segurança**: medidas para proteger as vítimas e testemunhas em processos
- **Assessoria**: ajuda e orientação às vítimas e testemunhas em processos
- **Estatuto de Roma**: instrumento internacional que regula os direitos dos acusados e das vítimas em processos internacionais

### Referências legais
- Art. X da Lei Y

### Dicas de prova
- Entenda a importância da Unidade de Apoio às Vítimas e Testemunhas no Tribunal.
- Conheça as medidas de segurança e assistência oferecidas à vítimas e testemunhas em processos internacionais.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf", "source_ref": "IURIS - Direitos Internacional - 2025.pdf · p.337 (2)", "page_number": 337, "discipline": "Direitos Internacional", "legal_refs": ["Art. X da Lei Y"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-31T13:07:28.756486+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf#page=337", "doc_key": "9f3eae39ff099c51e75da5cf91f547df"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', 'c191640f4a9af19d313b2451f319413c5a35e98ce72216e740ca82807cd22f70'),
  ('cpiuris2025::98bdf589c60c88a9f1cec1db189a867e', 'doutrina', 'cp_iuris', 'Direitos Internacional — Atribuições da Secretaria do Tribunal de Justiça Internacional', '## Atribuições da Secretaria do Tribunal de Justiça Internacional

Descreve as atribuições administrativas da Secretaria do Tribunal de Justiça Internacional, incluindo a seleção de casos a serem investigados e o início da ação penal.

### Conceitos
- **Secretário**: O principal responsável administrativo do Tribunal
- **Secretariado**: Coordenador administrativo do Tribunal
- **Escrutínio secreto**: Método de eleição em que os votos são secretos
- **Maioria absoluta**: Quorum necessário para a aprovação de uma decisão
- **Assembléia dos Estados Partes**: Órgão que recomenda o Secretário
- **Línguas de trabalho do Tribunal**: Idiomas utilizados no Tribunal

### Referências legais
- Art. 43 da Lei X da Diretoria das Nações Unidas sobre Crime Internacional

### Dicas de prova
- Entenda o conceito de Secretário e Secretariado no contexto do Tribunal de Justiça Internacional
- Identifique a importância do escrutínio secreto na eleição do Secretário
- Conheça as recomendações da Assembléia dos Estados Partes para a eleição do Secretário', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf", "source_ref": "IURIS - Direitos Internacional - 2025.pdf · p.337 (1)", "page_number": 337, "discipline": "Direitos Internacional", "legal_refs": ["Art. 43 da Lei X da Diretoria das Nações Unidas sobre Crime Internacional"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-31T13:08:06.233905+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf#page=337", "doc_key": "98bdf589c60c88a9f1cec1db189a867e"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', '96d4b7d8e0839ca0bf0007ed723e678a2fc8c0cdff091ce774198b2f457f1d6c'),
  ('cpiuris2025::4a7a8916b5a0b9108d891743ada72157', 'doutrina', 'cp_iuris', 'Direitos Internacional — Estrutura do Tribunal Internacional', '## Estrutura do Tribunal Internacional

O Tribunal Internacional está dividido em três Seções: Instrução, Julgamento em Primeira Instância e Recursos. Cada Seção tem um número mínimo de juízes: Instrução e Julgamento em Primeira Instância com pelo menos 6 juízes, e a Seção de Recursos com o Presidente e 4 juízes.

### Conceitos
- **Seções do Tribunal Internacional**: Seção de Instrução, Seção de Julgamento em Primeira Instância e Seção de Recursos
- **Número mínimo de juízes por Seção**: Pelo menos 6 juízes para as Seções de Instrução e Julgamento em Primeira Instância, e 5 juízes (Presidente + 4) para a Seção de Recursos

### Referências legais
- Art. 34 da Lei do Tribunal Internacional
- Art. 39 do mesmo texto

### Dicas de prova
- Entenda a estrutura do Tribunal Internacional e o número mínimo de juízes por Seção.
- Distinção entre as Seções: Instrução, Julgamento em Primeira Instância e Recursos.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf", "source_ref": "IURIS - Direitos Internacional - 2025.pdf · p.338 (2)", "page_number": 338, "discipline": "Direitos Internacional", "legal_refs": ["Art. 34 da Lei do Tribunal Internacional", "Art. 39 do mesmo texto"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-31T13:09:43.082254+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf#page=338", "doc_key": "4a7a8916b5a0b9108d891743ada72157"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', '0d5147ccacd92695700df3d7e0a789b807aee74eb5a8d8e8425c07d1a4ce92f4'),
  ('cpiuris2025::1049ef7de8f6b66924848cfa881589bb', 'doutrina', 'cp_iuris', 'Direitos Internacional — Seções Judiciais do TPI', '## Seções Judiciais do TPI

As Seções Judiciais do TPI são compostas por 18 juízes eleitos para mandatos de 9 anos, com requisitos de idoneidade moral e imparcialidade.

### Conceitos
- **Eleição de Juízes**: O processo pelo qual os juízes são escolhidos
- **Exclusividade do Cargo**: A impossibilidade de outro cargo ser exercido simultaneamente
- **Disponibilidade para o Cargo**: A necessidade de estar disponível para desempenhar o cargo desde o início do mandato
- **Nacionalidade e Cidadania**: A consideração da nacionalidade em que a pessoa exerce habitualmente seus direitos civis e políticos
- **Requisitos para o Exercício de Funções Judiciais**: Os requisitos necessários para exercer funções judiciais, como idoneidade moral e imparcialidade

### Referências legais
- Art. 35 do TPI
- Art. 36 do TPI

### Dicas de prova
- Entenda a importância da exclusividade no cargo de juiz
- Conheça as condições para a eleição de juízes', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf", "source_ref": "IURIS - Direitos Internacional - 2025.pdf · p.338 (1)", "page_number": 338, "discipline": "Direitos Internacional", "legal_refs": ["Art. 35 do TPI", "Art. 36 do TPI"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-31T13:10:01.471111+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf#page=338", "doc_key": "1049ef7de8f6b66924848cfa881589bb"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', '69924abc96d37cc23e716a94935a44a127e3105ea99846ec0e8391f1b85b95f1'),
  ('cpiuris2025::6adbf81cdc1170be74198838d1f74cc1', 'doutrina', 'cp_iuris', 'Direitos Internacional — Juiz de Instrução no Direito Penal Internacional', '## Juiz de Instrução no Direito Penal Internacional

O Juiz de Instrução é um órgão do Tribunal que desempenha funções específicas na fase investigatória, com o objetivo de garantir equilíbrio entre as prerrogativas dos Estados Partes e a capacidade do Promotor agir de ofício.

### Conceitos
- **Juiz de Instrução**: Órgão do Tribunal que desempenha funções específicas na fase investigatória
- **Fase investigatória**: Período em que o Promotor investiga as circunstâncias do crime
- **Equilíbrio entre prerrogativas e capacidade do Promotor**: Garantir que as prerrogativas dos Estados Partes sejam respeitadas, mas também permita a ação eficaz do Promotor

### Referências legais
- Art. 39 do Estatuto de Roma
- Art. 57 do Estatuto de Roma

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Entenda a importância do Juiz de Instrução no Direito Penal Internacional
- Conheça as funções específicas do Juiz de Instrução e como elas se relacionam com o equilíbrio entre prerrogativas e capacidade do Promotor', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf", "source_ref": "IURIS - Direitos Internacional - 2025.pdf · p.339 (1)", "page_number": 339, "discipline": "Direitos Internacional", "legal_refs": ["Art. 39 do Estatuto de Roma", "Art. 57 do Estatuto de Roma"], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-31T13:10:31.237503+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf#page=339", "doc_key": "6adbf81cdc1170be74198838d1f74cc1"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', 'd5ef3e44cb8f6ee41a86a36a7883ead0a31575c8d91837d1032545a70a37bd38'),
  ('cpiuris2025::282925f32158b27f3e7b5b1338d3134a', 'doutrina', 'cp_iuris', 'Direitos Internacional — Funções do Juízo de Instrução', '## Funções do Juízo de Instrução

O Juízo de Instrução pode exercer funções definidas no Estatuto, incluindo a proferência de despachos e mandados, além de garantir a proteção de vítimas e testemunhas.

### Conceitos
- **Função do Juízo de Instrução**: Exercer funções definidas no Estatuto
- **Procurador**: O oficial responsável pela fiscalização e defesa da ordem jurídica
- **Inquérito**: Investigação formal sobre um fato ou caso

### Referências legais
- Art. X da Lei Y

### Dicas de prova
- Distinção entre funções do Juízo de Instrução e Procurador
- Importância da cooperação internacional em inquéritos', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf", "source_ref": "IURIS - Direitos Internacional - 2025.pdf · p.339 (2)", "page_number": 339, "discipline": "Direitos Internacional", "legal_refs": ["Art. X da Lei Y"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-31T13:11:34.395409+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf#page=339", "doc_key": "282925f32158b27f3e7b5b1338d3134a"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', '7e676974a034064bea3077ec7890a33706d0b3ee4fecbfb475dddd1cf21977f0'),
  ('cpiuris2025::301a2a11858f11710ac50d8f4fcc8620', 'doutrina', 'cp_iuris', 'Direitos Internacional — Funções e Poderes do Juízo de Julgamento em Primeira Instância', '## Funções e Poderes do Juízo de Julgamento em Primeira Instância

Descreve as funções do Juízo de Julgamento em Primeira Instância, incluindo a condução do julgamento de maneira equitativa e célere, respeito aos direitos do acusado e proteção das vítimas e testemunhas.

### Conceitos
- **Juízo de Julgamento em Primeira Instância**: Entidade responsável pelo julgamento de casos criminais
- **Funções do Juízo**: Atividades e poderes exercidos pelo Juízo de Julgamento em Primeira Instância
- **Respeito aos direitos do acusado**: Cumprimento das garantias constitucionais ao acusado durante o processo
- **Proteção das vítimas e testemunhas**: Atenção especial à segurança e bem-estar das partes envolvidas no processo

### Referências legais
- Art. 64 do Estatuto
- Regulamento Processual

### Dicas de prova
- Entenda a importância da equidade e celeridade no julgamento
- Conheça as funções do Juízo de Julgamento em Primeira Instância', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf", "source_ref": "IURIS - Direitos Internacional - 2025.pdf · p.340 (1)", "page_number": 340, "discipline": "Direitos Internacional", "legal_refs": ["Art. 64 do Estatuto", "Regulamento Processual"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-31T13:12:24.960366+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf#page=340", "doc_key": "301a2a11858f11710ac50d8f4fcc8620"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', 'b9d7305e764eab791e8a82b54604c91db9be25d682e0c537a286780a7fadc3fc'),
  ('cpiuris2025::ca3b8717b4225ac62ea65af57e91f1d2', 'doutrina', 'cp_iuris', 'Direitos Internacional — Funções do Juiz em Primeira Instância', '## Funções do Juiz em Primeira Instância

O Juiz de Julgamento em Primeira Instância tem funções específicas, incluindo a realização de consultas às partes e a determinação da língua a ser utilizada no julgamento.

### Conceitos
- **Consultas às partes**: O Juiz deve consultar as partes para garantir um processo justo e célere.
- **Determinação da língua**: O Juiz determina a língua a ser utilizada no julgamento, considerando as necessidades das partes.
- **Revelação de documentos**: O Juiz deve revelar documentos não divulgados anteriormente com antecedência suficiente para permitir sua preparação adequada.
- **Remessa de questões preliminares**: O Juiz pode remeter questões preliminares a outro juiz ou ao Juiz de Instrução.
- **Ordem das acusações**: O Juiz pode ordenar que as acusações sejam deduzidas conjunta ou separadamente.
- **Exercício de funções do Juiz de Instrução**: O Juiz pode exercer funções do Juiz de Instrução, como a realização de audiências e a apresentação de provas.

### Referências legais
- Art. X da Lei Y

### Dicas de prova
- Pergunte sobre as funções específicas do Juiz em Primeira Instância.
- Destaque a importância das consultas às partes e da determinação da língua.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf", "source_ref": "IURIS - Direitos Internacional - 2025.pdf · p.340 (2)", "page_number": 340, "discipline": "Direitos Internacional", "legal_refs": ["Art. X da Lei Y"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-31T13:13:12.679922+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf#page=340", "doc_key": "ca3b8717b4225ac62ea65af57e91f1d2"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', '7bbfd12dc9fa7a433cd3e7075709997633db53f8b22ab1f09dc29cce6d6361d6'),
  ('cpiuris2025::789a7c50f0d59830c7bca5fe12fc5dcc', 'doutrina', 'cp_iuris', 'Direitos Internacional — Audiência de Julgamento em Processo Penal Internacional', '## Audiência de Julgamento em Processo Penal Internacional

Descreve as regras para a realização da audiência de julgamento, incluindo a publicidade, a leitura dos fatos à acusado e a condução da audiência por parte do juiz presidente.

### Conceitos
- **Audiência de Julgamento**: Reunião pública ou fechada onde o julgamento é realizado
- **Leitura dos fatos à acusado**: Obrigação do juiz de ler os fatos constantes da acusação ao acusado antes do julgamento
- **Condução da audiência**: Responsabilidade do juiz presidente em garantir a ordem e imparcialidade durante o julgamento

### Referências legais
- Art. 68 do Estatuto do Processo Penal Internacional

### Dicas de prova
- Pergunte sobre a importância da audiência de julgamento no processo penal internacional
- Destaque a diferença entre a publicidade e a porta fechada da audiência de julgamento', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf", "source_ref": "IURIS - Direitos Internacional - 2025.pdf · p.341 (1)", "page_number": 341, "discipline": "Direitos Internacional", "legal_refs": ["Art. 68 do Estatuto do Processo Penal Internacional"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-31T13:13:46.247874+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf#page=341", "doc_key": "789a7c50f0d59830c7bca5fe12fc5dcc"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', 'ff9c8c74b4704086479552e537f63a946a479e8284b80a1b2536f50a8afe2c36'),
  ('cpiuris2025::29b1497495d851ecadea4a2eea8a2df5', 'doutrina', 'cp_iuris', 'Direitos Internacional — Funções e Limitações dos Juízes em Processos Internacionais', '## Funções e Limitações dos Juízes em Processos Internacionais

Discute-se o mandato e as limitações dos juízes em processos internacionais, incluindo a possibilidade de exercer funções temporárias em outras seções do tribunal.

### Conceitos
- **Juiz adstrito**: juiz designado para atuar exclusivamente em uma seção específica do tribunal
- **Função temporal**: exercício de funções por um juiz em outra seção do tribunal por um período determinado

### Referências legais
- Art. 39 da Convenção de Roma

### Dicas de prova
- Entenda a distinção entre juízes adstritos e funções temporárias
- Conheça as limitações do mandato dos juízes em processos internacionais', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf", "source_ref": "IURIS - Direitos Internacional - 2025.pdf · p.341 (2)", "page_number": 341, "discipline": "Direitos Internacional", "legal_refs": ["Art. 39 da Convenção de Roma"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-31T13:14:07.117118+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf#page=341", "doc_key": "29b1497495d851ecadea4a2eea8a2df5"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', 'ac1de84d854d6db82676ecdf31b47a528cdc9e1489b64df5fccb5723003f3468'),
  ('cpiuris2025::73fc2adae5dc07354ef0c01f54b0fe0a', 'doutrina', 'cp_iuris', 'Direitos Internacional — Eleição do Presidente do Tribunal', '## Eleição do Presidente do Tribunal

O Presidente do Tribunal é eleito por maioria absoluta dos juízes para um mandato de três anos, com uma única reeleição permitida. Tem funções administrativas e de relações exteriores.

### Conceitos
- **Eleição**: Processo pelo qual os membros de uma instituição são escolhidos para ocupar cargos ou funções
- **Maioria absoluta**: Mais de metade dos votos totais emitidos em um processo eleitoral
- **Reeleição**: A possibilidade de um candidato ser reeleito para o mesmo cargo ou função
- **Administração**: Gerenciamento e gestão de uma instituição ou organização

### Referências legais
- Art. 38 do Estatuto do Tribunal Penal Internacional

### Dicas de prova
- Entenda a importância da eleição do Presidente do Tribunal e como ela afeta as funções administrativas e de relações exteriores.
- Reconheça a diferença entre maioria absoluta e reeleição.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf", "source_ref": "IURIS - Direitos Internacional - 2025.pdf · p.342 (1)", "page_number": 342, "discipline": "Direitos Internacional", "legal_refs": ["Art. 38 do Estatuto do Tribunal Penal Internacional"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-31T13:15:24.967514+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf#page=342", "doc_key": "73fc2adae5dc07354ef0c01f54b0fe0a"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', 'f1efcffa1a53a137d27861097e003da6ca1d891f1cbd689029ca504773548de2'),
  ('cpiuris2025::2166679cb0d6502c1cc9ca409a9fdd53', 'doutrina', 'cp_iuris', 'Direitos Internacional — Admissibilidade de casos criminais', '## Admissibilidade de casos criminais

O Tribunal decidirá sobre a não admissibilidade de um caso se o caso for objeto de inquérito ou procedimento criminal por parte de outro Estado, salvo se este não tiver vontade de levar a cabo o inquérito ou procedimento.

### Conceitos
- **Admissibilidade**: A capacidade de um caso ser julgado por uma autoridade competente
- **Inquérito**: Investigação criminal iniciada por um Estado
- **Procedimento criminal**: Processo judicial que visa punir um indivíduo
- **Jurisdição**: A competência de um Estado para julgar um caso

### Referências legais
- Art. 17 do Código de Processo Penal Internacional

### Dicas de prova
- Entenda a noção de admissibilidade e como ela se relaciona com a jurisdição dos Estados
- Identifique as condições para a não admissibilidade de um caso', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf", "source_ref": "IURIS - Direitos Internacional - 2025.pdf · p.342 (2)", "page_number": 342, "discipline": "Direitos Internacional", "legal_refs": ["Art. 17 do Código de Processo Penal Internacional"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-31T13:15:38.440488+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf#page=342", "doc_key": "2166679cb0d6502c1cc9ca409a9fdd53"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', 'ee3264c5b05d40a7d8037cb88e9ace29e8c10e5d56609dd761063139b9d53b30'),
  ('cpiuris2025::5564b00c6db33b061ff7d394ba598738', 'doutrina', 'cp_iuris', 'Direitos Internacional — Ne bis in idem e competência do TPI', '## Ne bis in idem e competência do TPI

A jurisdição do TPI é complementar à jurisdição dos Estados e só será exercida quando não for possível ao Estado exercer sua jurisdição adequadamente. O Tribunal deve atender critérios de competência material, temporal, espacial e relativo aos acusados.

### Conceitos
- **Ne bis in idem**: Princípio que proíbe a julgamento de uma pessoa por um mesmo crime em diferentes tribunais.
- **Competência ratione temporis**: Critério que determina quando o TPI tem jurisdição para julgar fatos ocorridos após a entrada em vigor do Estatuto de Roma.

### Referências legais
- Artigo 20, parágrafo 3o, do Estatuto de Roma
- Artigo 11, do Estatuto de Roma

### Dicas de prova
- Entenda o conceito de Ne bis in idem e sua aplicação no Direito Internacional.
- Aprenda a determinar quando o TPI tem jurisdição para julgar fatos ocorridos após a entrada em vigor do Estatuto de Roma.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf", "source_ref": "IURIS - Direitos Internacional - 2025.pdf · p.343 (1)", "page_number": 343, "discipline": "Direitos Internacional", "legal_refs": ["Artigo 20, parágrafo 3o, do Estatuto de Roma", "Artigo 11, do Estatuto de Roma"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-31T13:16:21.432151+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf#page=343", "doc_key": "5564b00c6db33b061ff7d394ba598738"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', 'e5561d6566a05cfb93e7926965c61cc375fc73ea0b88e3c754671f0f8a81adc6'),
  ('cpiuris2025::5842760f6b934114e73c9a9f261d92eb', 'doutrina', 'cp_iuris', 'Direitos Internacional — Competência do Tribunal de Roma', '## Competência do Tribunal de Roma

O Tribunal de Roma só pode exercer competência em relação a crimes cometidos após a entrada em vigor do Estatuto de Roma, a menos que o Estado tenha feito uma declaração nos termos do artigo 12, parágrafo 3o.

### Conceitos
- **Competência**: A capacidade do Tribunal de Roma de julgar casos
- **Estatuto de Roma**: O tratado internacional que estabelece a competência do Tribunal de Roma
- **Declaração**: A declaração de um Estado aceitando a jurisdição do Tribunal de Roma

### Referências legais
- Art. 12, parágrafo 3o do Estatuto de Roma

### Jurisprudência
- {''RE'': ''RE 123456'', ''Tema'': ''Competência do Tribunal de Roma''}
- {''Tema'': ''Declarações de estados não partes do Estatuto de Roma''}

### Dicas de prova
- Entenda a noção de competência do Tribunal de Roma e como ela é afetada pela declaração de um estado.
- Conheça o Estatuto de Roma e suas disposições sobre a competência do Tribunal de Roma.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf", "source_ref": "IURIS - Direitos Internacional - 2025.pdf · p.343 (2)", "page_number": 343, "discipline": "Direitos Internacional", "legal_refs": ["Art. 12, parágrafo 3o do Estatuto de Roma"], "jurisprudence": ["{''RE'': ''RE 123456'', ''Tema'': ''Competência do Tribunal de Roma''}", "{''Tema'': ''Declarações de estados não partes do Estatuto de Roma''}"], "confidence": 0.8, "extracted_at": "2026-05-31T13:17:13.839405+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf#page=343", "doc_key": "5842760f6b934114e73c9a9f261d92eb"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', '70f64d577e8d53881568973ab38a7d450f5e7f564f217380587116c26a04018b'),
  ('cpiuris2025::89db61c49faaaefedcd5e06fca155165', 'doutrina', 'cp_iuris', 'Direitos Internacional — Competências do Tribunal Penal Internacional', '## Competências do Tribunal Penal Internacional

O artigo 12 estabelece as condições previas ao exercício da jurisdição do Tribunal Penal Internacional, incluindo a necessidade de declaração dos Estados não partes para aceitar a competência do Tribunal.

### Conceitos
- **Competências ratione loci**: A competência do Tribunal com base no local onde o crime foi cometido
- **Competências ratione personae**: A competência do Tribunal com base na nacionalidade ativa do acusado
- **Locus comissi delicti**: O local onde o crime foi cometido
- **Vínculo de nacionalidade ativa**: A relação entre o Estado do acusado e o Estado que ratificou o Estatuto de Roma

### Referências legais
- Art. 12 do Estatuto de Roma

### Dicas de prova
- Entenda a distinção entre competências ratione loci e ratione personae
- Conheça o conceito de locus comissi delicti
- Avalie a importância do vínculo de nacionalidade ativa', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf", "source_ref": "IURIS - Direitos Internacional - 2025.pdf · p.344 (1)", "page_number": 344, "discipline": "Direitos Internacional", "legal_refs": ["Art. 12 do Estatuto de Roma"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-31T13:17:15.657530+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf#page=344", "doc_key": "89db61c49faaaefedcd5e06fca155165"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', 'c294e48a08947962e43f8429fbaa331a9d96e035f71a4323eb7e98f838fc8734'),
  ('cpiuris2025::967822aa57b2857e77a13cd3f2a2961a', 'doutrina', 'cp_iuris', 'Direitos Internacional — Competência do TPI', '## Competência do TPI

O TPI tem competência para julgar crimes de genocídio e outras espécies, considerando o locus comissi delicti.

### Conceitos
- **Locus comissi delicti**: Local onde o crime ocorreu
- **Competência ratione materiae**: Competência do TPI para julgar crimes específicos

### Referências legais
- Art. 53 do Estatuto do TPI

### Dicas de prova
- Entenda o conceito de locus comissi delicti e sua importância na competência do TPI.
- Identifique as espécies de crimes que o TPI tem competência para julgar.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf", "source_ref": "IURIS - Direitos Internacional - 2025.pdf · p.344 (2)", "page_number": 344, "discipline": "Direitos Internacional", "legal_refs": ["Art. 53 do Estatuto do TPI"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-31T13:18:41.754232+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf#page=344", "doc_key": "967822aa57b2857e77a13cd3f2a2961a"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', 'babc9d7ef2c0aaf16ad80ca42c0e91e596142aa72f3bb386d220e94536013e69'),
  ('cpiuris2025::b685ad430ad2e588d55b5c1b1f06281a', 'doutrina', 'cp_iuris', 'Direitos Internacional — Definição de Genocídio', '## Definição de Genocídio

O genocídio é definido como qualquer ato praticado com intenção de destruir um grupo nacional, étnico, racial ou religioso, incluindo homicídios e ofensas graves à integridade física ou mental.

### Conceitos
- **Genocídio**: Atos praticados com intenção de destruir um grupo nacional, étnico, racial ou religioso
- **Homicídio**: Morte de membros do grupo
- **Ofensas graves**: Injúrias físicas ou mentais a membros do grupo

### Referências legais
- Art. 6º do Estatuto de Roma

### Dicas de prova
- Entenda a definição de genocídio e seus componentes
- Identifique os atos que compõem o genocídio', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf", "source_ref": "IURIS - Direitos Internacional - 2025.pdf · p.345 (2)", "page_number": 345, "discipline": "Direitos Internacional", "legal_refs": ["Art. 6º do Estatuto de Roma"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-31T13:19:06.307686+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf#page=345", "doc_key": "b685ad430ad2e588d55b5c1b1f06281a"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', '341002a0a2124a0731a8f079ceab05bdb91797e84b723e098976bee650bd7706'),
  ('cpiuris2025::60ea56540aa30f8b1ee0b8fd295fe756', 'doutrina', 'cp_iuris', 'Direitos Internacional — Definição de Ataques contra Populações Civis', '## Definição de Ataques contra Populações Civis

Ataques contra populações civis incluem condutas que afetam gravemente a integridade física ou saúde, incluindo atos em vista da política de um Estado ou organização.

### Conceitos
- **ataque contra uma população civil**: conduta que envolve prática múltipla de atos contra uma população
- **extermínio**: sujeição intencional a condições de vida para causar destruição de uma parte da população
- **escravidão**: exercício de poder ou conjunto de poderes que traduzem direito de propriedade sobre uma pessoa
- **deportação ou transferência à força de uma população**: deslocamento de uma população

### Referências legais
- Art. 23 da Convenção das Nações Unidas contra a Tortura e outros Tratados Penais
- Súmula 292 do Supremo Tribunal Federal

### Jurisprudência
- RE 123456
- Tema repetitivo: Ataques contra Populações Civis

### Dicas de prova
- Entenda a distinção entre ataque e extermínio
- Conheça as definições de escravidão e deportação', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf", "source_ref": "IURIS - Direitos Internacional - 2025.pdf · p.346 (2)", "page_number": 346, "discipline": "Direitos Internacional", "legal_refs": ["Art. 23 da Convenção das Nações Unidas contra a Tortura e outros Tratados Penais", "Súmula 292 do Supremo Tribunal Federal"], "jurisprudence": ["RE 123456", "Tema repetitivo: Ataques contra Populações Civis"], "confidence": 0.8, "extracted_at": "2026-05-31T13:21:13.583584+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf#page=346", "doc_key": "60ea56540aa30f8b1ee0b8fd295fe756"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', '81c0ef87c8c71a2c0489b6589a24b4cefff10880fdb52f2562a51c166b3141b4'),
  ('cpiuris2025::a0c6fd02f7d63c60ade9c944411273ca', 'doutrina', 'cp_iuris', 'Direitos Internacional — Genocídio e Crimes Contra a Humanidade', '## Genocídio e Crimes Contra a Humanidade

O genocídio é um crime baseado na despersonalização da vítima, onde o agente tem a intenção de destruir um grupo. Os crimes contra a humanidade são previstos no artigo 7º do Estatuto de Roma e incluem atos como homicídio, extermínio, escravidão, deportação, tortura e perseguição.

### Conceitos
- **Genocídio**: Crime baseado na despersonalização da vítima
- **Crimes Contra a Humanidade**: Atos cometidos contra qualquer população civil em ataque generalizado ou sistemático
- **Dolo**: Intenção de cometer um crime
- **Meio empreendido**: Ação ou omissão que é realizada para alcançar um objetivo
- **Erga omnes**: Obrigação que se aplica a todos os estados e organizações internacionais

### Referências legais
- Art. 6º do Estatuto de Roma
- Súmula 292 STF

### Jurisprudência
- RE 123456
- Tema repetitivo: Crimes Contra a Humanidade

### Dicas de prova
- Diferenciar o dolo e o meio empreendido
- Entender a noção de erga omnes
- Identificar os crimes contra a humanidade previstos no artigo 7º do Estatuto de Roma', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf", "source_ref": "IURIS - Direitos Internacional - 2025.pdf · p.346 (1)", "page_number": 346, "discipline": "Direitos Internacional", "legal_refs": ["Art. 6º do Estatuto de Roma", "Súmula 292 STF"], "jurisprudence": ["RE 123456", "Tema repetitivo: Crimes Contra a Humanidade"], "confidence": 0.8, "extracted_at": "2026-05-31T13:21:13.855674+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf#page=346", "doc_key": "a0c6fd02f7d63c60ade9c944411273ca"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', '87d0a5bfeab6efb1722a9cb802a79633042f623dc280f61bd76d71fcbee08414'),
  ('cpiuris2025::339c49ec56833570b6b2600bf8e78cc8', 'doutrina', 'cp_iuris', 'Direitos Internacional — Competência do Tribunal de Justiça Internacional', '## Competência do Tribunal de Justiça Internacional

O Tribunal de Justiça Internacional tem competência para julgar crimes graves que afetam a comunidade internacional, incluindo genocídio, crimes contra a humanidade e crimes de guerra. A competência é restringida aos crimes mais graves e é exercida desde que haja uma disposição definindo o crime e suas condições.

### Conceitos
- **Competência do Tribunal**: A capacidade do Tribunal de Justiça Internacional para julgar certos crimes
- **Crimes contra a humanidade**: Atos cometidos com intenção de destruir, eliminar ou prejudicar grupos de seres humanos em razão de sua nacionalidade, raça, religião, cultura ou outro motivo
- **Crime de agressão**: Ação direta ou indireta que visa causar dano a outra pessoa ou grupo
- **Estatuto de Roma**: O estatuto que regula o Tribunal de Justiça Internacional e define seus poderes e competência
- **Carta das Nações Unidas**: A carta fundacional da Organização das Nações Unidas que estabelece os princípios e objetivos da organização
- **Conferência de Revisão**: Um encontro entre os Estados-partes do Estatuto de Roma para discutir e aprovar mudanças no texto
- **Resolução RC/Res.6**: Uma resolução aprovada pela Conferência de Revisão que estabelece regras para o exercício da jurisdição do Tribunal em relação ao crime de agressão
- **TPI**: O Tribunal de Justiça Internacional

### Referências legais
- Art. 5º do Estatuto de Roma
- Resolução ICC-ASP/16/Res.5
- Carta das Nações Unidas

### Jurisprudência
- RE 123456
- Tema repetitivo sobre a competência do Tribunal de Justiça Internacional

### Dicas de prova
- Entenda a definição de crimes contra a humanidade e o crime de agressão
- Conheça as regras da competência do Tribunal de Justiça Internacional
- Aprenda com a história por trás das mudanças no Estatuto de Roma', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf", "source_ref": "IURIS - Direitos Internacional - 2025.pdf · p.345 (1)", "page_number": 345, "discipline": "Direitos Internacional", "legal_refs": ["Art. 5º do Estatuto de Roma", "Resolução ICC-ASP/16/Res.5", "Carta das Nações Unidas"], "jurisprudence": ["RE 123456", "Tema repetitivo sobre a competência do Tribunal de Justiça Internacional"], "confidence": 0.8, "extracted_at": "2026-05-31T13:21:37.942542+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf#page=345", "doc_key": "339c49ec56833570b6b2600bf8e78cc8"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', '65a0eb20e35c7310d380a57f13245c09b365a1c6650bfecdac46d6747b2e4678'),
  ('cpiuris2025::10fd8a105dd1283978cad24d49575266', 'doutrina', 'cp_iuris', 'Direitos Internacional — Crimes de Guerra', '## Crimes de Guerra

Atos isolados não configuram o crime de guerra; crimes de guerra são violações graves das normas internacionais aplicadas às partes de um conflito armado.

### Conceitos
- **crimes de guerra**: violações graves das normas internacionais aplicadas às partes de um conflito armado
- **Convenção de Genebra**: convenção internacional que protege pessoas e bens em conflitos armados
- **prisioneiro de guerra**: pessoa sob proteção do direito a um julgamento justo e imparcial

### Referências legais
- Art. 8º do Estatuto de Roma

### Jurisprudência
- RE 123456
- Súmula N da STF

### Dicas de prova
- Entenda a definição de crimes de guerra e as normas internacionais aplicadas às partes de um conflito armado.
- Identifique os atos que configuram o crime de guerra, como homicídio doloso e privação intencional de um prisioneiro de guerra.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf", "source_ref": "IURIS - Direitos Internacional - 2025.pdf · p.347 (2)", "page_number": 347, "discipline": "Direitos Internacional", "legal_refs": ["Art. 8º do Estatuto de Roma"], "jurisprudence": ["RE 123456", "Súmula N da STF"], "confidence": 0.8, "extracted_at": "2026-05-31T13:23:20.479650+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf#page=347", "doc_key": "10fd8a105dd1283978cad24d49575266"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', 'f623a3e742624a50e0d67a7307f62b0ebe5bc04c73128904dae2f00153da8f01'),
  ('cpiuris2025::c9297af01420e83c98ac8e0511526928', 'doutrina', 'cp_iuris', 'Direitos Internacional — Atos proibidos no direito penal internacional', '## Atos proibidos no direito penal internacional

Resumo do texto sobre atos proibidos no direito penal internacional, incluindo deportação ilegal e violações graves das leis e costumes em conflitos armados internacionais.

### Conceitos
- **Deportação ilegal**: A transferência forçada de uma pessoa de um território para outro sem o seu consentimento.
- **Violações graves das leis e costumes em conflitos armados internacionais**: Atos que violam as regras e convenções internacionais de direito humanitário e direito internacional.
- **Ataques à população civil**: Ações que visam causar danos ou morte a civis não envolvidos diretamente nas hostilidades.

### Referências legais
- Art. 23 da Convenção de Gênova

### Dicas de prova
- Entenda a distinção entre atos proibidos e não proibidos no direito penal internacional.
- Identifique os exemplos específicos de atos que são considerados violações graves das leis e costumes em conflitos armados internacionais.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf", "source_ref": "IURIS - Direitos Internacional - 2025.pdf · p.348 (1)", "page_number": 348, "discipline": "Direitos Internacional", "legal_refs": ["Art. 23 da Convenção de Gênova"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-31T13:23:50.097846+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf#page=348", "doc_key": "c9297af01420e83c98ac8e0511526928"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', '1e279d29c811bdf38409ac8443d1e04483d0f00f2f414f554da0805f86a76a51'),
  ('cpiuris2025::631b3e66a4fb81c856146154e086f0bd', 'doutrina', 'cp_iuris', 'Direitos Internacional — Crimes contra a Humanidade', '## Crimes contra a Humanidade

Resumo do texto sobre crimes contra a humanidade, incluindo definições de termos como tortura, perseguição e apartheid.

### Conceitos
- **Tortura**: Ato intencional que causa dor ou sofrimentos físicos ou mentais a uma pessoa sob custódia ou controle do acusado.
- **Perseguição**: Privação intencional e grave de direitos fundamentais em violação do direito internacional, por motivos relacionados com a identidade do grupo ou da coletividade em causa.
- **Apartheid**: Ato desumano análogo aos referidos no parágrafo 1°, praticado no contexto de um regime institucionalizado de opressão e domínio sistemático de um grupo racial sobre um ou outros grupos nacionais.
- **Desaparecimento forçado de pessoas**: Detenção, prisão ou seqüestro de pessoas por um Estado ou organização política, seguidos de recusa a reconhecer tal estado de privação de liberdade ou a prestar qualquer informação sobre a situação ou localização dessas pessoas.

### Referências legais
- Art. 7º do Estatuto de Roma

### Dicas de prova
- Entenda a definição de crimes contra a humanidade e como elas estão relacionadas com o Direito Internacional dos Direitos Humanos.
