  ('cpiuris2025::76570379b31e9cbee88a0f5cd8c764ed', 'doutrina', 'cp_iuris', 'Direitos Internacional — Violações graves do artigo 3o das Convenções de Genebra', '## Violações graves do artigo 3o das Convenções de Genebra

Descreve as violações graves do artigo 3o das Convenções de Genebra, incluindo atos de violência contra a vida e pessoa, ultrajes à dignidade da pessoa, tomada de reféns e condenações sem julgamento prévio.

### Conceitos
- **Convenções de Genebra**: Acordos internacionais que regulamentam o direito de guerra
- **Violação grave do artigo 3o**: Atos que violam a dignidade e a vida das pessoas, incluindo atos de violência, tortura e ultrajes à dignidade

### Referências legais
- Art. 3o das Convenções de Genebra

