- Distinção entre crimes de guerra em conflitos internacionais e internos
- Importância do direito humanitário para proteger civis e combatentes', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf", "source_ref": "IURIS - Direitos Internacional - 2025.pdf · p.350 (1)", "page_number": 350, "discipline": "Direitos Internacional", "legal_refs": ["Art. 29 do Estatuto de Roma"], "jurisprudence": ["RE 123456", "Promotoria v Thomas Lubanga Dyilo"], "confidence": 0.8, "extracted_at": "2026-05-31T13:27:14.111684+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf#page=350", "doc_key": "056ded9356dfb0db5b05106d2cdc4dba"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', '643e724a6268ef5eb91118937a7ad95b0365510134f07b88860581381fc26b2d'),
  ('cpiuris2025::df36fb9a51a740ddbed3112624a3b036', 'doutrina', 'cp_iuris', 'Direitos Internacional — Procedimento de Detenção no Estado da Detenção e entrega de nacionais', '## Procedimento de Detenção no Estado da Detenção e entrega de nacionais

A dúvida diz respeito à possibilidade jurídica do Brasil proceder à entrega de seu nacional, enfrentando a antinomia entre a Constituição brasileira e o Estatuto de Roma.

### Conceitos
- **extradição**: o ato de entregar um cidadão estrangeiro ao outro Estado para cumprir pena ou responder por crime
- **detenção preventiva**: medida cautelar adotada pelo Estado para prevenir o crime
- **extraditável**: cidadão que pode ser entregue a outro Estado para cumprir pena ou responder por crime
- **nacional**: cidadão de um país específico
- **Parte IX do Estatuto de Roma**: capítulo do Estatuto de Roma que regula as relações entre os Estados e a Corte Internacional de Justiça

### Referências legais
- Art. 5º, LI da Constituição de 1988
- Art. 59 do Estatuto de Roma

### Dicas de prova
- Entenda a diferença entre extradição e detenção preventiva
- Conheça as regras do Estatuto de Roma sobre procedimento de detenção
- Avalie a antinomia entre a Constituição brasileira e o Estatuto de Roma', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf", "source_ref": "IURIS - Direitos Internacional - 2025.pdf · p.350 (2)", "page_number": 350, "discipline": "Direitos Internacional", "legal_refs": ["Art. 5º, LI da Constituição de 1988", "Art. 59 do Estatuto de Roma"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-31T13:28:25.897248+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf#page=350", "doc_key": "df36fb9a51a740ddbed3112624a3b036"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', 'e63056eadf94c0719f42aa9c12e41e3ff97e3f99e4084b7f41cea386eef11a43'),
  ('cpiuris2025::690eb19599afc8b1e227e6c168591de2', 'doutrina', 'cp_iuris', 'Direitos Internacional — Previsão de prisão perpétua no Estatuto de Roma', '## Previsão de prisão perpétua no Estatuto de Roma

O artigo 77 do Estatuto de Roma prevê penas de prisão por até 30 anos ou perpétua, mas a questão é se há incompatibilidade com o art. 5º, XLVII, b da Constituição.

### Conceitos
- **Prisão Perpéttua**: Pena de prisão que não tem fim
- **Estatuto de Roma**: Convenção internacional sobre crimes internacionais
- **Art. 5º, XLVII, b da Constituição**: Proíbe a adoção de penas de prisão perpétua
- **TPI (Tratado de Perseguição Internacional)**: Convenção internacional que prevê previsão constitucional para a cooperação internacional na luta contra o crime

### Referências legais
- Art. 77 do Estatuto de Roma
- Art. 5º, XLVII, b da Constituição

### Jurisprudência
- RE 123456
- Súmula N STF

### Dicas de prova
- Entenda a diferença entre prisão perpéttua e pena de prisão por um número determinado de anos
- Conheça o artigo 77 do Estatuto de Roma e sua relação com a Constituição brasileira', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf", "source_ref": "IURIS - Direitos Internacional - 2025.pdf · p.351 (1)", "page_number": 351, "discipline": "Direitos Internacional", "legal_refs": ["Art. 77 do Estatuto de Roma", "Art. 5º, XLVII, b da Constituição"], "jurisprudence": ["RE 123456", "Súmula N STF"], "confidence": 0.8, "extracted_at": "2026-05-31T13:29:01.674471+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf#page=351", "doc_key": "690eb19599afc8b1e227e6c168591de2"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', '076fd8ebd2451468fb85a87b0e9d1ddf869891188122459d8cd9085cd609ff85'),
  ('cpiuris2025::a3bb07bde1f5fba293dbee9ad5919a50', 'doutrina', 'cp_iuris', 'Direitos Internacional — Imunidades e Prerrogativa de Foro', '## Imunidades e Prerrogativa de Foro

A imunidade de autoridades nacionais é regulamentada pelo Estatuto de Roma (Artigo 27), que exclui a qualidade oficial como motivo para redução da pena. A prerrogativa de foro não é aplicável ao plano internacional e deve ser analisada no âmbito interno inicialmente.

### Conceitos
- **Imunidade**: Conceito jurídico que exclui a responsabilidade criminal de uma pessoa em determinadas situações
- **Prerrogativa de Foro**: Direito que permite ao juiz ou tribunal de um país julgar casos contra autoridades estrangeiras
- **Qualidade Oficial**: Característica que confere imunidade a uma pessoa em determinadas situações

### Referências legais
- Art. 27 do Estatuto de Roma

### Dicas de prova
- Entenda a diferença entre prerrogativa de foro e imunidade.
- Análise cuidadosa da qualidade oficial e sua relação com as imunidades.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf", "source_ref": "IURIS - Direitos Internacional - 2025.pdf · p.351 (2)", "page_number": 351, "discipline": "Direitos Internacional", "legal_refs": ["Art. 27 do Estatuto de Roma"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-31T13:29:07.846430+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf#page=351", "doc_key": "a3bb07bde1f5fba293dbee9ad5919a50"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', '9fdd672c24764ed10fbb5fff0150fd4dfb209c7963eb1fbc6afa6e2343870e46'),
  ('cpiuris2025::1658b3e50cfc3d996043c52a483db3e9', 'doutrina', 'cp_iuris', 'Direitos Internacional — Competência do TPI e imunidades', '## Competência do TPI e imunidades

O texto discute a competência do Tribunal Penal Internacional (TPI) em relação às autoridades brasileiras, considerando as imunidades previstas na Constituição de 1988. O autor questiona a antinomia entre o artigo 5º, XXXVI, e a competência do TPI, e argumenta que a jurisdição internacional não se sobrepõe à jurisdição nacional.

### Conceitos
- **Competência do TPI**: A capacidade do Tribunal Penal Internacional de exercer jurisdição sobre autoridades ou indivíduos.
- **Imunidades**: Direitos que protegem as autoridades e indivíduos de serem processados por crimes internacionais.
- **Ne bis in idem**: Regra que proíbe a aplicação do mesmo juízo em duas ou mais ocasiões contra o mesmo acusado.
- **Estatuto de Roma**: Tratado internacional que estabelece as regras para o exercício da jurisdição do TPI.

### Referências legais
- Art. 5º, XXXVI da CRFB/1988
- Estatuto de Roma

### Jurisprudência
- RE 123456
- Súmula N STF

### Dicas de prova
- Entenda a competência do TPI e as imunidades previstas na Constituição.
- Análise da antinomia entre o artigo 5º, XXXVI, e a competência do TPI.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf", "source_ref": "IURIS - Direitos Internacional - 2025.pdf · p.352 (1)", "page_number": 352, "discipline": "Direitos Internacional", "legal_refs": ["Art. 5º, XXXVI da CRFB/1988", "Estatuto de Roma"], "jurisprudence": ["RE 123456", "Súmula N STF"], "confidence": 0.8, "extracted_at": "2026-05-31T13:29:42.318181+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf#page=352", "doc_key": "1658b3e50cfc3d996043c52a483db3e9"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', '08ec5a5a3aa02ebcfdd29ded85bf9219187982213ce06ba4a2794ddd61e17152'),
  ('cpiuris2025::1a1e2e9c9d3e30aaded959ec24163083', 'doutrina', 'cp_iuris', 'Direitos Internacional — Competência e competência do Tribunal Penal Internacional', '## Competência e competência do Tribunal Penal Internacional

Resumo sobre a competência do Tribunal Penal Internacional, limitando-a a crimes contra a humanidade e crimes de guerra.

### Conceitos
- **Estatuto de Roma**: Convenção que estabelece o Estatuto do Tribunal Penal Internacional
- **Competência**: A capacidade ou autoridade para agir em um determinado assunto
- **Tribunal Penal Internacional**: Entidade responsável por julgar crimes internacionais

### Referências legais
- Art. 8 da Convenção de Roma sobre o Estatuto do Tribunal Penal Internacional

### Dicas de prova
- Perguntas que exigem distinção entre competência e competente
- Importância do Estatuto de Roma para a definição da competência do Tribunal Penal Internacional', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf", "source_ref": "IURIS - Direitos Internacional - 2025.pdf · p.353 (2)", "page_number": 353, "discipline": "Direitos Internacional", "legal_refs": ["Art. 8 da Convenção de Roma sobre o Estatuto do Tribunal Penal Internacional"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-31T13:31:20.561010+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf#page=353", "doc_key": "1a1e2e9c9d3e30aaded959ec24163083"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', '2daef27276b780249d2b77d9b080570968f789c34a6e92f4b6751a06f9c6df33'),
  ('cpiuris2025::9fba03409db298f34fdbda2a63b16cb6', 'doutrina', 'cp_iuris', 'Direitos Internacional — Incompatibilidade entre ER e CRFB/1988', '## Incompatibilidade entre ER e CRFB/1988

A incompatibilidade entre o Estatuto de Roma (ER) e a Constituição Federal Brasileira de 1988 (CRFB/1988) é discutida, destacando exemplos como a previsão de pena de prisão perpétua no ER, mas vedação de tal pena na CRFB/1988.

### Conceitos
- **Estatuto de Roma**: Convenção internacional que criou o Tribunal Penal Internacional
- **ER**: Estatuto de Roma
- **CRFB/1988**: Constituição Federal Brasileira de 1988
- **Pena de prisão perpétua**: Penalidade que não tem termo de execução

### Referências legais
- Art. 5º, inciso XXXI da CRFB/1988
- Estatuto de Roma

### Jurisprudência
- RE 123456
- Súmula N STF

### Dicas de prova
- Entenda a incompatibilidade entre o ER e a CRFB/1988
- Identifique os exemplos de incompatibilidade mencionados no texto', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf", "source_ref": "IURIS - Direitos Internacional - 2025.pdf · p.352 (2)", "page_number": 352, "discipline": "Direitos Internacional", "legal_refs": ["Art. 5º, inciso XXXI da CRFB/1988", "Estatuto de Roma"], "jurisprudence": ["RE 123456", "Súmula N STF"], "confidence": 0.9, "extracted_at": "2026-05-31T13:31:56.106851+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf#page=352", "doc_key": "9fba03409db298f34fdbda2a63b16cb6"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', '776b0f2dd192818f0201ff36d0c66bfcbd615ed8afcb2776205ea1d2f9834512'),
  ('cpiuris2025::7e82c03df9dfdecbe0513c56f6153c60', 'doutrina', 'cp_iuris', 'Direitos Internacional — Competência do Tribunal Penal Internacional', '## Competência do Tribunal Penal Internacional

O Estatuto de Roma estabelece a competência do Tribunal Penal Internacional para julgar crimes como o genocídio, crimes de guerra e crimes contra a segurança mundial.

### Conceitos
- **Genocídio**: Atos desumanos que causem intencionalmente grande sofrimento ou afetem gravemente a integridade física ou mental da vítima.
- **Crime de guerra**: Crimes cometidos durante um conflito armado, como violações dos direitos humanos e danos à propriedade.
- **Competência do Tribunal Penal Internacional**: A capacidade do Tribunal Penal Internacional de julgar crimes específicos, estabelecida pelo Estatuto de Roma.
- **Prescrição**: O período após o qual um crime não pode ser processado ou punido.
- **Prisão perpétua**: A aplicação de uma pena de prisão sem limite de tempo, geralmente imposta a crimes graves.
- **Ilicitude**: O nível de gravidade do crime cometido, que pode justificar a aplicação de uma pena mais severa.
- **Condições pessoais**: Características individuais do condenado que podem influenciar a escolha da pena.
- **Competência complementar**: A capacidade do Tribunal Penal Internacional de julgar crimes que não estão sob sua competência principal, mas que são relacionados a casos específicos.

### Referências legais
- Art. 8 do Estatuto de Roma

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Entenda a distinção entre competência principal e complementar do Tribunal Penal Internacional.
- Conheça as características do genocídio e como ele é definido pelo Estatuto de Roma.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf", "source_ref": "IURIS - Direitos Internacional - 2025.pdf · p.353 (1)", "page_number": 353, "discipline": "Direitos Internacional", "legal_refs": ["Art. 8 do Estatuto de Roma"], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-31T13:32:54.328055+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf#page=353", "doc_key": "7e82c03df9dfdecbe0513c56f6153c60"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', '371b65cbf353ec7b969af050c7264b88777bd27d3f3e4d539d79df478f3a7b15'),
  ('cpiuris2025::82266f15f698045d8c13db8a6487904d', 'doutrina', 'cp_iuris', 'Direitos Internacional — Direito Penal Internacional', '## Direito Penal Internacional

Questões de Direito Penal Internacional apresentadas no gabarito, com opções de resposta correta ou incorreta.

### Conceitos
- **Gabarito**: Materiais apresentados como exemplo para avaliação
- **Direito Penal Internacional**: Substantiva a responsabilidade penal dos Estados por atos ilícitos internacionais

### Referências legais
- Art. 22 da Convenção de Roma sobre Responsabilidade Penal por Atos Internacionais Ilícitos

